{
  "name": "Gemini AI Discovery",
  "description": "An elegant and interactive chat application powered by Google's Gemini 3 Flash model, designed to showcase advanced AI capabilities with a world-class user interface."
}

export type Role = 'user' | 'assistant' | 'system';

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: Date;
}

export interface ChatState {
  messages: Message[];
  isThinking: boolean;
  error: string | null;
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";

// Initialization logic
const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
};

export const createChatSession = (): Chat => {
  const ai = getAIClient();
  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: '你是由 Google 训练的大语言模型，名字叫 Gemini。你会以专业、友善且知识渊博的方式回答用户。你的回答应包含对你身份的明确说明。',
      temperature: 0.7,
      topK: 40,
      topP: 0.95,
    },
  });
};

export const sendMessageToGemini = async (
  chat: Chat, 
  message: string
): Promise<string> => {
  try {
    const result = await chat.sendMessage({ message });
    return result.text || "对不起，我暂时无法生成回答。";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("请求失败，请稍后再试。");
  }
};

import React, { useEffect, useRef } from 'react';
import { Message } from '../types';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
}

const MessageList: React.FC<MessageListProps> = ({ messages, isThinking }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isThinking]);

  return (
    <div 
      ref={scrollRef}
      className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth"
    >
      {messages.length === 0 && (
        <div className="h-full flex flex-col items-center justify-center text-slate-500 space-y-4">
          <div className="w-16 h-16 rounded-full bg-slate-800/50 flex items-center justify-center border border-slate-700">
            <svg xmlns="http://www.w3.org/2000/svg" className="w-8 h-8 text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
            </svg>
          </div>
          <p className="text-lg font-medium">你好！我是 Gemini，很高兴为你服务。</p>
          <p className="text-sm">你可以问我任何问题，比如：“你是谁？”</p>
        </div>
      )}

      {messages.map((msg) => (
        <div 
          key={msg.id} 
          className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}
        >
          <div className={`max-w-[85%] md:max-w-[70%] rounded-2xl p-4 shadow-sm ${
            msg.role === 'user' 
              ? 'message-bubble-user text-white' 
              : 'message-bubble-ai text-slate-100'
          }`}>
            <div className="flex items-center mb-1 gap-2">
               <span className="text-[10px] font-bold uppercase tracking-wider opacity-60">
                {msg.role === 'user' ? 'YOU' : 'GEMINI'}
               </span>
               <span className="text-[10px] opacity-40">
                {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
               </span>
            </div>
            <div className="text-sm md:text-base leading-relaxed whitespace-pre-wrap">
              {msg.content}
            </div>
          </div>
        </div>
      ))}

      {isThinking && (
        <div className="flex justify-start animate-pulse">
          <div className="message-bubble-ai text-slate-100 max-w-[85%] md:max-w-[70%] rounded-2xl p-4 flex items-center gap-2">
            <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce"></div>
            <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce [animation-delay:-.3s]"></div>
            <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce [animation-delay:-.5s]"></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MessageList;

import React, { useState, FormEvent } from 'react';

interface ChatInputProps {
  onSendMessage: (message: string) => void;
  disabled: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, disabled }) => {
  const [input, setInput] = useState('');

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (input.trim() && !disabled) {
      onSendMessage(input.trim());
      setInput('');
    }
  };

  return (
    <div className="p-4 border-t border-slate-800 bg-slate-900/50 backdrop-blur-md">
      <form onSubmit={handleSubmit} className="max-w-4xl mx-auto flex gap-3 relative">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="给 Gemini 发送消息..."
          disabled={disabled}
          className="flex-1 bg-slate-800/50 border border-slate-700 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500/50 transition-all disabled:opacity-50"
        />
        <button
          type="submit"
          disabled={!input.trim() || disabled}
          className="bg-blue-600 hover:bg-blue-500 disabled:bg-slate-700 disabled:cursor-not-allowed text-white rounded-xl px-5 py-3 transition-colors flex items-center justify-center shadow-lg shadow-blue-900/20"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" />
          </svg>
        </button>
      </form>
      <p className="text-center text-[10px] text-slate-500 mt-2">
        Gemini 可能会显示不准确的信息，请验证其回答。
      </p>
    </div>
  );
};

export default ChatInput;

import React, { useState, useEffect, useRef } from 'react';
import { Message, ChatState } from './types';
import { createChatSession, sendMessageToGemini } from './services/geminiService';
import MessageList from './components/MessageList';
import ChatInput from './components/ChatInput';

const App: React.FC = () => {
  const [state, setState] = useState<ChatState>({
    messages: [],
    isThinking: false,
    error: null,
  });

  // Reference to persist chat session across renders
  const chatRef = useRef<any>(null);

  useEffect(() => {
    // Initialize session once
    chatRef.current = createChatSession();
  }, []);

  const handleSendMessage = async (content: string) => {
    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: new Date(),
    };

    setState(prev => ({
      ...prev,
      messages: [...prev.messages, userMessage],
      isThinking: true,
      error: null
    }));

    try {
      const response = await sendMessageToGemini(chatRef.current, content);

      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response,
        timestamp: new Date(),
      };

      setState(prev => ({
        ...prev,
        messages: [...prev.messages, assistantMessage],
        isThinking: false
      }));
    } catch (err: any) {
      setState(prev => ({
        ...prev,
        isThinking: false,
        error: err.message || "Something went wrong"
      }));
    }
  };

  const clearChat = () => {
    chatRef.current = createChatSession();
    setState({
      messages: [],
      isThinking: false,
      error: null
    });
  };

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-200">
      {/* Header */}
      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-xl z-10 sticky top-0">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-tr from-blue-600 to-indigo-400 flex items-center justify-center shadow-lg shadow-blue-500/20">
            <span className="text-white font-bold text-lg">G</span>
          </div>
          <div>
            <h1 className="font-semibold text-sm tracking-tight">Gemini AI</h1>
            <div className="flex items-center gap-1.5">
                <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                <span className="text-[10px] text-slate-400 font-medium uppercase tracking-widest">Online</span>
            </div>
          </div>
        </div>

        <button 
          onClick={clearChat}
          className="text-xs font-medium text-slate-400 hover:text-white transition-colors bg-slate-800/50 hover:bg-slate-700/50 px-3 py-1.5 rounded-lg border border-slate-700"
        >
          清空对话
        </button>
      </header>

      {/* Error Banner */}
      {state.error && (
        <div className="bg-red-500/10 border-b border-red-500/20 px-6 py-2 flex items-center justify-between">
          <p className="text-xs text-red-400">{state.error}</p>
          <button onClick={() => setState(prev => ({...prev, error: null}))}>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-red-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
      )}

      {/* Chat Area */}
      <main className="flex-1 overflow-hidden flex flex-col max-w-5xl mx-auto w-full">
        <MessageList messages={state.messages} isThinking={state.isThinking} />
      </main>

      {/* Input Area */}
      <ChatInput onSendMessage={handleSendMessage} disabled={state.isThinking} />
    </div>
  );
};

export default App;

import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";
import { Message } from "../types";

// Initialization logic
const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
};

/**
 * Maps our app's Message format to the Gemini API's expected history format.
 */
const mapHistory = (messages: Message[]) => {
  return messages.map(msg => ({
    role: msg.role === 'user' ? 'user' : 'model',
    parts: [{ text: msg.content }]
  }));
};

export const createChatSession = (history: Message[] = []): Chat => {
  const ai = getAIClient();
  return ai.chats.create({
    model: 'gemini-3-flash-preview',
    // Pass existing history to the model so it remembers past turns
    history: mapHistory(history),
    config: {
      systemInstruction: '你是由 Google 训练的大语言模型，名字叫 Gemini。你会以专业、友善且知识渊博的方式回答用户。你的回答应包含对你身份的明确说明。',
      temperature: 0.7,
      topK: 40,
      topP: 0.95,
    },
  });
};

