  chat: Chat, 
  message: string
): Promise<string> => {
  try {
    const result = await chat.sendMessage({ message });
    return result.text || "对不起，我暂时无法生成回答。";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("请求失败，请稍后再试。");
