{
  "name": "Gemini AI Discovery",
  "description": "An elegant and interactive chat application powered by Google's Gemini 3 Flash model, designed to showcase advanced AI capabilities with a world-class user interface.",
  "requestFramePermissions": [
    "camera"
  ]
}

export type Role = 'user' | 'assistant' | 'system';

export interface MessageImage {
  data: string; // Base64 string
  mimeType: string;
}

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: Date;
  image?: MessageImage;
}

export interface ChatState {
  messages: Message[];
  isThinking: boolean;
  error: string | null;
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Message } from "../types";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
};

/**
 * Maps our app's Message format to the Gemini API's expected contents format.
 * Includes image parts if present.
 */
const mapToContent = (messages: Message[]) => {
  return messages.map(msg => {
    const parts: any[] = [{ text: msg.content }];
    if (msg.image) {
      parts.push({
        inlineData: {
          data: msg.image.data,
          mimeType: msg.image.mimeType
        }
      });
    }
    return {
      role: msg.role === 'user' ? 'user' : 'model',
      parts
    };
  });
};

export const sendMessageToGemini = async (
  history: Message[],
  currentText: string,
  image?: { data: string; mimeType: string }
): Promise<string> => {
  const ai = getAIClient();

  // Construct the parts for the new message
  const newParts: any[] = [{ text: currentText }];
  if (image) {
    newParts.push({
      inlineData: {
        data: image.data,
        mimeType: image.mimeType
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...mapToContent(history),
        { role: 'user', parts: newParts }
      ],
      config: {
        systemInstruction: '你是由 Google 训练的大语言模型，名字叫 Gemini。你具有强大的视觉理解能力，可以分析用户发送的图片并回答相关问题。你的回答应专业且友善。',
        temperature: 0.7,
      },
    });

    return response.text || "对不起，我暂时无法生成回答。";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw new Error("分析失败，请检查图片格式或稍后再试。");
  }
};

