import React, { useState, useEffect } from 'react';
import { Message, ChatState } from './types';
import { sendMessageToGemini } from './services/geminiService';
import MessageList from './components/MessageList';
import ChatInput from './components/ChatInput';

const STORAGE_KEY = 'gemini_chat_history_v2'; // Bump version for image support

const App: React.FC = () => {
  const [state, setState] = useState<ChatState>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        return {
          messages: parsed.map((m: any) => ({
            ...m,
            timestamp: new Date(m.timestamp)
          })),
          isThinking: false,
          error: null
        };
      }
    } catch (e) {
      console.error("Failed to load history", e);
    }
    return {
      messages: [],
      isThinking: false,
      error: null,
    };
  });

  const [lastSaved, setLastSaved] = useState<Date | null>(null);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.messages));
    if (state.messages.length > 0) {
      setLastSaved(new Date());
    }
  }, [state.messages]);

  const handleSendMessage = async (content: string, image?: { data: string; mimeType: string }) => {
    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: new Date(),
      image
    };

    setState(prev => ({
      ...prev,
      messages: [...prev.messages, userMessage],
      isThinking: true,
      error: null
    }));

    try {
      // Pass the entire history and the new input to the service
      const response = await sendMessageToGemini(state.messages, content, image);

      const assistantMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response,
        timestamp: new Date(),
      };

      setState(prev => ({
        ...prev,
        messages: [...prev.messages, assistantMessage],
        isThinking: false
      }));
    } catch (err: any) {
      setState(prev => ({
        ...prev,
        isThinking: false,
        error: err.message || "分析请求失败，请稍后重试。"
      }));
    }
  };

  const clearChat = () => {
    localStorage.removeItem(STORAGE_KEY);
    setState({
      messages: [],
      isThinking: false,
      error: null
    });
    setLastSaved(null);
  };

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-200">
      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-xl z-10 sticky top-0">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-tr from-blue-600 to-indigo-400 flex items-center justify-center shadow-lg shadow-blue-500/20">
            <span className="text-white font-bold text-lg">G</span>
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="font-semibold text-sm tracking-tight">Gemini Vision</h1>
              {lastSaved && (
                <span className="text-[9px] text-slate-500 font-normal italic">
                  已保存 {lastSaved.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                </span>
              )}
            </div>
            <div className="flex items-center gap-1.5">
                <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                <span className="text-[10px] text-slate-400 font-medium uppercase tracking-widest">Multi-modal Active</span>
            </div>
          </div>
        </div>

        <button 
          onClick={clearChat}
          className="text-xs font-medium text-slate-400 hover:text-white transition-colors bg-slate-800/50 hover:bg-slate-700/50 px-3 py-1.5 rounded-lg border border-slate-700"
        >
          清空对话
        </button>
      </header>

      {state.error && (
        <div className="bg-red-500/10 border-b border-red-500/20 px-6 py-2 flex items-center justify-between">
          <p className="text-xs text-red-400 font-medium">{state.error}</p>
          <button onClick={() => setState(prev => ({...prev, error: null}))}>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-red-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
      )}

      <main className="flex-1 overflow-hidden flex flex-col max-w-5xl mx-auto w-full">
        <MessageList messages={state.messages} isThinking={state.isThinking} />
      </main>

      <ChatInput onSendMessage={handleSendMessage} disabled={state.isThinking} />
    </div>
  );
};

