export type Role = 'user' | 'assistant' | 'system';

export interface MessageMedia {
  data?: string; // Base64 for images/docs
  mimeType: string;
  url?: string; // For generated video/files
  fileName?: string;
}

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: Date;
  media?: MessageMedia;
  type?: 'text' | 'video_gen' | 'doc_analysis';
}

export interface ChatState {
  messages: Message[];
  isThinking: boolean;
  isGeneratingVideo: boolean;
  error: string | null;
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Message } from "../types";

// Note: Video generation requires its own instance with user-selected key
const getAIClient = (customKey?: string) => {
  return new GoogleGenAI({ apiKey: customKey || process.env.API_KEY || '' });
};

const mapToContent = (messages: Message[]) => {
  return messages.filter(m => m.type !== 'video_gen').map(msg => {
    const parts: any[] = [{ text: msg.content }];
    if (msg.media && msg.media.data) {
      parts.push({
        inlineData: {
          data: msg.media.data,
          mimeType: msg.media.mimeType
        }
      });
    }
    return {
      role: msg.role === 'user' ? 'user' : 'model',
      parts
    };
  });
};

export const sendMessageWithMedia = async (
  history: Message[],
  currentText: string,
  media?: { data: string; mimeType: string }
): Promise<string> => {
  const ai = getAIClient();
  const newParts: any[] = [{ text: currentText }];
  if (media) {
    newParts.push({
      inlineData: {
        data: media.data,
        mimeType: media.mimeType
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...mapToContent(history),
        { role: 'user', parts: newParts }
      ],
      config: {
        systemInstruction: '你是一个全能助手。你不仅能理解图片，还能深度阅读 PDF 文档并进行总结或分析。你的回答应直接且有深度。',
      },
    });
    return response.text || "未能获取有效回复。";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const generateVideo = async (prompt: string): Promise<string> => {
  // Use the latest key injected via process.env.API_KEY
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  let operation = await ai.models.generateVideos({
    model: 'veo-3.1-fast-generate-preview',
    prompt: prompt,
    config: {
      numberOfVideos: 1,
      resolution: '720p',
      aspectRatio: '16:9'
    }
  });

  // Polling for completion
  while (!operation.done) {
    await new Promise(resolve => setTimeout(resolve, 10000));
    operation = await ai.operations.getVideosOperation({ operation: operation });
  }

  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  if (!downloadLink) throw new Error("视频生成失败，未获取到下载链接。");

  // Fetch the actual MP4 bytes with the key
  const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
  const blob = await response.blob();
  return URL.createObjectURL(blob);
};

