            type="submit"
            disabled={(!input.trim() && !filePreview) || disabled}
            className={`rounded-xl px-5 py-3 transition-all flex items-center justify-center shadow-lg ${mode === 'video' ? 'bg-purple-600 hover:bg-purple-500 shadow-purple-900/20' : 'bg-blue-600 hover:bg-blue-500 shadow-blue-900/20'}`}
