const STORAGE_KEY = 'gemini_chat_history_v3';

declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

const App: React.FC = () => {
  const [state, setState] = useState<ChatState>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        return {
          messages: parsed.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
          isThinking: false,
          isGeneratingVideo: false,
          error: null
        };
      }
    } catch (e) {}
    return { messages: [], isThinking: false, isGeneratingVideo: false, error: null };
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.messages));
  }, [state.messages]);

  const handleSendMessage = async (content: string, media?: { data: string; mimeType: string; fileName?: string }) => {
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: new Date(),
      media,
      type: media?.mimeType.includes('pdf') ? 'doc_analysis' : 'text'
    };

    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isThinking: true, error: null }));

    try {
      const response = await sendMessageWithMedia(state.messages, content, media);
      const assistantMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response,
        timestamp: new Date(),
      };
      setState(prev => ({ ...prev, messages: [...prev.messages, assistantMsg], isThinking: false }));
