import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { Message } from "../types";

// Note: Removed the getAIClient helper. Instances must be created right before each API call.

/**
 * Maps message history to Gemini content parts.
 */
const mapToContent = (messages: Message[]) => {
  return messages.filter(m => m.type !== 'video_gen').map(msg => {
    const parts: any[] = [{ text: msg.content }];
    if (msg.media && msg.media.data) {
      parts.push({
        inlineData: {
          data: msg.media.data,
          mimeType: msg.media.mimeType
        }
      });
    }
    return {
      role: msg.role === 'user' ? 'user' : 'model',
      parts
    };
  });
};

/**
 * Sends a standard generateContent request.
 * Follows the guideline: new GoogleGenAI({ apiKey: process.env.API_KEY }) before each call.
 */
export const sendMessageWithMedia = async (
  history: Message[],
  currentText: string,
  media?: { data: string; mimeType: string }
): Promise<string> => {
  // Always initialize right before making an API call
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const newParts: any[] = [{ text: currentText }];
  if (media) {
    newParts.push({
      inlineData: {
        data: media.data,
        mimeType: media.mimeType
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...mapToContent(history),
        { role: 'user', parts: newParts }
      ],
      config: {
        systemInstruction: '你是一个全能助手。你不仅能理解图片，还能深度阅读 PDF 文档并进行总结或分析。你的回答应直接且有深度。',
      },
    });
    // The response.text is a getter, not a method.
    return response.text || "未能获取有效回复。";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

/**
 * Generates video using the Veo model.
 * Follows the guideline: new GoogleGenAI({ apiKey: process.env.API_KEY }) before each call.
 */
export const generateVideo = async (prompt: string): Promise<string> => {
  // Always initialize right before making an API call to ensure latest key is used.
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  let operation = await ai.models.generateVideos({
    model: 'veo-3.1-fast-generate-preview',
    prompt: prompt,
    config: {
      numberOfVideos: 1,
      resolution: '720p',
      aspectRatio: '16:9'
    }
  });

  // Polling for completion
  while (!operation.done) {
    await new Promise(resolve => setTimeout(resolve, 10000));
    operation = await ai.operations.getVideosOperation({ operation: operation });
  }

  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  if (!downloadLink) throw new Error("视频生成失败，未获取到下载链接。");

  // Fetch the actual MP4 bytes with the key appended to the URL.
  const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
  if (!response.ok) throw new Error("无法获取生成的视频文件。");

  const blob = await response.blob();
  return URL.createObjectURL(blob);
};

import React, { useState, FormEvent, useRef, ClipboardEvent } from 'react';

interface ChatInputProps {
  onSendMessage: (message: string, media?: { data: string; mimeType: string; fileName?: string }) => void;
  onGenerateVideo: (prompt: string) => void;
  disabled: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, onGenerateVideo, disabled }) => {
  const [input, setInput] = useState('');
  const [mode, setMode] = useState<'chat' | 'video'>('chat');
  const [filePreview, setFilePreview] = useState<{ data: string; mimeType: string; name: string } | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const val = input.trim();
    if (!val && !filePreview) return;

    if (mode === 'video') {
      onGenerateVideo(val || "生成一段精彩视频");
      setInput('');
    } else {
      onSendMessage(val || (filePreview?.mimeType.includes('pdf') ? "请分析这份文档" : "请分析这张图片"), filePreview || undefined);
      setInput('');
      setFilePreview(null);
    }
  };

  const processFile = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64Data = (reader.result as string).split(',')[1];
      setFilePreview({
        data: base64Data,
        mimeType: file.type,
        name: file.name || 'Pasted Image'
      });
    };
    reader.readAsDataURL(file);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      processFile(file);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handlePaste = (e: ClipboardEvent<HTMLInputElement>) => {
    const items = e.clipboardData.items;
    for (let i = 0; i < items.length; i++) {
      if (items[i].type.indexOf('image') !== -1) {
        const file = items[i].getAsFile();
        if (file) {
          processFile(file);
          // Optional: prevents text being pasted if it's just an image, 
          // but usually we want to allow mixed paste if available.
        }
      }
    }
  };

  return (
    <div className="p-4 border-t border-slate-800 bg-slate-900/80 backdrop-blur-xl">
      <div className="max-w-4xl mx-auto flex flex-col gap-3">

        {/* File Preview */}
        {filePreview && (
          <div className="flex items-center gap-3 p-2 bg-slate-800 rounded-xl border border-slate-700 w-fit animate-in fade-in slide-in-from-left-2 shadow-lg">
            <div className="w-10 h-10 bg-blue-600/20 rounded flex items-center justify-center text-blue-400 overflow-hidden">
              {filePreview.mimeType.includes('pdf') ? (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
                </svg>
              ) : (
                <img src={`data:${filePreview.mimeType};base64,${filePreview.data}`} className="w-full h-full object-cover" alt="Preview" />
              )}
            </div>
            <div className="flex flex-col">
              <span className="text-xs font-medium text-slate-200 truncate max-w-[150px]">{filePreview.name}</span>
              <span className="text-[10px] text-slate-500 uppercase tracking-tighter">{filePreview.mimeType.split('/')[1]}</span>
            </div>
            <button 
              onClick={() => setFilePreview(null)} 
              className="ml-2 p-1 text-slate-400 hover:text-red-400 transition-colors"
              type="button"
            >
               <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex gap-3 items-center">
          <input type="file" accept="image/*,.pdf" className="hidden" ref={fileInputRef} onChange={handleFileChange} />

          <div className="flex bg-slate-800 rounded-xl p-1 border border-slate-700 shadow-inner">
            <button 
              type="button"
              onClick={() => setMode('chat')}
              className={`p-2 rounded-lg transition-all ${mode === 'chat' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-white'}`}
              title="对话模式"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
              </svg>
            </button>
            <button 
              type="button"
              onClick={() => setMode('video')}
              className={`p-2 rounded-lg transition-all ${mode === 'video' ? 'bg-purple-600 text-white shadow-md' : 'text-slate-400 hover:text-white'}`}
              title="视频生成"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
              </svg>
            </button>
          </div>

          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={disabled || mode === 'video'}
            className="p-3 bg-slate-800/80 hover:bg-slate-700 text-slate-300 rounded-xl border border-slate-700 transition-all disabled:opacity-30 group"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
            </svg>
          </button>

          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onPaste={handlePaste}
            placeholder={mode === 'video' ? "描述你想生成的视频画面..." : "直接粘贴图片或文字..."}
            disabled={disabled}
            className={`flex-1 bg-slate-800/50 border border-slate-700 rounded-xl px-4 py-3 text-sm focus:outline-none transition-all ${mode === 'video' ? 'focus:ring-purple-500/50 focus:border-purple-500/50' : 'focus:ring-blue-500/50 focus:border-blue-500/50'}`}
          />

          <button
            type="submit"
            disabled={(!input.trim() && !filePreview) || disabled}
            className={`rounded-xl px-5 py-3 transition-all flex items-center justify-center shadow-lg active:scale-95 ${mode === 'video' ? 'bg-purple-600 hover:bg-purple-500 shadow-purple-900/20' : 'bg-blue-600 hover:bg-blue-500 shadow-blue-900/20'}`}
          >
            <span className="text-white font-medium">{mode === 'video' ? '生成视频' : '发送'}</span>
          </button>
        </form>
      </div>
    </div>
  );
};

export default ChatInput;

export type Role = 'user' | 'assistant' | 'system';

export interface MessageMedia {
  data?: string; // Base64 for images/docs
  mimeType: string;
  url?: string; // For generated video/files
  fileName?: string;
}

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: Date;
  mediaItems?: MessageMedia[]; // Changed from media to mediaItems array
  type?: 'text' | 'video_gen' | 'doc_analysis';
}

export interface ChatState {
  messages: Message[];
  isThinking: boolean;
  isGeneratingVideo: boolean;
  error: string | null;
}

import { GoogleGenAI } from "@google/genai";
import { Message, MessageMedia } from "../types";

/**
 * Maps message history to Gemini content parts.
 */
const mapToContent = (messages: Message[]) => {
  return messages.filter(m => m.type !== 'video_gen').map(msg => {
    const parts: any[] = [{ text: msg.content }];

    // Add all media items as separate parts
    if (msg.mediaItems && msg.mediaItems.length > 0) {
      msg.mediaItems.forEach(item => {
        if (item.data) {
          parts.push({
            inlineData: {
              data: item.data,
              mimeType: item.mimeType
            }
          });
        }
      });
    }

    return {
      role: msg.role === 'user' ? 'user' : 'model',
      parts
    };
  });
};

/**
 * Sends a standard generateContent request with support for multiple media items.
 */
export const sendMessageWithMedia = async (
  history: Message[],
  currentText: string,
  mediaItems?: MessageMedia[]
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const newParts: any[] = [{ text: currentText }];

  if (mediaItems && mediaItems.length > 0) {
    mediaItems.forEach(item => {
      if (item.data) {
        newParts.push({
          inlineData: {
            data: item.data,
            mimeType: item.mimeType
          }
        });
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...mapToContent(history),
        { role: 'user', parts: newParts }
      ],
      config: {
        systemInstruction: '你是一个全能助手。你支持多图识别和 PDF 深度研读。当用户发送多张图片时，请结合所有图片信息进行综合分析。你的回答应直接、专业且富有洞察力。',
      },
    });
    return response.text || "未能获取有效回复。";
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

/**
 * Generates video using the Veo model.
 */
export const generateVideo = async (prompt: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  let operation = await ai.models.generateVideos({
    model: 'veo-3.1-fast-generate-preview',
    prompt: prompt,
    config: {
      numberOfVideos: 1,
      resolution: '720p',
      aspectRatio: '16:9'
    }
  });

  while (!operation.done) {
    await new Promise(resolve => setTimeout(resolve, 10000));
    operation = await ai.operations.getVideosOperation({ operation: operation });
  }

  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  if (!downloadLink) throw new Error("视频生成失败，未获取到下载链接。");

  const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
  if (!response.ok) throw new Error("无法获取生成的视频文件。");

  const blob = await response.blob();
  return URL.createObjectURL(blob);
};

import React, { useState, FormEvent, useRef, ClipboardEvent } from 'react';
import { MessageMedia } from '../types';

interface ChatInputProps {
  onSendMessage: (message: string, media?: MessageMedia[]) => void;
  onGenerateVideo: (prompt: string) => void;
  disabled: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, onGenerateVideo, disabled }) => {
  const [input, setInput] = useState('');
  const [mode, setMode] = useState<'chat' | 'video'>('chat');
  const [previews, setPreviews] = useState<(MessageMedia & { id: string; name: string })[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const val = input.trim();
    if (!val && previews.length === 0) return;

    if (mode === 'video') {
      onGenerateVideo(val || "生成一段精彩视频");
      setInput('');
    } else {
      // If user just sends files without text, provide a default prompt
      const defaultText = previews.some(p => p.mimeType.includes('pdf')) 
        ? "请分析这些文档" 
        : "请分析这些图片";

      onSendMessage(val || defaultText, previews.length > 0 ? previews : undefined);
      setInput('');
      setPreviews([]);
    }
  };

  const processFiles = (files: FileList | File[]) => {
    const newFiles = Array.from(files);

    newFiles.forEach(file => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64Data = (reader.result as string).split(',')[1];
        const newPreview = {
          id: Math.random().toString(36).substr(2, 9),
          data: base64Data,
          mimeType: file.type,
          name: file.name || 'Pasted Image'
        };
        setPreviews(prev => [...prev, newPreview].slice(-20)); // Limit to 20 files
      };
      reader.readAsDataURL(file);
    });
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      processFiles(e.target.files);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handlePaste = (e: ClipboardEvent<HTMLInputElement>) => {
    const items = e.clipboardData.items;
    const filesToProcess: File[] = [];

    for (let i = 0; i < items.length; i++) {
      if (items[i].type.indexOf('image') !== -1 || items[i].type.indexOf('pdf') !== -1) {
        const file = items[i].getAsFile();
        if (file) {
          filesToProcess.push(file);
        }
      }
    }

    if (filesToProcess.length > 0) {
      processFiles(filesToProcess);
    }
  };

  const removePreview = (id: string) => {
    setPreviews(prev => prev.filter(p => p.id !== id));
  };

  return (
    <div className="p-4 border-t border-slate-800 bg-slate-900/80 backdrop-blur-xl">
      <div className="max-w-4xl mx-auto flex flex-col gap-3">

        {/* Scrollable File Preview List */}
        {previews.length > 0 && (
          <div className="flex gap-3 overflow-x-auto pb-2 scrollbar-hide animate-in fade-in slide-in-from-bottom-2">
            {previews.map((preview) => (
              <div key={preview.id} className="relative flex-shrink-0 group">
                <div className="w-16 h-16 bg-slate-800 rounded-xl border border-slate-700 overflow-hidden flex items-center justify-center shadow-md">
                  {preview.mimeType.includes('pdf') ? (
                    <div className="flex flex-col items-center">
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-red-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
                      </svg>
                    </div>
                  ) : (
                    <img src={`data:${preview.mimeType};base64,${preview.data}`} className="w-full h-full object-cover" alt="Preview" />
                  )}
                </div>
                <button 
                  onClick={() => removePreview(preview.id)} 
                  className="absolute -top-1.5 -right-1.5 bg-red-500 text-white rounded-full p-0.5 shadow-lg scale-0 group-hover:scale-100 transition-transform z-10"
                  type="button"
                >
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center pointer-events-none">
                   <span className="text-[8px] text-white font-bold truncate px-1 uppercase">{preview.mimeType.split('/')[1]}</span>
                </div>
              </div>
            ))}
            {previews.length > 0 && (
              <button 
                onClick={() => setPreviews([])}
                className="flex-shrink-0 w-16 h-16 border-2 border-dashed border-slate-700 rounded-xl flex flex-col items-center justify-center text-slate-500 hover:text-red-400 hover:border-red-400/50 transition-all"
              >
                <span className="text-[10px] font-bold">清除全部</span>
              </button>
            )}
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex gap-3 items-center">
          <input type="file" accept="image/*,.pdf" multiple className="hidden" ref={fileInputRef} onChange={handleFileChange} />

          <div className="flex bg-slate-800 rounded-xl p-1 border border-slate-700 shadow-inner">
            <button 
              type="button"
              onClick={() => setMode('chat')}
              className={`p-2 rounded-lg transition-all ${mode === 'chat' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-white'}`}
              title="对话模式"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
              </svg>
            </button>
            <button 
              type="button"
              onClick={() => setMode('video')}
              className={`p-2 rounded-lg transition-all ${mode === 'video' ? 'bg-purple-600 text-white shadow-md' : 'text-slate-400 hover:text-white'}`}
              title="视频生成"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
              </svg>
            </button>
          </div>

          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={disabled || mode === 'video'}
            className="p-3 bg-slate-800/80 hover:bg-slate-700 text-slate-300 rounded-xl border border-slate-700 transition-all disabled:opacity-30 group"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
            </svg>
          </button>

          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onPaste={handlePaste}
            placeholder={mode === 'video' ? "描述你想生成的视频画面..." : "输入文字或连续粘贴多张图片..."}
            disabled={disabled}
            className={`flex-1 bg-slate-800/50 border border-slate-700 rounded-xl px-4 py-3 text-sm focus:outline-none transition-all ${mode === 'video' ? 'focus:ring-purple-500/50 focus:border-purple-500/50' : 'focus:ring-blue-500/50 focus:border-blue-500/50'}`}
          />

          <button
            type="submit"
            disabled={(!input.trim() && previews.length === 0) || disabled}
            className={`rounded-xl px-5 py-3 transition-all flex items-center justify-center shadow-lg active:scale-95 ${mode === 'video' ? 'bg-purple-600 hover:bg-purple-500 shadow-purple-900/20' : 'bg-blue-600 hover:bg-blue-500 shadow-blue-900/20'}`}
          >
            <span className="text-white font-medium">
              {mode === 'video' ? '生成视频' : `发送 ${previews.length > 0 ? `(${previews.length})` : ''}`}
            </span>
          </button>
        </form>
      </div>
    </div>
  );
};

export default ChatInput;

