import { GoogleGenAI } from "@google/genai";
import { Message, MessageMedia } from "../types";

/**
 * Maps message history to Gemini content parts.
 * Ensures alternating roles and handles media items correctly.
 */
const mapToContent = (messages: Message[]) => {
  // We take all previous messages EXCEPT the very last one (which is handled as the current prompt)
  const history = messages.slice(0, -1);

  return history.map(msg => {
    const parts: any[] = [];

    // Always add text part if it exists
    if (msg.content) {
      parts.push({ text: msg.content });
    }

    // Add all media items as separate parts
    if (msg.mediaItems && msg.mediaItems.length > 0) {
      msg.mediaItems.forEach(item => {
        if (item.data) {
          parts.push({
            inlineData: {
              data: item.data,
              mimeType: item.mimeType
            }
          });
        }
      });
    }

    // Safety: If somehow a message has no content or media, add a placeholder to prevent API error
    if (parts.length === 0) {
      parts.push({ text: "..." });
    }

    return {
      role: msg.role === 'user' ? 'user' : 'model',
      parts
    };
  });
};

/**
 * Sends a standard generateContent request with enhanced history support.
 */
export const sendMessageWithMedia = async (
  fullHistory: Message[],
  currentText: string,
  mediaItems?: MessageMedia[]
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Construct the current turn parts
  const currentParts: any[] = [{ text: currentText }];
  if (mediaItems && mediaItems.length > 0) {
    mediaItems.forEach(item => {
      if (item.data) {
        currentParts.push({
          inlineData: {
            data: item.data,
            mimeType: item.mimeType
          }
        });
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...mapToContent(fullHistory),
        { role: 'user', parts: currentParts }
      ],
      config: {
        systemInstruction: `你是一个全能的 AI 助手。你拥有完整的对话记忆，能够识别并分析用户之前发送过的所有图片、文档和对话内容。
重要准则：
1. 始终关注上下文：如果用户提到了“之前那张图”或“上次那个问题”，请从历史记录中寻找线索。
2. 保持连贯性：你的语气应当像是一个一直陪伴在用户身边的伙伴。
3. 深度分析：支持多图识别和 PDF 深度研读。
4. 视频协助：你知道用户何时要求生成了视频，并能就视频内容进行讨论。`,
      },
    });

    return response.text || "未能获取有效回复。";
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

/**
 * Generates video using the Veo model.
 */
export const generateVideo = async (prompt: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  let operation = await ai.models.generateVideos({
    model: 'veo-3.1-fast-generate-preview',
    prompt: prompt,
    config: {
      numberOfVideos: 1,
      resolution: '720p',
      aspectRatio: '16:9'
    }
  });

  while (!operation.done) {
    await new Promise(resolve => setTimeout(resolve, 10000));
    operation = await ai.operations.getVideosOperation({ operation: operation });
  }

  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  if (!downloadLink) throw new Error("视频生成失败，未获取到下载链接。");

  const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
  if (!response.ok) throw new Error("无法获取生成的视频文件。");

  const blob = await response.blob();
  return URL.createObjectURL(blob);
};

import React, { useState, FormEvent, useRef, ClipboardEvent } from 'react';
import { MessageMedia } from '../types';

interface ChatInputProps {
  onSendMessage: (message: string, media?: MessageMedia[]) => void;
  onGenerateVideo: (prompt: string) => void;
  disabled: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, onGenerateVideo, disabled }) => {
  const [input, setInput] = useState('');
  const [mode, setMode] = useState<'chat' | 'video'>('chat');
  const [previews, setPreviews] = useState<(MessageMedia & { id: string; name: string })[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const val = input.trim();
    if (!val && previews.length === 0) return;

    if (mode === 'video') {
      onGenerateVideo(val || "生成一段精彩视频");
      setInput('');
    } else {
      const hasDocs = previews.some(p => !p.mimeType.includes('image'));
      const defaultText = hasDocs ? "请分析这些文档" : "请分析这些图片";

      onSendMessage(val || defaultText, previews.length > 0 ? previews : undefined);
      setInput('');
      setPreviews([]);
    }
  };

  const processFiles = (files: FileList | File[]) => {
    const newFiles = Array.from(files);

    newFiles.forEach(file => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64Data = (reader.result as string).split(',')[1];
        const newPreview = {
          id: Math.random().toString(36).substr(2, 9),
          data: base64Data,
          mimeType: file.type || 'application/octet-stream',
          name: file.name || 'Pasted File',
          fileName: file.name
        };
        setPreviews(prev => [...prev, newPreview].slice(-20)); // Limit to 20 files
      };
      reader.readAsDataURL(file);
    });
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      processFiles(e.target.files);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handlePaste = (e: ClipboardEvent<HTMLInputElement>) => {
    const items = e.clipboardData.items;
    const filesToProcess: File[] = [];

    for (let i = 0; i < items.length; i++) {
      // items[i].kind is 'file' for files copied from OS file explorer
      if (items[i].kind === 'file') {
        const file = items[i].getAsFile();
        if (file) {
          filesToProcess.push(file);
        }
      }
    }

    if (filesToProcess.length > 0) {
      processFiles(filesToProcess);
    }
  };

  const removePreview = (id: string) => {
    setPreviews(prev => prev.filter(p => p.id !== id));
  };

  return (
    <div className="p-4 border-t border-slate-800 bg-slate-900/80 backdrop-blur-xl">
      <div className="max-w-4xl mx-auto flex flex-col gap-3">

        {/* Scrollable File Preview List */}
        {previews.length > 0 && (
          <div className="flex gap-3 overflow-x-auto pb-2 scrollbar-hide animate-in fade-in slide-in-from-bottom-2">
            {previews.map((preview) => (
              <div key={preview.id} className="relative flex-shrink-0 group">
                <div className="w-16 h-16 bg-slate-800 rounded-xl border border-slate-700 overflow-hidden flex flex-col items-center justify-center shadow-md p-1">
                  {preview.mimeType.includes('image') ? (
                    <img src={`data:${preview.mimeType};base64,${preview.data}`} className="w-full h-full object-cover rounded-md" alt="Preview" />
                  ) : (
                    <div className="flex flex-col items-center justify-center">
                      <svg xmlns="http://www.w3.org/2000/svg" className={`h-8 w-8 ${preview.mimeType.includes('pdf') ? 'text-red-400' : 'text-blue-400'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                      </svg>
                      <span className="text-[7px] text-slate-400 truncate max-w-full mt-1 px-1">{preview.name}</span>
                    </div>
                  )}
                </div>
                <button 
                  onClick={() => removePreview(preview.id)} 
                  className="absolute -top-1.5 -right-1.5 bg-red-500 text-white rounded-full p-0.5 shadow-lg scale-0 group-hover:scale-100 transition-transform z-10"
                  type="button"
                >
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))}
            {previews.length > 0 && (
              <button 
                onClick={() => setPreviews([])}
                className="flex-shrink-0 w-16 h-16 border-2 border-dashed border-slate-700 rounded-xl flex flex-col items-center justify-center text-slate-500 hover:text-red-400 hover:border-red-400/50 transition-all"
              >
                <span className="text-[10px] font-bold">重置</span>
              </button>
            )}
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex gap-3 items-center">
          <input type="file" multiple className="hidden" ref={fileInputRef} onChange={handleFileChange} />

          <div className="flex bg-slate-800 rounded-xl p-1 border border-slate-700 shadow-inner">
            <button 
              type="button"
              onClick={() => setMode('chat')}
              className={`p-2 rounded-lg transition-all ${mode === 'chat' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-white'}`}
              title="对话模式"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
              </svg>
            </button>
            <button 
              type="button"
              onClick={() => setMode('video')}
              className={`p-2 rounded-lg transition-all ${mode === 'video' ? 'bg-purple-600 text-white shadow-md' : 'text-slate-400 hover:text-white'}`}
              title="视频生成"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
              </svg>
            </button>
          </div>

          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={disabled || mode === 'video'}
            className="p-3 bg-slate-800/80 hover:bg-slate-700 text-slate-300 rounded-xl border border-slate-700 transition-all disabled:opacity-30 group"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
            </svg>
          </button>

          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onPaste={handlePaste}
            placeholder={mode === 'video' ? "描述视频画面..." : "输入文字或直接粘贴任何文件 (WPS, LaTeX, etc)..."}
            disabled={disabled}
            className={`flex-1 bg-slate-800/50 border border-slate-700 rounded-xl px-4 py-3 text-sm focus:outline-none transition-all ${mode === 'video' ? 'focus:ring-purple-500/50 focus:border-purple-500/50' : 'focus:ring-blue-500/50 focus:border-blue-500/50'}`}
          />

          <button
            type="submit"
            disabled={(!input.trim() && previews.length === 0) || disabled}
            className={`rounded-xl px-5 py-3 transition-all flex items-center justify-center shadow-lg active:scale-95 ${mode === 'video' ? 'bg-purple-600 hover:bg-purple-500 shadow-purple-900/20' : 'bg-blue-600 hover:bg-blue-500 shadow-blue-900/20'}`}
          >
            <span className="text-white font-medium">
              {mode === 'video' ? '生成视频' : `发送 ${previews.length > 0 ? `(${previews.length})` : ''}`}
            </span>
          </button>
        </form>
      </div>
    </div>
  );
};

