import React, { useState, useEffect, useRef } from 'react';
import { Message, ChatState, MessageMedia } from './types';
import { sendMessageWithMedia, generateVideo } from './services/geminiService';
import MessageList from './components/MessageList';
import ChatInput from './components/ChatInput';

// Stable key to maintain history across app updates
const STORAGE_KEY = 'GEMINI_ULTIMATE_STABLE_STORAGE_V1';

const App: React.FC = () => {
  const [state, setState] = useState<ChatState>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        return {
          messages: parsed.map((m: any) => ({ 
            ...m, 
            timestamp: new Date(m.timestamp) 
          })),
          isThinking: false,
          isGeneratingVideo: false,
          error: null
        };
      }
    } catch (e) {
      console.warn("History restoration failed:", e);
    }
    return { messages: [], isThinking: false, isGeneratingVideo: false, error: null };
  });

  // Safe storage function with auto-pruning if space is full
  const saveHistorySafely = (messages: Message[]) => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(messages));
    } catch (e) {
      // If quota exceeded, remove the oldest 2 messages and try again
      if (e instanceof DOMException && (e.name === 'QuotaExceededError' || e.name === 'NS_ERROR_DOM_QUOTA_REACHED')) {
        if (messages.length > 2) {
          console.warn("Storage full, pruning oldest messages...");
          saveHistorySafely(messages.slice(2)); 
        }
      }
    }
  };

  // Sync state to local storage whenever messages change
  useEffect(() => {
    saveHistorySafely(state.messages);
  }, [state.messages]);

  const handleSendMessage = async (content: string, mediaItems?: MessageMedia[]) => {
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: new Date(),
      mediaItems,
      type: mediaItems?.some(m => m.mimeType.includes('pdf')) ? 'doc_analysis' : 'text'
    };

    const updatedMessages = [...state.messages, userMsg];
    setState(prev => ({ 
      ...prev, 
      messages: updatedMessages, 
      isThinking: true, 
      error: null 
    }));

    try {
      const response = await sendMessageWithMedia(updatedMessages, content, mediaItems);

      const assistantMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response,
        timestamp: new Date(),
      };

      setState(prev => ({ 
        ...prev, 
        messages: [...updatedMessages, assistantMsg], 
        isThinking: false 
      }));
    } catch (err: any) {
      console.error("Chat Error:", err);
      setState(prev => ({ 
        ...prev, 
        isThinking: false, 
        error: "回复失败。建议检查文件大小或重试。历史记录已自动保存。" 
      }));
    }
  };

  const handleGenerateVideo = async (prompt: string) => {
    try {
      if ((window as any).aistudio) {
        const hasKey = await (window as any).aistudio.hasSelectedApiKey();
        if (!hasKey) {
          await (window as any).aistudio.openSelectKey();
        }
      }

      const userMsg: Message = {
        id: Date.now().toString(),
        role: 'user',
        content: `请为我创作一段视频，主题是：${prompt}`,
        timestamp: new Date(),
        type: 'video_gen'
      };

      const updatedWithUser = [...state.messages, userMsg];
      setState(prev => ({ 
        ...prev, 
        messages: updatedWithUser, 
        isGeneratingVideo: true, 
        error: null 
      }));

      const videoUrl = await generateVideo(prompt);

      const assistantMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: `视频创作完成！场景描述："${prompt}"。您可以通过上方滚动查看之前的对话历史。`,
        timestamp: new Date(),
        mediaItems: [{ url: videoUrl, mimeType: 'video/mp4' }],
        type: 'video_gen'
      };

      setState(prev => ({ 
        ...prev, 
        messages: [...updatedWithUser, assistantMsg], 
        isGeneratingVideo: false 
      }));
    } catch (err: any) {
      console.error(err);
      setState(prev => ({ 
        ...prev, 
        isGeneratingVideo: false, 
        error: "视频生成失败，请确认 API Key 是否正确配置。" 
      }));
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-200">
      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-xl z-10 sticky top-0">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 flex items-center justify-center shadow-lg shadow-purple-500/20">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" viewBox="0 0 20 20" fill="currentColor">
              <path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM5 10a1 1 0 01-1 1H3a1 1 0 110-2h1a1 1 0 011 1zM8 16v-1a1 1 0 112 0v1a1 1 0 11-2 0zM13.536 15.657a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM6.464 14.95a1 1 0 11-1.414 1.414l-.707-.707a1 1 0 011.414-1.414l.707.707z" />
            </svg>
          </div>
          <div>
            <h1 className="font-bold text-sm bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">Gemini Omniverse</h1>
            <div className="flex items-center gap-1.5">
              <span className="w-2 h-2 bg-emerald-500 rounded-full shadow-[0_0_8px_rgba(16,185,129,0.5)]"></span>
              <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                历史已就绪 ({state.messages.length} 条记录)
              </span>
            </div>
          </div>
        </div>
        <div className="flex gap-2">
           <button 
             onClick={() => {
                if(confirm('警告：这将永久删除当前所有本地对话记忆，确定吗？')) {
                  setState(prev => ({ ...prev, messages: [] }));
                  localStorage.removeItem(STORAGE_KEY);
                }
             }} 
             className="text-[10px] uppercase font-bold text-slate-500 hover:text-red-400 bg-slate-800/50 px-3 py-1.5 rounded-md border border-slate-700/50 transition-all"
           >
             重置会话
           </button>
        </div>
      </header>

      {state.error && (
        <div className="bg-red-500/20 border-b border-red-500/50 px-6 py-3 flex items-center justify-between animate-in slide-in-from-top duration-300">
          <p className="text-xs text-red-300 font-medium">{state.error}</p>
          <button onClick={() => setState(prev => ({...prev, error: null}))} className="text-red-300 hover:text-white">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>
      )}

      <main className="flex-1 overflow-hidden flex flex-col max-w-5xl mx-auto w-full relative">
        <MessageList messages={state.messages} isThinking={state.isThinking} isGeneratingVideo={state.isGeneratingVideo} />

        {/* Memory status subtle indicator */}
        <div className="absolute bottom-4 right-4 pointer-events-none opacity-20 hover:opacity-100 transition-opacity">
           <div className="bg-slate-800 text-[8px] px-2 py-1 rounded border border-slate-700 font-mono">
             MEMORY SYNCED: OK
           </div>
        </div>
      </main>

      <ChatInput onSendMessage={handleSendMessage} onGenerateVideo={handleGenerateVideo} disabled={state.isThinking || state.isGeneratingVideo} />

      <div className="bg-slate-900 border-t border-slate-800/50 py-1.5 px-4 text-center">
        <p className="text-[9px] text-slate-500">
          对话内容将实时加密同步至本地存储，您可以随时向上翻阅。若存储空间不足，系统将自动循环优化旧记忆。
        </p>
      </div>
    </div>
  );
};

export default App;

export type Role = 'user' | 'assistant' | 'system';

export interface MessageMedia {
  data?: string; // Base64 for images/docs
  mimeType: string;
  url?: string; // For generated video/files
  fileName?: string;
  textContent?: string; // For text-based files like LaTeX, source code
}

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: Date;
  mediaItems?: MessageMedia[];
  type?: 'text' | 'video_gen' | 'doc_analysis';
}

export interface ChatState {
  messages: Message[];
  isThinking: boolean;
  isGeneratingVideo: boolean;
  error: string | null;
}

import React, { useState, FormEvent, useRef, ClipboardEvent } from 'react';
import { MessageMedia } from '../types';

interface ChatInputProps {
  onSendMessage: (message: string, media?: MessageMedia[]) => void;
  onGenerateVideo: (prompt: string) => void;
  disabled: boolean;
}

// Supported inlineData types for Gemini API
const SUPPORTED_MIME_TYPES = [
  'image/png', 'image/jpeg', 'image/webp', 'image/heic', 'image/heif',
  'application/pdf'
];

// Extensions that should be treated as plain text
const TEXT_EXTENSIONS = [
  'tex', 'txt', 'md', 'js', 'jsx', 'ts', 'tsx', 'py', 'java', 'c', 'cpp', 'h', 'css', 'html', 'json', 'xml', 'yaml', 'yml', 'sql'
];

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, onGenerateVideo, disabled }) => {
  const [input, setInput] = useState('');
  const [mode, setMode] = useState<'chat' | 'video'>('chat');
  const [previews, setPreviews] = useState<(MessageMedia & { id: string; name: string })[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const val = input.trim();
    if (!val && previews.length === 0) return;

    if (mode === 'video') {
      onGenerateVideo(val || "生成一段精彩视频");
      setInput('');
    } else {
      onSendMessage(val, previews.length > 0 ? previews : undefined);
      setInput('');
      setPreviews([]);
    }
  };

  const processFiles = (files: FileList | File[]) => {
    const newFiles = Array.from(files);

    newFiles.forEach(file => {
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      const isText = TEXT_EXTENSIONS.includes(extension) || file.type.startsWith('text/');
      const isSupportedMedia = SUPPORTED_MIME_TYPES.includes(file.type);

      const reader = new FileReader();

      if (isText) {
        // Handle text files (LaTeX, code, etc.)
        reader.onloadend = () => {
          const text = reader.result as string;
          const newPreview = {
            id: Math.random().toString(36).substr(2, 9),
            mimeType: 'text/plain',
            name: file.name,
            fileName: file.name,
            textContent: text
          };
          setPreviews(prev => [...prev, newPreview].slice(-20));
        };
        reader.readAsText(file);
      } else if (isSupportedMedia) {
        // Handle supported images/PDFs
        reader.onloadend = () => {
          const base64Data = (reader.result as string).split(',')[1];
          const newPreview = {
            id: Math.random().toString(36).substr(2, 9),
            data: base64Data,
            mimeType: file.type,
            name: file.name,
            fileName: file.name
          };
          setPreviews(prev => [...prev, newPreview].slice(-20));
        };
        reader.readAsDataURL(file);
      } else {
        // Unsupported binary files (like raw WPS)
        alert(`文件 "${file.name}" 的格式暂时无法直接解析。建议：\n1. 如果是文本文件，重命名为 .txt 后重新粘贴。\n2. 如果是 WPS 文档，请导出为 PDF 后粘贴。`);
      }
    });
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      processFiles(e.target.files);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handlePaste = (e: ClipboardEvent<HTMLInputElement>) => {
    const items = e.clipboardData.items;
    const filesToProcess: File[] = [];

    for (let i = 0; i < items.length; i++) {
      if (items[i].kind === 'file') {
        const file = items[i].getAsFile();
        if (file) {
          filesToProcess.push(file);
        }
      }
    }

    if (filesToProcess.length > 0) {
      processFiles(filesToProcess);
    }
  };

  const removePreview = (id: string) => {
    setPreviews(prev => prev.filter(p => p.id !== id));
  };

  return (
    <div className="p-4 border-t border-slate-800 bg-slate-900/80 backdrop-blur-xl">
      <div className="max-w-4xl mx-auto flex flex-col gap-3">
        {previews.length > 0 && (
          <div className="flex gap-3 overflow-x-auto pb-2 scrollbar-hide animate-in fade-in slide-in-from-bottom-2">
            {previews.map((preview) => (
              <div key={preview.id} className="relative flex-shrink-0 group">
                <div className="w-16 h-16 bg-slate-800 rounded-xl border border-slate-700 overflow-hidden flex flex-col items-center justify-center shadow-md p-1">
                  {preview.mimeType.includes('image') && preview.data ? (
                    <img src={`data:${preview.mimeType};base64,${preview.data}`} className="w-full h-full object-cover rounded-md" alt="Preview" />
                  ) : (
                    <div className="flex flex-col items-center justify-center">
                      <svg xmlns="http://www.w3.org/2000/svg" className={`h-8 w-8 ${preview.textContent ? 'text-emerald-400' : preview.mimeType.includes('pdf') ? 'text-red-400' : 'text-blue-400'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                      </svg>
                      <span className="text-[7px] text-slate-400 truncate max-w-full mt-1 px-1">{preview.name}</span>
                    </div>
                  )}
                </div>
                <button 
                  onClick={() => removePreview(preview.id)} 
                  className="absolute -top-1.5 -right-1.5 bg-red-500 text-white rounded-full p-0.5 shadow-lg scale-0 group-hover:scale-100 transition-transform z-10"
                  type="button"
                >
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))}
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex gap-3 items-center">
          <input type="file" multiple className="hidden" ref={fileInputRef} onChange={handleFileChange} />
          <div className="flex bg-slate-800 rounded-xl p-1 border border-slate-700 shadow-inner">
            <button type="button" onClick={() => setMode('chat')} className={`p-2 rounded-lg transition-all ${mode === 'chat' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-400 hover:text-white'}`} title="对话模式">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
            </button>
            <button type="button" onClick={() => setMode('video')} className={`p-2 rounded-lg transition-all ${mode === 'video' ? 'bg-purple-600 text-white shadow-md' : 'text-slate-400 hover:text-white'}`} title="视频生成">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
            </button>
          </div>
          <button type="button" onClick={() => fileInputRef.current?.click()} disabled={disabled || mode === 'video'} className="p-3 bg-slate-800/80 hover:bg-slate-700 text-slate-300 rounded-xl border border-slate-700 transition-all disabled:opacity-30 group">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          </button>
          <input type="text" value={input} onChange={(e) => setInput(e.target.value)} onPaste={handlePaste} placeholder={mode === 'video' ? "描述视频画面..." : "直接粘贴任何文件 (LaTeX, 代码, PDF, 图片)..."} disabled={disabled} className={`flex-1 bg-slate-800/50 border border-slate-700 rounded-xl px-4 py-3 text-sm focus:outline-none transition-all ${mode === 'video' ? 'focus:ring-purple-500/50 focus:border-purple-500/50' : 'focus:ring-blue-500/50 focus:border-blue-500/50'}`} />
          <button type="submit" disabled={(!input.trim() && previews.length === 0) || disabled} className={`rounded-xl px-5 py-3 transition-all flex items-center justify-center shadow-lg active:scale-95 ${mode === 'video' ? 'bg-purple-600 hover:bg-purple-500 shadow-purple-900/20' : 'bg-blue-600 hover:bg-blue-500 shadow-blue-900/20'}`}>
            <span className="text-white font-medium">{mode === 'video' ? '生成视频' : `发送 ${previews.length > 0 ? `(${previews.length})` : ''}`}</span>
          </button>
        </form>
      </div>
    </div>
  );
};

export default ChatInput;

import { GoogleGenAI } from "@google/genai";
import { Message, MessageMedia } from "../types";

const SUPPORTED_MIME_TYPES = [
  'image/png', 'image/jpeg', 'image/webp', 'image/heic', 'image/heif',
  'application/pdf'
];

/**
 * Maps message history to Gemini content parts.
 */
const mapToContent = (messages: Message[]) => {
  const history = messages.slice(0, -1);

  return history.map(msg => {
    const parts: any[] = [];

    // Aggregate text: actual message + any textContent from files
    let combinedText = msg.content || "";
    if (msg.mediaItems) {
      msg.mediaItems.forEach(item => {
        if (item.textContent) {
          combinedText += `\n\n--- 附件文件: ${item.fileName} ---\n${item.textContent}\n--- 结束 ---`;
        }
      });
    }

    if (combinedText.trim()) {
      parts.push({ text: combinedText });
    }

    // Add supported binary media (images/PDFs)
    if (msg.mediaItems) {
      msg.mediaItems.forEach(item => {
        if (item.data && SUPPORTED_MIME_TYPES.includes(item.mimeType)) {
          parts.push({
            inlineData: {
              data: item.data,
              mimeType: item.mimeType
            }
          });
        }
      });
    }

    if (parts.length === 0) parts.push({ text: "..." });

    return {
      role: msg.role === 'user' ? 'user' : 'model',
      parts
    };
  });
};

/**
 * Sends a standard generateContent request with enhanced history support.
 */
export const sendMessageWithMedia = async (
  fullHistory: Message[],
  currentText: string,
  mediaItems?: MessageMedia[]
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Construct current turn
  let finalPrompt = currentText;
  const currentParts: any[] = [];

  if (mediaItems) {
    mediaItems.forEach(item => {
      // If it's a text file (LaTeX, Code), put it in the prompt
      if (item.textContent) {
        finalPrompt += `\n\n--- 粘贴的文件内容: ${item.fileName} ---\n${item.textContent}\n--- 结束 ---`;
      }
      // If it's a supported binary file (Image/PDF), send as inlineData
      if (item.data && SUPPORTED_MIME_TYPES.includes(item.mimeType)) {
        currentParts.push({
          inlineData: {
            data: item.data,
            mimeType: item.mimeType
          }
        });
      }
    });
  }

  // Ensure there's at least one text part
  currentParts.unshift({ text: finalPrompt || "请分析我上传的文件。" });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...mapToContent(fullHistory),
        { role: 'user', parts: currentParts }
      ],
      config: {
        systemInstruction: `你是一个全能的 AI 助手。你拥有完整的对话记忆，并能处理用户粘贴的各种文件。
处理逻辑：
1. 文本/代码文件（如 LaTeX, .js, .py）：这些文件内容已直接附加在用户的 Prompt 中，请像阅读正文一样分析它们。
2. 图片/PDF：这些以多媒体部分发送，请进行视觉或文档解析。
3. 保持连贯：始终记得用户之前的提问和上传过的文件。`,
      },
    });

    return response.text || "未能获取有效回复。";
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

/**
 * Generates video using the Veo model.
 */
export const generateVideo = async (prompt: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  let operation = await ai.models.generateVideos({
    model: 'veo-3.1-fast-generate-preview',
    prompt: prompt,
    config: {
      numberOfVideos: 1,
      resolution: '720p',
      aspectRatio: '16:9'
    }
  });

  while (!operation.done) {
    await new Promise(resolve => setTimeout(resolve, 10000));
    operation = await ai.operations.getVideosOperation({ operation: operation });
  }

  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  if (!downloadLink) throw new Error("视频生成失败。");

  const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
  const blob = await response.blob();
  return URL.createObjectURL(blob);
};

import React, { useEffect, useRef } from 'react';
import { Message } from '../types';
import Markdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { atomDark } from 'react-syntax-highlighter/dist/esm/styles/prism';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  isGeneratingVideo: boolean;
}

const MessageList: React.FC<MessageListProps> = ({ messages, isThinking, isGeneratingVideo }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isThinking, isGeneratingVideo]);

  const handleDownloadFile = (content: string, language: string) => {
    const extensions: Record<string, string> = {
      'latex': 'tex',
      'tex': 'tex',
      'javascript': 'js',
      'typescript': 'ts',
      'python': 'py',
      'markdown': 'md',
      'html': 'html',
      'css': 'css',
      'json': 'json',
      'java': 'java',
      'cpp': 'cpp',
      'c': 'c'
    };

    const ext = extensions[language.toLowerCase()] || 'txt';
    const filename = `gemini_export_${Date.now()}.${ext}`;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth">
      {messages.length === 0 && !isGeneratingVideo && (
        <div className="h-full flex flex-col items-center justify-center text-slate-500 space-y-4">
          <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-blue-600 to-purple-600 flex items-center justify-center shadow-2xl">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" />
            </svg>
          </div>
          <h2 className="text-xl font-bold text-slate-200">Gemini Omniverse</h2>
          <p className="text-sm text-slate-500 text-center max-w-sm">
            支持 <b>万物下载</b>：生成 LaTeX、源码、文档并一键导出。
          </p>
        </div>
      )}

      {messages.map((msg) => (
        <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2`}>
          <div className={`max-w-[90%] md:max-w-[80%] rounded-2xl p-4 shadow-sm ${msg.role === 'user' ? 'message-bubble-user text-white' : 'message-bubble-ai text-slate-100'}`}>
            <div className="flex items-center mb-2 gap-2 opacity-60">
               <span className="text-[10px] font-bold uppercase tracking-wider">{msg.role === 'user' ? 'YOU' : 'GEMINI'}</span>
               <span className="text-[10px]">{msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
            </div>

            {msg.mediaItems && msg.mediaItems.length > 0 && (
              <div className={`grid gap-2 mb-3 ${msg.mediaItems.length === 1 ? 'grid-cols-1' : msg.mediaItems.length === 2 ? 'grid-cols-2' : 'grid-cols-2 md:grid-cols-3'}`}>
                {msg.mediaItems.map((item, idx) => (
                  <div key={idx} className="relative rounded-lg overflow-hidden border border-white/10 shadow-md">
                    {item.mimeType.includes('image') && item.data ? (
                      <img src={`data:${item.mimeType};base64,${item.data}`} className="w-full h-full object-cover max-h-48" alt="Attachment" />
                    ) : item.url && item.mimeType.includes('video') ? (
                      <video controls className="w-full bg-black" src={item.url} />
                    ) : (
                      <div className="flex items-center gap-3 p-3 bg-white/5 h-20 group hover:bg-white/10 transition-colors">
                        <div className="p-2 bg-slate-800 rounded-lg">
                           <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 ${item.mimeType.includes('pdf') ? 'text-red-400' : 'text-blue-400'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
