                        </div>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}

            <div className="markdown-content text-sm md:text-[15px] leading-relaxed">
              <Markdown remarkPlugins={[remarkGfm]} components={{
                code({node, inline, className, children, ...props}: any) {
                  const match = /language-(\w+)/.exec(className || '');
                  const lang = match ? match[1] : '';
                  const content = String(children).replace(/\n$/, '');

                  return !inline && match ? (
                    <div className="relative group/code my-4">
                      <div className="absolute right-2 top-2 z-10 flex gap-2 opacity-0 group-hover/code:opacity-100 transition-opacity">
                         <button 
                           onClick={() => handleDownloadFile(content, lang)}
                           className="bg-slate-800/80 hover:bg-blue-600 text-white text-[10px] px-2 py-1 rounded border border-white/10 backdrop-blur-sm flex items-center gap-1 transition-colors"
                           title="点击下载为文件"
                         >
                           <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                             <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                           </svg>
                           导出 .{lang === 'latex' ? 'tex' : lang}
                         </button>
                      </div>
                      <SyntaxHighlighter 
                        style={atomDark} 
                        language={lang} 
                        PreTag="div" 
                        {...props}
                      >
                        {content}
                      </SyntaxHighlighter>
                    </div>
                  ) : (
                    <code className={`${className} bg-slate-950/50 px-1.5 py-0.5 rounded text-blue-300 font-mono text-xs`} {...props}>
                      {children}
                    </code>
                  );
                }
              }}>{msg.content}</Markdown>
            </div>
          </div>
        </div>
      ))}

      {isGeneratingVideo && (
        <div className="flex flex-col items-center justify-center p-8 space-y-4 animate-in zoom-in-95 duration-700">
           <div className="relative">
              <div className="w-20 h-20 rounded-full border-4 border-purple-500/30 border-t-purple-500 animate-spin"></div>
              <div className="absolute inset-0 flex items-center justify-center">
                 <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-purple-400 animate-pulse" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" />
                 </svg>
              </div>
           </div>
           <div className="text-center">
             <p className="text-purple-400 font-bold tracking-widest text-sm uppercase">正在生成精彩视频...</p>
             <p className="text-[10px] text-slate-500 mt-1">这可能需要一分钟，请稍候。</p>
           </div>
        </div>
      )}

      {isThinking && !isGeneratingVideo && (
        <div className="flex justify-start animate-pulse">
          <div className="message-bubble-ai text-slate-100 p-4 rounded-2xl flex items-center gap-2">
            <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce"></div>
            <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce [animation-delay:-.3s]"></div>
            <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce [animation-delay:-.5s]"></div>
          </div>
        </div>
      )}
    </div>
  );
};

