import React, { useState, FormEvent, useRef, ClipboardEvent, useImperativeHandle, forwardRef } from 'react';
import { MessageMedia } from '../types';

interface ChatInputProps {
  onSendMessage: (message: string, media?: MessageMedia[]) => void;
  onGenerateVideo: (prompt: string) => void;
  disabled: boolean;
}

const SUPPORTED_MIME_TYPES = [
  'image/png', 'image/jpeg', 'image/webp', 'image/heic', 'image/heif',
  'application/pdf'
];

const TEXT_EXTENSIONS = [
  'tex', 'txt', 'md', 'js', 'jsx', 'ts', 'tsx', 'py', 'java', 'c', 'cpp', 'h', 'css', 'html', 'json', 'xml', 'yaml', 'yml', 'sql'
];

const ChatInput = forwardRef((props: ChatInputProps, ref) => {
  const { onSendMessage, onGenerateVideo, disabled } = props;
  const [input, setInput] = useState('');
  const [mode, setMode] = useState<'chat' | 'video'>('chat');
  const [previews, setPreviews] = useState<(MessageMedia & { id: string; name: string })[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // 公开给 App 组件的接口
  useImperativeHandle(ref, () => ({
    addFiles: (files: FileList | File[]) => {
      processFiles(files);
    }
  }));

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const val = input.trim();
    if (!val && previews.length === 0) return;

    if (mode === 'video') {
      onGenerateVideo(val || "一段科幻大片视频");
      setInput('');
    } else {
      onSendMessage(val, previews.length > 0 ? previews : undefined);
      setInput('');
      setPreviews([]);
    }
  };

  const processFiles = (files: FileList | File[]) => {
    const newFiles = Array.from(files);

    newFiles.forEach(file => {
      // 避免重复添加同名文件
      if (previews.some(p => p.name === file.name)) return;

      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      const isText = TEXT_EXTENSIONS.includes(extension) || file.type.startsWith('text/');
      const isSupportedMedia = SUPPORTED_MIME_TYPES.includes(file.type);

      const reader = new FileReader();

      if (isText) {
        reader.onloadend = () => {
          const text = reader.result as string;
          const newPreview = {
            id: Math.random().toString(36).substr(2, 9),
            mimeType: 'text/plain',
            name: file.name,
            fileName: file.name,
            textContent: text
          };
          setPreviews(prev => [...prev, newPreview].slice(-15));
        };
        reader.readAsText(file);
      } else if (isSupportedMedia) {
        reader.onloadend = () => {
          const base64Data = (reader.result as string).split(',')[1];
          const newPreview = {
            id: Math.random().toString(36).substr(2, 9),
            data: base64Data,
            mimeType: file.type,
            name: file.name,
            fileName: file.name
          };
          setPreviews(prev => [...prev, newPreview].slice(-15));
        };
        reader.readAsDataURL(file);
      }
    });
  };

  const handlePaste = (e: ClipboardEvent<HTMLInputElement>) => {
    const items = e.clipboardData.items;
    const filesToProcess: File[] = [];

    for (let i = 0; i < items.length; i++) {
      if (items[i].kind === 'file') {
        const file = items[i].getAsFile();
        if (file) filesToProcess.push(file);
      }
    }

    if (filesToProcess.length > 0) {
      processFiles(filesToProcess);
    }
  };

  return (
    <div className="p-4 border-t border-slate-800 bg-slate-900/80 backdrop-blur-xl relative">
      <div className="max-w-4xl mx-auto flex flex-col gap-3">
        {previews.length > 0 && (
          <div className="flex items-end gap-3 animate-in fade-in slide-in-from-bottom-2">
            <div className="flex-1 flex gap-3 overflow-x-auto pb-2 scrollbar-hide">
              {previews.map((preview) => (
                <div key={preview.id} className="relative flex-shrink-0 group">
                  <div className={`w-14 h-14 rounded-xl border border-slate-700 overflow-hidden flex flex-col items-center justify-center shadow-md p-1 ${preview.textContent ? 'bg-emerald-500/10' : 'bg-slate-800'}`}>
                    {preview.mimeType.includes('image') && preview.data ? (
                      <img src={`data:${preview.mimeType};base64,${preview.data}`} className="w-full h-full object-cover rounded-md" alt="Preview" />
                    ) : (
                      <div className="flex flex-col items-center">
                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 ${preview.textContent ? 'text-emerald-400' : preview.mimeType.includes('pdf') ? 'text-red-400' : 'text-blue-400'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                        </svg>
                        <span className="text-[6px] text-slate-500 truncate max-w-[40px] mt-1">{preview.name}</span>
                      </div>
                    )}
                  </div>
                  <button onClick={() => setPreviews(p => p.filter(x => x.id !== preview.id))} className="absolute -top-1.5 -right-1.5 bg-red-500 text-white rounded-full p-0.5 shadow-lg scale-0 group-hover:scale-100 transition-transform">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M6 18L18 6M6 6l12 12" /></svg>
                  </button>
                </div>
              ))}
            </div>
            <button 
              onClick={() => setPreviews([])} 
              className="mb-2 text-[9px] font-bold text-slate-500 hover:text-slate-300 uppercase tracking-tighter"
            >
              清空全部
            </button>
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex gap-3 items-center">
          <input type="file" multiple className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && processFiles(e.target.files)} />
          <div className="flex bg-slate-800 rounded-xl p-1 border border-slate-700 shadow-inner">
            <button type="button" onClick={() => setMode('chat')} className={`p-2 rounded-lg transition-all ${mode === 'chat' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
            </button>
            <button type="button" onClick={() => setMode('video')} className={`p-2 rounded-lg transition-all ${mode === 'video' ? 'bg-purple-600 text-white' : 'text-slate-400 hover:text-white'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
            </button>
          </div>
          <button type="button" onClick={() => fileInputRef.current?.click()} disabled={disabled || mode === 'video'} className="p-3 bg-slate-800/80 hover:bg-slate-700 text-slate-300 rounded-xl border border-slate-700 disabled:opacity-30">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M12 4v16m8-8H4" /></svg>
          </button>
          <input 
            type="text" 
            value={input} 
            onChange={(e) => setInput(e.target.value)} 
            onPaste={handlePaste} 
            placeholder={mode === 'video' ? "描述视频..." : "直接拖入或粘贴多个文件..."} 
            disabled={disabled} 
            className="flex-1 bg-slate-800/50 border border-slate-700 rounded-xl px-4 py-3 text-sm focus:outline-none" 
          />
          <button type="submit" disabled={(!input.trim() && previews.length === 0) || disabled} className={`rounded-xl px-5 py-3 transition-all ${mode === 'video' ? 'bg-purple-600 hover:bg-purple-500' : 'bg-blue-600 hover:bg-blue-500'} text-white font-medium`}>
            {mode === 'video' ? '生成' : `发送 ${previews.length > 0 ? `(${previews.length})` : ''}`}
          </button>
        </form>
      </div>
    </div>
  );
});

