import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Message, ChatState, MessageMedia } from './types';
import { sendMessageWithMedia, generateVideo } from './services/geminiService';
import MessageList from './components/MessageList';
import ChatInput from './components/ChatInput';

const STORAGE_KEY = 'GEMINI_OMNIVERSE_STABLE_V1';

const App: React.FC = () => {
  const [state, setState] = useState<ChatState>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        const parsed = JSON.parse(savedData);
        if (Array.isArray(parsed)) {
          return {
            messages: parsed.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
            isThinking: false,
            isGeneratingVideo: false,
            error: null
          };
        }
      }
    } catch (e) { console.error("Load error", e); }
    return { messages: [], isThinking: false, isGeneratingVideo: false, error: null };
  });

  const [isDragging, setIsDragging] = useState(false);
  const isInitialMount = useRef(true);
  const chatInputRef = useRef<{ addFiles: (files: FileList | File[]) => void } | null>(null);

  // 计算存储使用率 (假设上限 5MB)
  const storageUsage = useMemo(() => {
    const str = JSON.stringify(state.messages);
    const bytes = new Blob([str]).size;
    const limit = 5 * 1024 * 1024; // 5MB
    return Math.min(100, Math.round((bytes / limit) * 100));
  }, [state.messages]);

  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
      return;
    }
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.messages));
  }, [state.messages]);

  const handleDeleteMessage = (id: string) => {
    setState(prev => ({
      ...prev,
      messages: prev.messages.filter(m => m.id !== id)
    }));
  };

  const clearAllHistory = () => {
    setState(prev => ({ ...prev, messages: [] }));
    localStorage.removeItem(STORAGE_KEY);
  };

  const handleSendMessage = async (content: string, mediaItems?: MessageMedia[]) => {
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: new Date(),
      mediaItems,
      type: mediaItems?.some(m => m.mimeType.includes('pdf')) ? 'doc_analysis' : 'text'
    };

    const updatedMessages = [...state.messages, userMsg];
    setState(prev => ({ ...prev, messages: updatedMessages, isThinking: true, error: null }));

    try {
      const response = await sendMessageWithMedia(updatedMessages, content, mediaItems);

      // 处理函数调用
      if (response.functionCalls) {
        for (const call of response.functionCalls) {
          if (call.name === 'clear_all_history') {
            clearAllHistory();
            return; // 已经清空，无需继续
          }
          if (call.name === 'delete_last_n_messages') {
            const count = call.args.count || 2;
            setState(prev => ({
              ...prev,
              messages: prev.messages.slice(0, -count),
              isThinking: false
            }));
            return;
          }
        }
      }

      const assistantMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "已完成您的请求。",
        timestamp: new Date(),
      };
      setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isThinking: false }));
    } catch (err: any) {
      setState(prev => ({ ...prev, isThinking: false, error: "服务响应异常。" }));
    }
  };

  const handleGenerateVideo = async (prompt: string) => {
    // ... 原有逻辑保持不变
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: `生成视频：${prompt}`, timestamp: new Date(), type: 'video_gen' };
    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isGeneratingVideo: true }));
    try {
      const url = await generateVideo(prompt);
      const assistantMsg: Message = { id: (Date.now() + 1).toString(), role: 'assistant', content: '视频已生成', timestamp: new Date(), mediaItems: [{url, mimeType: 'video/mp4'}], type: 'video_gen' };
      setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isGeneratingVideo: false }));
    } catch { setState(prev => ({ ...prev, isGeneratingVideo: false, error: "视频生成失败" })); }
  };

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-200 relative" onDragOver={e=>{e.preventDefault();setIsDragging(true)}} onDragLeave={()=>setIsDragging(false)} onDrop={e=>{e.preventDefault();setIsDragging(false);e.dataTransfer.files && chatInputRef.current?.addFiles(e.dataTransfer.files)}}>
      {isDragging && <div className="absolute inset-0 z-50 bg-blue-600/20 backdrop-blur-sm border-4 border-dashed border-blue-500 flex items-center justify-center pointer-events-none"><div className="bg-slate-900 p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4"><p className="text-xl font-bold text-white">释放文件</p></div></div>}

      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-xl z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 flex items-center justify-center shadow-lg"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" viewBox="0 0 20 20" fill="currentColor"><path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM5 10a1 1 0 01-1 1H3a1 1 0 110-2h1a1 1 0 011 1zM8 16v-1a1 1 0 112 0v1a1 1 0 11-2 0zM13.536 15.657a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM6.464 14.95a1 1 0 11-1.414 1.414l-.707-.707a1 1 0 011.414-1.414l.707.707z" /></svg></div>
          <div>
            <h1 className="font-bold text-sm">Gemini Omniverse</h1>
            <div className="flex items-center gap-2">
              <div className="w-20 h-1 bg-slate-800 rounded-full overflow-hidden">
                <div className={`h-full transition-all duration-500 ${storageUsage > 80 ? 'bg-rose-500' : 'bg-emerald-500'}`} style={{width: `${storageUsage}%`}}></div>
              </div>
              <span className="text-[9px] text-slate-500 font-bold tracking-tighter uppercase">Memory: {storageUsage}%</span>
            </div>
          </div>
        </div>
        <div className="flex gap-2">
           <button onClick={() => confirm('重置所有记忆？') && clearAllHistory()} className="text-[10px] uppercase font-bold text-slate-500 hover:text-red-400 bg-slate-800/50 px-3 py-1.5 rounded-md border border-slate-700/50">重置</button>
        </div>
      </header>

      {state.error && <div className="bg-red-500/20 p-2 text-center text-xs text-red-300">{state.error}</div>}

      <main className="flex-1 overflow-hidden flex flex-col max-w-5xl mx-auto w-full">
        <MessageList 
          messages={state.messages} 
          isThinking={state.isThinking} 
          isGeneratingVideo={state.isGeneratingVideo} 
          onDeleteMessage={handleDeleteMessage}
        />
      </main>

      <ChatInput 
        ref={(el) => (chatInputRef.current = el)}
        onSendMessage={handleSendMessage} 
        onGenerateVideo={handleGenerateVideo} 
        disabled={state.isThinking || state.isGeneratingVideo} 
      />
    </div>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';
import { Message } from '../types';
import Markdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { atomDark } from 'react-syntax-highlighter/dist/esm/styles/prism';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  isGeneratingVideo: boolean;
  onDeleteMessage: (id: string) => void;
}

const MessageList: React.FC<MessageListProps> = ({ messages, isThinking, isGeneratingVideo, onDeleteMessage }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isThinking, isGeneratingVideo]);

  const handleDownloadFile = (content: string, language: string) => {
    const extensions: Record<string, string> = { 'latex': 'tex', 'tex': 'tex', 'javascript': 'js', 'typescript': 'ts', 'python': 'py', 'markdown': 'md', 'html': 'html', 'css': 'css', 'json': 'json', 'java': 'java', 'cpp': 'cpp', 'c': 'c' };
    const ext = extensions[language.toLowerCase()] || 'txt';
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `gemini_export_${Date.now()}.${ext}`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth">
      {messages.length === 0 && !isGeneratingVideo && (
        <div className="h-full flex flex-col items-center justify-center text-slate-500 space-y-4">
          <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-blue-600 to-purple-600 flex items-center justify-center shadow-2xl">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg>
          </div>
          <h2 className="text-xl font-bold text-slate-200">Gemini Omniverse</h2>
          <p className="text-sm text-slate-500 text-center max-w-sm">
            本地记忆已就绪。你可以通过右下角按钮或直接输入 <b>“清空历史”</b> 来管理存储空间。
          </p>
        </div>
      )}

      {messages.map((msg) => (
        <div key={msg.id} className={`flex group/msg ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
          <div className={`relative max-w-[90%] md:max-w-[80%] rounded-2xl p-4 shadow-sm ${msg.role === 'user' ? 'message-bubble-user text-white' : 'message-bubble-ai text-slate-100'}`}>
            {/* 消息删除按钮 */}
            <button 
              onClick={() => onDeleteMessage(msg.id)}
              className="absolute -top-2 -right-2 w-6 h-6 bg-rose-500/90 hover:bg-rose-600 text-white rounded-full flex items-center justify-center opacity-0 group-hover/msg:opacity-100 transition-all scale-75 group-hover/msg:scale-100 shadow-lg z-20"
              title="删除此条消息"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
            </button>

            <div className="flex items-center mb-2 gap-2 opacity-60">
               <span className="text-[10px] font-bold uppercase tracking-wider">{msg.role === 'user' ? 'YOU' : 'GEMINI'}</span>
               <span className="text-[10px]">{msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
            </div>

            {msg.mediaItems && msg.mediaItems.length > 0 && (
              <div className={`grid gap-2 mb-3 ${msg.mediaItems.length === 1 ? 'grid-cols-1' : 'grid-cols-2 md:grid-cols-3'}`}>
                {msg.mediaItems.map((item, idx) => (
                  <div key={idx} className="relative rounded-lg overflow-hidden border border-white/10 shadow-md">
                    {item.mimeType.includes('image') && item.data ? (
                      <img src={`data:${item.mimeType};base64,${item.data}`} className="w-full h-full object-cover max-h-48" alt="Attachment" />
                    ) : item.url && item.mimeType.includes('video') ? (
                      <video controls className="w-full bg-black" src={item.url} />
                    ) : (
                      <div className="flex items-center gap-3 p-3 bg-white/5 h-20">
                        <div className="p-2 bg-slate-800 rounded-lg">
                           <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 ${item.mimeType.includes('pdf') ? 'text-red-400' : 'text-blue-400'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                        </div>
                        <div className="flex flex-col min-w-0"><span className="text-[11px] font-bold truncate text-slate-200">{item.fileName}</span></div>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}

            <div className="markdown-content text-sm md:text-[15px] leading-relaxed">
              <Markdown remarkPlugins={[remarkGfm]} components={{
                code({node, inline, className, children, ...props}: any) {
                  const match = /language-(\w+)/.exec(className || '');
                  const lang = match ? match[1] : '';
                  const content = String(children).replace(/\n$/, '');
                  return !inline && match ? (
                    <div className="relative group/code my-4">
                      <div className="absolute right-2 top-2 z-10 flex gap-2 opacity-0 group-hover/code:opacity-100 transition-opacity">
                         <button onClick={() => handleDownloadFile(content, lang)} className="bg-slate-800/80 hover:bg-blue-600 text-white text-[10px] px-2 py-1 rounded border border-white/10 backdrop-blur-sm flex items-center gap-1 transition-colors">
                           <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                           导出 .{lang === 'latex' ? 'tex' : lang}
                         </button>
                      </div>
                      <SyntaxHighlighter style={atomDark} language={lang} PreTag="div" {...props}>{content}</SyntaxHighlighter>
                    </div>
                  ) : <code className={`${className} bg-slate-950/50 px-1.5 py-0.5 rounded text-blue-300 font-mono text-xs`} {...props}>{children}</code>;
                }
              }}>{msg.content}</Markdown>
            </div>
          </div>
        </div>
      ))}

      {(isThinking || isGeneratingVideo) && (
        <div className="flex justify-start animate-pulse">
          <div className="message-bubble-ai text-slate-100 p-4 rounded-2xl flex items-center gap-2">
            <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce"></div>
            <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce [animation-delay:-.3s]"></div>
            <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce [animation-delay:-.5s]"></div>
          </div>
        </div>
      )}
    </div>
  );
};

