              value={input} 
              onChange={(e) => setInput(e.target.value)} 
              onPaste={handlePaste} 
              placeholder={mode === 'video' ? "描述视频..." : "拖入文件、ZIP 或输入消息..."} 
              disabled={disabled} 
              className="w-full bg-slate-800/50 border border-slate-700 rounded-xl px-4 py-3 text-sm focus:outline-none transition-all" 
            />
          </div>

          <button type="submit" disabled={(!input.trim() && previews.length === 0) || disabled} className={`rounded-xl px-5 py-3 transition-all ${mode === 'video' ? 'bg-purple-600 hover:bg-purple-500' : 'bg-blue-600 hover:bg-blue-500'} text-white font-medium`}>
            {mode === 'video' ? '生成' : `发送 ${previews.length > 0 ? `(${previews.length})` : ''}`}
          </button>
        </form>
      </div>
    </div>
  );
});

export default ChatInput;

import React, { useState, FormEvent, useRef, ClipboardEvent, useImperativeHandle, forwardRef } from 'react';
import { MessageMedia } from '../types';
import JSZip from 'jszip';

interface ChatInputProps {
  onSendMessage: (message: string, media?: MessageMedia[]) => void;
  onGenerateVideo: (prompt: string) => void;
  disabled: boolean;
}

const SUPPORTED_MIME_TYPES = [
  'image/png', 'image/jpeg', 'image/webp', 'image/heic', 'image/heif',
  'application/pdf'
];

const TEXT_EXTENSIONS = [
  'tex', 'txt', 'md', 'js', 'jsx', 'ts', 'tsx', 'py', 'java', 'c', 'cpp', 'h', 'css', 'html', 'json', 'xml', 'yaml', 'yml', 'sql'
];

const ChatInput = forwardRef((props: ChatInputProps, ref) => {
  const { onSendMessage, onGenerateVideo, disabled } = props;
  const [input, setInput] = useState('');
  const [mode, setMode] = useState<'chat' | 'video'>('chat');
  const [previews, setPreviews] = useState<(MessageMedia & { id: string; name: string })[]>([]);
  const [isProcessingZip, setIsProcessingZip] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useImperativeHandle(ref, () => ({
    addFiles: (files: FileList | File[]) => {
      processFiles(files);
    }
  }));

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const val = input.trim();
    if (!val && previews.length === 0) return;

    if (mode === 'video') {
      onGenerateVideo(val || "一段科幻大片视频");
      setInput('');
    } else {
      onSendMessage(val, previews.length > 0 ? previews : undefined);
      setInput('');
      setPreviews([]);
    }
  };

  const processFiles = async (files: FileList | File[]) => {
    const newFiles = Array.from(files);

    for (const file of newFiles) {
      if (previews.some(p => p.name === file.name)) continue;

      const extension = file.name.split('.').pop()?.toLowerCase() || '';

      // 特殊处理 ZIP 文件
      if (extension === 'zip') {
        setIsProcessingZip(true);
        try {
          const zip = new JSZip();
          const contents = await zip.loadAsync(file);
          const zipFiles: File[] = [];

          // Fix: Iterate through files and cast zipEntry to any to avoid "unknown" type errors for 'dir' and 'async' properties
          for (const relativePath of Object.keys(contents.files)) {
            const zipEntry = contents.files[relativePath] as any;
            if (zipEntry.dir) continue;

            // 提取文件内容并构造 File 对象
            const blob = await zipEntry.async('blob');
            const fileName = relativePath.split('/').pop() || 'unnamed';
            const innerFile = new File([blob], fileName, { type: getMimeTypeFromExtension(fileName) });
            zipFiles.push(innerFile);
          }

          if (zipFiles.length > 0) {
            await processFiles(zipFiles);
          }
        } catch (err) {
          console.error("ZIP Error:", err);
          alert(`无法解析压缩包 ${file.name}`);
        } finally {
          setIsProcessingZip(false);
        }
        continue;
      }

      const isText = TEXT_EXTENSIONS.includes(extension) || file.type.startsWith('text/');
      const isSupportedMedia = SUPPORTED_MIME_TYPES.includes(file.type);

      if (isText) {
        const text = await file.text();
        setPreviews(prev => [...prev, { 
          id: Math.random().toString(36).substr(2, 9), 
          mimeType: 'text/plain', 
          name: file.name, 
          fileName: file.name, 
          textContent: text 
        }].slice(-30)); // 增加预览上限
      } else if (isSupportedMedia) {
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64Data = (reader.result as string).split(',')[1];
          setPreviews(prev => [...prev, { 
            id: Math.random().toString(36).substr(2, 9), 
            data: base64Data, 
            mimeType: file.type, 
            name: file.name, 
            fileName: file.name 
          }].slice(-30));
        };
        reader.readAsDataURL(file);
      }
    }
  };

  // 简单的扩展名转 MIME 类型
  const getMimeTypeFromExtension = (fileName: string): string => {
    const ext = fileName.split('.').pop()?.toLowerCase();
    const map: Record<string, string> = {
      'png': 'image/png', 'jpg': 'image/jpeg', 'jpeg': 'image/jpeg',
      'webp': 'image/webp', 'pdf': 'application/pdf', 'txt': 'text/plain'
    };
    return map[ext || ''] || 'application/octet-stream';
  };

  const handlePaste = (e: ClipboardEvent<HTMLInputElement>) => {
    const items = e.clipboardData.items;
    const filesToProcess: File[] = [];
    for (let i = 0; i < items.length; i++) {
      if (items[i].kind === 'file') {
        const file = items[i].getAsFile();
        if (file) filesToProcess.push(file);
      }
    }
    if (filesToProcess.length > 0) processFiles(filesToProcess);
  };

  return (
    <div className="p-4 border-t border-slate-800 bg-slate-900/80 backdrop-blur-xl relative">
      <div className="max-w-4xl mx-auto flex flex-col gap-3">
        {isProcessingZip && (
          <div className="flex items-center gap-2 text-[10px] text-blue-400 font-bold animate-pulse px-2">
            <svg className="animate-spin h-3 w-3" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
            正在解压压缩包...
          </div>
        )}

        {previews.length > 0 && (
          <div className="flex items-end gap-3 animate-in fade-in slide-in-from-bottom-2">
            <div className="flex-1 flex gap-3 overflow-x-auto pb-2 scrollbar-hide">
              {previews.map((preview) => (
                <div key={preview.id} className="relative flex-shrink-0 group">
                  <div className={`w-14 h-14 rounded-xl border border-slate-700 overflow-hidden flex flex-col items-center justify-center shadow-md p-1 ${preview.textContent ? 'bg-emerald-500/10' : 'bg-slate-800'}`}>
                    {preview.mimeType.includes('image') && preview.data ? (
                      <img src={`data:${preview.mimeType};base64,${preview.data}`} className="w-full h-full object-cover rounded-md" alt="Preview" />
                    ) : (
                      <div className="flex flex-col items-center">
                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 ${preview.textContent ? 'text-emerald-400' : preview.mimeType.includes('pdf') ? 'text-red-400' : 'text-blue-400'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                        </svg>
                        <span className="text-[6px] text-slate-500 truncate max-w-[40px] mt-1">{preview.name}</span>
                      </div>
                    )}
                  </div>
                  <button onClick={() => setPreviews(p => p.filter(x => x.id !== preview.id))} className="absolute -top-1.5 -right-1.5 bg-red-500 text-white rounded-full p-0.5 shadow-lg scale-0 group-hover:scale-100 transition-transform">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M6 18L18 6M6 6l12 12" /></svg>
                  </button>
                </div>
              ))}
            </div>
            <button onClick={() => setPreviews([])} className="mb-2 text-[9px] font-bold text-slate-500 hover:text-slate-300 uppercase tracking-tighter">清空全部</button>
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex gap-3 items-center">
          <input type="file" multiple className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && processFiles(e.target.files)} />
          <div className="flex bg-slate-800 rounded-xl p-1 border border-slate-700 shadow-inner">
            <button type="button" onClick={() => setMode('chat')} className={`p-2 rounded-lg transition-all ${mode === 'chat' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
            </button>
            <button type="button" onClick={() => setMode('video')} className={`p-2 rounded-lg transition-all ${mode === 'video' ? 'bg-purple-600 text-white' : 'text-slate-400 hover:text-white'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
            </button>
          </div>
          <button type="button" onClick={() => fileInputRef.current?.click()} disabled={disabled || mode === 'video'} className="p-3 bg-slate-800/80 hover:bg-slate-700 text-slate-300 rounded-xl border border-slate-700 disabled:opacity-30">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M12 4v16m8-8H4" /></svg>
          </button>

          <div className="flex-1 relative">
            <input 
              type="text" 
              value={input} 
              onChange={(e) => setInput(e.target.value)} 
              onPaste={handlePaste} 
              placeholder={mode === 'video' ? "描述视频..." : "拖入文件、ZIP 或输入消息..."} 
              disabled={disabled} 
              className="w-full bg-slate-800/50 border border-slate-700 rounded-xl px-4 py-3 text-sm focus:outline-none transition-all" 
            />
          </div>

          <button type="submit" disabled={(!input.trim() && previews.length === 0) || disabled} className={`rounded-xl px-5 py-3 transition-all ${mode === 'video' ? 'bg-purple-600 hover:bg-purple-500' : 'bg-blue-600 hover:bg-blue-500'} text-white font-medium`}>
            {mode === 'video' ? '生成' : `发送 ${previews.length > 0 ? `(${previews.length})` : ''}`}
          </button>
        </form>
      </div>
    </div>
  );
});

export default ChatInput;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Message, ChatState, MessageMedia } from './types';
import { sendMessageWithMedia, generateVideo } from './services/geminiService';
import MessageList from './components/MessageList';
import ChatInput from './components/ChatInput';

const STORAGE_KEY = 'GEMINI_OMNIVERSE_STABLE_V1';

// Fix: Augment window interface for mandatory aistudio API key selection
declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

const App: React.FC = () => {
  const [state, setState] = useState<ChatState>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        const parsed = JSON.parse(savedData);
        if (Array.isArray(parsed)) {
          return {
            messages: parsed.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
            isThinking: false,
            isGeneratingVideo: false,
            error: null
          };
        }
      }
    } catch (e) { console.error("Load error", e); }
    return { messages: [], isThinking: false, isGeneratingVideo: false, error: null };
  });

  const [isDragging, setIsDragging] = useState(false);
  // Fix: Track whether mandatory API key for Veo has been selected
  const [apiKeySelected, setApiKeySelected] = useState(false);
  const isInitialMount = useRef(true);
  const chatInputRef = useRef<{ addFiles: (files: FileList | File[]) => void } | null>(null);

  // Fix: Initialize API key selection state on mount
  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setApiKeySelected(hasKey);
      }
    };
    checkKey();
  }, []);

  // Fix: Helper to trigger the mandatory API key selection dialog
  const handleOpenKeySelector = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      // Assume success as per guidelines to avoid race condition delays
      setApiKeySelected(true);
    }
  };

  // 计算存储使用率 (假设上限 5MB)
  const storageUsage = useMemo(() => {
    const str = JSON.stringify(state.messages);
    const bytes = new Blob([str]).size;
    const limit = 5 * 1024 * 1024; // 5MB
    return Math.min(100, Math.round((bytes / limit) * 100));
  }, [state.messages]);

  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
      return;
    }
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.messages));
  }, [state.messages]);

  const handleDeleteMessage = (id: string) => {
    setState(prev => ({
      ...prev,
      messages: prev.messages.filter(m => m.id !== id)
    }));
  };

  const clearAllHistory = () => {
    setState(prev => ({ ...prev, messages: [] }));
    localStorage.removeItem(STORAGE_KEY);
  };

  const handleSendMessage = async (content: string, mediaItems?: MessageMedia[]) => {
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: new Date(),
      mediaItems,
      type: mediaItems?.some(m => m.mimeType.includes('pdf')) ? 'doc_analysis' : 'text'
    };

    const updatedMessages = [...state.messages, userMsg];
    setState(prev => ({ ...prev, messages: updatedMessages, isThinking: true, error: null }));

    try {
      const response = await sendMessageWithMedia(updatedMessages, content, mediaItems);

      // 处理函数调用
      if (response.functionCalls) {
        for (const call of response.functionCalls) {
          if (call.name === 'clear_all_history') {
            clearAllHistory();
            return; // 已经清空，无需继续
          }
          if (call.name === 'delete_last_n_messages') {
            const count = call.args.count || 2;
            setState(prev => ({
              ...prev,
              messages: prev.messages.slice(0, -count),
              isThinking: false
            }));
            return;
          }
        }
      }

      const assistantMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "已完成您的请求。",
        timestamp: new Date(),
      };
      setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isThinking: false }));
    } catch (err: any) {
      setState(prev => ({ ...prev, isThinking: false, error: "服务响应异常。" }));
    }
  };

  const handleGenerateVideo = async (prompt: string) => {
    // Fix: Mandatory API key selection check before using Veo models
    if (!apiKeySelected) {
      await handleOpenKeySelector();
    }

    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: `生成视频：${prompt}`, timestamp: new Date(), type: 'video_gen' };
    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isGeneratingVideo: true }));
    try {
      const url = await generateVideo(prompt);
      const assistantMsg: Message = { id: (Date.now() + 1).toString(), role: 'assistant', content: '视频已生成', timestamp: new Date(), mediaItems: [{url, mimeType: 'video/mp4'}], type: 'video_gen' };
      setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isGeneratingVideo: false }));
    } catch (err: any) { 
      // Fix: Reset key selection if entity not found as per guidelines
      if (err.message?.includes("Requested entity was not found.")) {
        setApiKeySelected(false);
      }
      setState(prev => ({ ...prev, isGeneratingVideo: false, error: "视频生成失败" })); 
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-200 relative" onDragOver={e=>{e.preventDefault();setIsDragging(true)}} onDragLeave={()=>setIsDragging(false)} onDrop={e=>{e.preventDefault();setIsDragging(false);e.dataTransfer.files && chatInputRef.current?.addFiles(e.dataTransfer.files)}}>
      {isDragging && <div className="absolute inset-0 z-50 bg-blue-600/20 backdrop-blur-sm border-4 border-dashed border-blue-500 flex items-center justify-center pointer-events-none"><div className="bg-slate-900 p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4"><p className="text-xl font-bold text-white">释放文件</p></div></div>}

      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-xl z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 flex items-center justify-center shadow-lg"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" viewBox="0 0 20 20" fill="currentColor"><path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM5 10a1 1 0 01-1 1H3a1 1 0 110-2h1a1 1 0 011 1zM8 16v-1a1 1 0 112 0v1a1 1 0 11-2 0zM13.536 15.657a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM6.464 14.95a1 1 0 11-1.414 1.414l-.707-.707a1 1 0 011.414-1.414l.707.707z" /></svg></div>
          <div>
            <h1 className="font-bold text-sm">Gemini Omniverse</h1>
            <div className="flex items-center gap-2">
              <div className="w-20 h-1 bg-slate-800 rounded-full overflow-hidden">
                <div className={`h-full transition-all duration-500 ${storageUsage > 80 ? 'bg-rose-500' : 'bg-emerald-500'}`} style={{width: `${storageUsage}%`}}></div>
              </div>
              <span className="text-[9px] text-slate-500 font-bold tracking-tighter uppercase">Memory: {storageUsage}%</span>
            </div>
          </div>
        </div>
        <div className="flex gap-2">
           {/* Fix: API key selection button for required paid projects */}
           {!apiKeySelected && (
             <button onClick={handleOpenKeySelector} className="text-[10px] uppercase font-bold text-blue-400 hover:text-blue-300 bg-blue-500/10 px-3 py-1.5 rounded-md border border-blue-500/30">激活付费Key (Veo)</button>
           )}
           <button onClick={() => confirm('重置所有记忆？') && clearAllHistory()} className="text-[10px] uppercase font-bold text-slate-500 hover:text-red-400 bg-slate-800/50 px-3 py-1.5 rounded-md border border-slate-700/50">重置</button>
        </div>
      </header>

      {state.error && <div className="bg-red-500/20 p-2 text-center text-xs text-red-300">{state.error}</div>}

      <main className="flex-1 overflow-hidden flex flex-col max-w-5xl mx-auto w-full">
        <MessageList 
          messages={state.messages} 
          isThinking={state.isThinking} 
          isGeneratingVideo={state.isGeneratingVideo} 
          onDeleteMessage={handleDeleteMessage}
        />
      </main>

      <ChatInput 
        ref={(el) => (chatInputRef.current = el)}
        onSendMessage={handleSendMessage} 
        onGenerateVideo={handleGenerateVideo} 
        disabled={state.isThinking || state.isGeneratingVideo} 
      />
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, FunctionDeclaration } from "@google/genai";
import { Message, MessageMedia } from "../types";

const SUPPORTED_MIME_TYPES = [
  'image/png', 'image/jpeg', 'image/webp', 'image/heic', 'image/heif',
  'application/pdf'
];

// 定义管理历史记录的工具函数
const historyToolDeclarations: FunctionDeclaration[] = [
  {
    name: 'clear_all_history',
    description: '完全清空所有对话记录和本地存储空间。当用户明确要求重置、清空或开始新对话时调用。',
    parameters: { type: Type.OBJECT, properties: {} }
  },
  {
    name: 'delete_last_n_messages',
    description: '删除最近的几条消息。',
    parameters: {
      type: Type.OBJECT,
      properties: {
        count: { type: Type.NUMBER, description: '需要删除的消息条数（默认为 2，即一对问答）。' }
      },
      required: ['count']
    }
  }
];

const mapToContent = (messages: Message[]) => {
  const history = messages.slice(0, -1);
  return history.map(msg => {
    const parts: any[] = [];
    let combinedText = msg.content || "";
    if (msg.mediaItems) {
      msg.mediaItems.forEach(item => {
        if (item.textContent) {
          combinedText += `\n\n--- 附件文件: ${item.fileName} ---\n${item.textContent}\n--- 结束 ---`;
        }
      });
    }
    if (combinedText.trim()) parts.push({ text: combinedText });
    if (msg.mediaItems) {
      msg.mediaItems.forEach(item => {
        if (item.data && SUPPORTED_MIME_TYPES.includes(item.mimeType)) {
          parts.push({ inlineData: { data: item.data, mimeType: item.mimeType } });
        }
      });
    }
    if (parts.length === 0) parts.push({ text: "..." });
    return { role: msg.role === 'user' ? 'user' : 'model', parts };
  });
};

export interface ChatResponse {
  text?: string;
  functionCalls?: any[];
}

export const sendMessageWithMedia = async (
  fullHistory: Message[],
  currentText: string,
  mediaItems?: MessageMedia[]
): Promise<ChatResponse> => {
  // Fix: Create a fresh GoogleGenAI instance right before the call as per guidelines
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  let finalPrompt = currentText;
  const currentParts: any[] = [];

  if (mediaItems) {
    mediaItems.forEach(item => {
      if (item.textContent) {
        finalPrompt += `\n\n--- 粘贴/拖入的文件: ${item.fileName} ---\n${item.textContent}\n--- 结束 ---`;
      }
      if (item.data && SUPPORTED_MIME_TYPES.includes(item.mimeType)) {
        currentParts.push({ inlineData: { data: item.data, mimeType: item.mimeType } });
      }
    });
  }

  currentParts.unshift({ text: finalPrompt || "请分析我上传的这些文件。" });

  try {
    const response = await ai.models.generateContent({
      // Fix: Upgrade to gemini-3-pro-preview for complex reasoning and file analysis tasks
      model: 'gemini-3-pro-preview',
      contents: [
        ...mapToContent(fullHistory),
        { role: 'user', parts: currentParts }
      ],
      config: {
        tools: [{ functionDeclarations: historyToolDeclarations }],
