import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Message, ChatState, MessageMedia } from './types';
import { sendMessageWithMedia, generateVideo } from './services/geminiService';
import MessageList from './components/MessageList';
import ChatInput from './components/ChatInput';

// 保持 Key 稳定性，确保跨版本更新时数据不丢失
const STORAGE_KEY = 'GEMINI_OMNIVERSE_STABLE_V1';

const App: React.FC = () => {
  const [state, setState] = useState<ChatState>(() => {
    // 优先从本地读取，确保在首次渲染时状态就是“旧的”
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        const parsed = JSON.parse(savedData);
        if (Array.isArray(parsed)) {
          return {
            messages: parsed.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
            isThinking: false,
            isGeneratingVideo: false,
            error: null
          };
        }
      }
    } catch (e) { 
      console.error("Load error during init", e); 
    }
    return { messages: [], isThinking: false, isGeneratingVideo: false, error: null };
  });

  const [isDragging, setIsDragging] = useState(false);
  const [apiKeySelected, setApiKeySelected] = useState(false);
  const [hasInitialized, setHasInitialized] = useState(false); // 关键：标记是否已确认完成初始化加载

  const chatInputRef = useRef<{ addFiles: (files: FileList | File[]) => void } | null>(null);

  // 初始化 API Key 状态并锁定初始化完成标记
  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio) {
        // @ts-ignore
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setApiKeySelected(hasKey);
      }
      // 在确保所有异步检查完成后，标记初始化完成
      setHasInitialized(true);
    };
    checkKey();
  }, []);

  const handleOpenKeySelector = async () => {
    // @ts-ignore
    if (window.aistudio) {
      // @ts-ignore
      await window.aistudio.openSelectKey();
      // Assume success due to race condition as per guidelines
      setApiKeySelected(true);
    }
  };

  // 稳健的数据持久化逻辑
  useEffect(() => {
    // 只有在完成初始化加载（hasInitialized 为 true）后，且 state.messages 发生变化时才保存
    if (!hasInitialized) return;

    try {
      const dataToSave = JSON.stringify(state.messages);
      localStorage.setItem(STORAGE_KEY, dataToSave);
    } catch (e) {
      console.error("Failed to save to localStorage", e);
      if (String(e).includes("QuotaExceededError")) {
        setState(prev => ({ ...prev, error: "本地存储空间已满（5MB），请删除部分旧的历史记录或大图。" }));
      }
    }
  }, [state.messages, hasInitialized]);

  // 计算本地存储使用率
  const storageUsage = useMemo(() => {
    try {
      const str = JSON.stringify(state.messages);
      const bytes = new Blob([str]).size;
      const limit = 5 * 1024 * 1024; // 浏览器通常限制为 5MB
      return Math.min(100, Math.round((bytes / limit) * 100));
    } catch (e) { return 0; }
  }, [state.messages]);

  const handleDeleteMessage = (id: string) => {
    setState(prev => ({
      ...prev,
      messages: prev.messages.filter(m => m.id !== id)
    }));
  };

  const clearAllHistory = () => {
    if (confirm('确定要清空所有历史对话吗？此操作将释放本地存储空间。')) {
      setState(prev => ({ ...prev, messages: [] }));
      localStorage.removeItem(STORAGE_KEY);
    }
  };

  const handleSendMessage = async (content: string, mediaItems?: MessageMedia[]) => {
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: new Date(),
      mediaItems,
      type: mediaItems?.some(m => m.mimeType.includes('pdf')) ? 'doc_analysis' : 'text'
    };

    const updatedMessages = [...state.messages, userMsg];
    setState(prev => ({ ...prev, messages: updatedMessages, isThinking: true, error: null }));

    try {
      const response = await sendMessageWithMedia(updatedMessages, content, mediaItems);

      if (response.functionCalls) {
        for (const call of response.functionCalls) {
          if (call.name === 'clear_all_history') {
            setState(prev => ({ ...prev, messages: [] }));
            localStorage.removeItem(STORAGE_KEY);
            return;
          }
          if (call.name === 'delete_last_n_messages') {
            const count = call.args.count || 2;
            setState(prev => ({
              ...prev,
              messages: prev.messages.slice(0, -count),
              isThinking: false
            }));
            return;
          }
        }
      }

      const assistantMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "已完成您的请求。",
        timestamp: new Date(),
      };
      setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isThinking: false }));
    } catch (err: any) {
      let errorMsg = "AI 服务响应异常。";
      const errStr = String(err);
      if (errStr.includes("429")) {
        errorMsg = "⚠️ 频率过快：每分钟提额已满，请休息一会再试。";
      } else if (errStr.includes("403")) {
        errorMsg = "🚫 额度耗尽：今日 API 免费额度已用完，请明天再来。";
      } else if (errStr.includes("500") || errStr.includes("503")) {
        errorMsg = "☁️ 云端故障：Google 服务器繁忙或维护中。";
      }
      setState(prev => ({ ...prev, isThinking: false, error: errorMsg }));
      setTimeout(() => setState(prev => ({ ...prev, error: null })), 6000);
    }
  };

  const handleGenerateVideo = async (prompt: string) => {
    if (!apiKeySelected) {
      await handleOpenKeySelector();
    }
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: `生成视频：${prompt}`, timestamp: new Date(), type: 'video_gen' };
    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isGeneratingVideo: true }));
    try {
      const url = await generateVideo(prompt);
      const assistantMsg: Message = { id: (Date.now() + 1).toString(), role: 'assistant', content: '视频已生成', timestamp: new Date(), mediaItems: [{url, mimeType: 'video/mp4'}], type: 'video_gen' };
      setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isGeneratingVideo: false }));
    } catch (err: any) { 
      if (err.message?.includes("Requested entity was not found.")) setApiKeySelected(false);
      setState(prev => ({ ...prev, isGeneratingVideo: false, error: "视频生成失败，可能是点数不足或网络中断。" })); 
      setTimeout(() => setState(prev => ({ ...prev, error: null })), 5000);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-200 relative" onDragOver={e=>{e.preventDefault();setIsDragging(true)}} onDragLeave={()=>setIsDragging(false)} onDrop={e=>{e.preventDefault();setIsDragging(false);e.dataTransfer.files && chatInputRef.current?.addFiles(e.dataTransfer.files)}}>
      {isDragging && <div className="absolute inset-0 z-50 bg-blue-600/20 backdrop-blur-sm border-4 border-dashed border-blue-500 flex items-center justify-center pointer-events-none"><div className="bg-slate-900 p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4"><p className="text-xl font-bold text-white">释放文件</p></div></div>}

      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-xl z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 flex items-center justify-center shadow-lg"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" viewBox="0 0 20 20" fill="currentColor"><path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707z" /></svg></div>
          <h1 className="text-xl font-black italic tracking-tighter text-white">GEMINI OMNIVERSE</h1>
        </div>
        <div className="flex items-center gap-4">
          {!apiKeySelected && (
            <button 
              onClick={handleOpenKeySelector}
              className="px-4 py-2 bg-blue-600 hover:bg-blue-500 text-white text-xs font-bold rounded-xl transition-all shadow-lg shadow-blue-500/20"
            >
              绑定 API KEY (Veo)
            </button>
          )}
          <div className="hidden md:flex flex-col items-end">
             <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Storage Status</span>
             <div className="flex items-center gap-2">
                <div className="w-24 h-1.5 bg-slate-800 rounded-full overflow-hidden">
                  <div className={`h-full ${storageUsage > 80 ? 'bg-rose-500' : 'bg-blue-500'} transition-all`} style={{ width: `${storageUsage}%` }}></div>
                </div>
                <span className={`text-[10px] ${storageUsage > 80 ? 'text-rose-400' : 'text-slate-400'}`}>{storageUsage}%</span>
             </div>
          </div>
        </div>
      </header>

      <MessageList 
        messages={state.messages} 
        isThinking={state.isThinking} 
        isGeneratingVideo={state.isGeneratingVideo} 
        onDeleteMessage={handleDeleteMessage}
      />

      <ChatInput 
        ref={chatInputRef}
        onSendMessage={handleSendMessage} 
        onGenerateVideo={handleGenerateVideo}
        disabled={state.isThinking || state.isGeneratingVideo} 
      />

      {state.error && (
        <div className="fixed bottom-28 left-1/2 -translate-x-1/2 z-50 animate-in fade-in slide-in-from-bottom-4">
          <div className="bg-rose-500/20 border border-rose-500/50 backdrop-blur-xl px-4 py-2 rounded-2xl text-rose-400 text-[11px] font-bold shadow-2xl flex items-center gap-2">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            {state.error}
          </div>
        </div>
      )}
    </div>
  );
};

