import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Message, ChatState, MessageMedia } from './types';
import { sendMessageWithMedia, generateVideo } from './services/geminiService';
import MessageList from './components/MessageList';
import ChatInput from './components/ChatInput';

// 固定的存储 Key
const STORAGE_KEY = 'GEMINI_OMNIVERSE_STABLE_V1';

const App: React.FC = () => {
  const [state, setState] = useState<ChatState>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        const parsed = JSON.parse(savedData);
        if (Array.isArray(parsed)) {
          return {
            messages: parsed.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
            isThinking: false,
            isGeneratingVideo: false,
            error: null
          };
        }
      }
    } catch (e) { 
      console.error("[Storage] Initial load failed:", e); 
    }
    return { messages: [], isThinking: false, isGeneratingVideo: false, error: null };
  });

  const [isDragging, setIsDragging] = useState(false);
  const [apiKeySelected, setApiKeySelected] = useState(false);
  const [hasInitialized, setHasInitialized] = useState(false);

  const chatInputRef = useRef<{ addFiles: (files: FileList | File[]) => void } | null>(null);

  useEffect(() => {
    const checkStatus = async () => {
      // @ts-ignore
      if (window.aistudio) {
        // @ts-ignore
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setApiKeySelected(hasKey);
      }
      setHasInitialized(true);
    };
    checkStatus();
  }, []);

  useEffect(() => {
    if (!hasInitialized) return;
    try {
      const dataToSave = JSON.stringify(state.messages);
      localStorage.setItem(STORAGE_KEY, dataToSave);
    } catch (e) {
      if (String(e).includes("QuotaExceededError")) {
        setState(prev => ({ ...prev, error: "本地空间已满，请删除部分历史对话。" }));
      }
    }
  }, [state.messages, hasInitialized]);

  const handleOpenKeySelector = async () => {
    // @ts-ignore
    if (window.aistudio) {
      // @ts-ignore
      await window.aistudio.openSelectKey();
      setApiKeySelected(true);
    }
  };

  const storageUsage = useMemo(() => {
    try {
      const str = JSON.stringify(state.messages);
      const bytes = new Blob([str]).size;
      const limit = 5 * 1024 * 1024;
      return Math.min(100, Math.round((bytes / limit) * 100));
    } catch (e) { return 0; }
  }, [state.messages]);

  const handleDeleteMessage = (id: string) => {
    setState(prev => ({
      ...prev,
      messages: prev.messages.filter(m => m.id !== id)
    }));
  };

  const clearAllHistory = () => {
    if (confirm('确认清空所有历史对话吗？')) {
      setState(prev => ({ ...prev, messages: [] }));
      localStorage.removeItem(STORAGE_KEY);
    }
  };

  const handleSendMessage = async (content: string, mediaItems?: MessageMedia[]) => {
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: new Date(),
      mediaItems,
      type: mediaItems?.some(m => m.mimeType.includes('pdf')) ? 'doc_analysis' : 'text'
    };

    const updatedMessages = [...state.messages, userMsg];
    setState(prev => ({ ...prev, messages: updatedMessages, isThinking: true, error: null }));

    try {
      const response = await sendMessageWithMedia(updatedMessages, content, mediaItems);

      if (response.functionCalls) {
        for (const call of response.functionCalls) {
          if (call.name === 'clear_all_history') {
            setState(prev => ({ ...prev, messages: [] }));
            localStorage.removeItem(STORAGE_KEY);
            return;
          }
          if (call.name === 'delete_last_n_messages') {
            const count = call.args.count || 2;
            setState(prev => ({ ...prev, messages: prev.messages.slice(0, -count), isThinking: false }));
            return;
          }
        }
      }

      const assistantMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "...",
        timestamp: new Date(),
      };
      setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isThinking: false }));
    } catch (err: any) {
      let errorMsg = "AI 服务响应异常。";
      const errStr = String(err);

      // 深度解析 429 和 403 错误
      if (errStr.includes("429") || errStr.includes("RESOURCE_EXHAUSTED")) {
        errorMsg = "⚠️ 触发云端限额：您今日的 Google API 免费配额已用完，或请求太快。请稍候再试（通常需等待 1-15 分钟）。";
      } else if (errStr.includes("403")) {
        errorMsg = "🚫 访问拒绝：您的 API 权限受限，可能是免费额度已彻底耗尽。";
      } else if (errStr.includes("500")) {
        errorMsg = "☁️ Google 服务器暂时忙碌，请点击重新发送。";
      }

      setState(prev => ({ ...prev, isThinking: false, error: errorMsg }));
      // 配额错误保持显示稍长时间
      setTimeout(() => setState(prev => ({ ...prev, error: null })), 8000);
    }
  };

  const handleGenerateVideo = async (prompt: string) => {
    if (!apiKeySelected) await handleOpenKeySelector();
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: `🎥 生成视频：${prompt}`, timestamp: new Date(), type: 'video_gen' };
    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isGeneratingVideo: true }));
    try {
      const url = await generateVideo(prompt);
      const assistantMsg: Message = { id: (Date.now() + 1).toString(), role: 'assistant', content: '视频已生成。', timestamp: new Date(), mediaItems: [{url, mimeType: 'video/mp4'}], type: 'video_gen' };
      setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isGeneratingVideo: false }));
    } catch (err: any) { 
      const errStr = String(err);
      let errorMsg = "视频生成失败。";
      if (errStr.includes("429")) errorMsg = "🎥 视频生成配额不足，请稍后再试。";
      setState(prev => ({ ...prev, isGeneratingVideo: false, error: errorMsg })); 
      setTimeout(() => setState(prev => ({ ...prev, error: null })), 5000);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-200 relative" onDragOver={e=>{e.preventDefault();setIsDragging(true)}} onDragLeave={()=>setIsDragging(false)} onDrop={e=>{e.preventDefault();setIsDragging(false);e.dataTransfer.files && chatInputRef.current?.addFiles(e.dataTransfer.files)}}>
      {isDragging && <div className="absolute inset-0 z-50 bg-blue-600/20 backdrop-blur-sm border-4 border-dashed border-blue-500 flex items-center justify-center pointer-events-none"><div className="bg-slate-900 p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4"><p className="text-xl font-bold text-white">释放文件</p></div></div>}

      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-xl z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 flex items-center justify-center shadow-lg"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" viewBox="0 0 20 20" fill="currentColor"><path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM5 10a1 1 0 01-1 1H3a1 1 0 110-2h1a1 1 0 011 1zM8 16v-1a1 1 0 112 0v1a1 1 0 11-2 0zM13.536 15.657a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM6.464 14.95a1 1 0 11-1.414 1.414l-.707-.707a1 1 0 011.414-1.414l.707.707z" /></svg></div>
          <h1 className="text-xl font-black italic tracking-tighter text-white">GEMINI OMNIVERSE</h1>
        </div>
        <div className="flex items-center gap-4">
          {!apiKeySelected && (
            <div className="flex flex-col items-end">
              <button onClick={handleOpenKeySelector} className="px-3 py-1.5 bg-blue-600 hover:bg-blue-500 text-white text-[10px] font-bold rounded-lg transition-all shadow-lg shadow-blue-500/20 uppercase">激活付费KEY (VEO)</button>
              <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noreferrer" className="text-[9px] text-slate-500 hover:text-blue-400 mt-0.5">账单文档</a>
            </div>
          )}
          <div className="hidden md:flex flex-col items-end border-l border-slate-800 pl-4 group relative cursor-help">
             <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">Local Memory</span>
             <div className="flex items-center gap-2">
                <div className="w-20 h-1 bg-slate-800 rounded-full overflow-hidden">
                  <div className={`h-full ${storageUsage > 80 ? 'bg-rose-500' : 'bg-indigo-500'} transition-all duration-700`} style={{ width: `${storageUsage}%` }}></div>
                </div>
                <span className={`text-[10px] font-mono ${storageUsage > 80 ? 'text-rose-400' : 'text-slate-400'}`}>{storageUsage}%</span>
             </div>
             {/* 浮窗提示，解释本地存储与 API 配额的区别 */}
             <div className="absolute top-10 right-0 w-48 bg-slate-800 border border-slate-700 p-2 rounded-lg text-[10px] text-slate-400 opacity-0 group-hover:opacity-100 transition-opacity z-50 pointer-events-none shadow-2xl">
               <p className="font-bold text-slate-200 mb-1">💡 提示</p>
               这里显示的是您浏览器本地保存对话记录的占用情况。API 配额（429错误）是 Google 云端服务的限制。
             </div>
          </div>
          <button onClick={clearAllHistory} title="清空所有记录" className="p-2 text-slate-500 hover:text-rose-500 transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
          </button>
        </div>
      </header>

      <MessageList 
        messages={state.messages} 
        isThinking={state.isThinking} 
        isGeneratingVideo={state.isGeneratingVideo} 
        onDeleteMessage={handleDeleteMessage}
      />

      <ChatInput 
        ref={chatInputRef}
        onSendMessage={handleSendMessage} 
        onGenerateVideo={handleGenerateVideo}
        disabled={state.isThinking || state.isGeneratingVideo} 
      />

      {state.error && (
        <div className="fixed bottom-28 left-1/2 -translate-x-1/2 z-50 animate-in fade-in slide-in-from-bottom-4 w-[90%] max-w-lg">
          <div className="bg-slate-900/90 border-2 border-rose-500/50 backdrop-blur-xl p-4 rounded-2xl shadow-2xl flex flex-col gap-2">
            <div className="flex items-center gap-3 text-rose-400">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
              <span className="text-sm font-bold">{state.error}</span>
            </div>
            <p className="text-[10px] text-slate-500 pl-9">
              注：这通常是由于短时间内请求过快触发了 Google 的云端保护。建议刷新页面或稍后再试。
            </p>
            <button 
              onClick={() => setState(prev => ({ ...prev, error: null }))}
              className="mt-2 w-full py-1.5 bg-rose-500/20 hover:bg-rose-500/30 text-rose-400 text-[10px] font-bold rounded-lg transition-colors border border-rose-500/20"
            >
              我知道了
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, FormEvent, useRef, ClipboardEvent, useImperativeHandle, forwardRef } from 'react';
import { MessageMedia } from '../types';
import JSZip from 'jszip';

interface ChatInputProps {
  onSendMessage: (message: string, media?: MessageMedia[]) => void;
  onGenerateVideo: (prompt: string) => void;
  disabled: boolean;
}

const SUPPORTED_MIME_TYPES = [
  'image/png', 'image/jpeg', 'image/webp', 'image/heic', 'image/heif',
  'application/pdf'
];

const TEXT_EXTENSIONS = [
  'tex', 'txt', 'md', 'js', 'jsx', 'ts', 'tsx', 'py', 'java', 'c', 'cpp', 'h', 'css', 'html', 'json', 'xml', 'yaml', 'yml', 'sql'
];

const ChatInput = forwardRef((props: ChatInputProps, ref) => {
  const { onSendMessage, onGenerateVideo, disabled } = props;
  const [input, setInput] = useState('');
  const [mode, setMode] = useState<'chat' | 'video'>('chat');
  const [previews, setPreviews] = useState<(MessageMedia & { id: string; name: string })[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useImperativeHandle(ref, () => ({
    addFiles: (files: FileList | File[]) => {
      processFiles(files);
    }
  }));

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const val = input.trim();
    if (!val && previews.length === 0) return;

    if (mode === 'video') {
      onGenerateVideo(val || "一段科幻大片视频");
      setInput('');
    } else {
      onSendMessage(val, previews.length > 0 ? previews : undefined);
      setInput('');
      setPreviews([]);
    }
  };

  const processFiles = async (files: FileList | File[]) => {
    setIsProcessing(true);
    const newFiles = Array.from(files);

    for (const file of newFiles) {
      // 移除原有的同名拦截逻辑，改用唯一 ID 标识，解决粘贴图片同名冲突问题
      const uniqueId = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      const extension = file.name.split('.').pop()?.toLowerCase() || '';

      if (extension === 'zip') {
        try {
          const zip = new JSZip();
          const contents = await zip.loadAsync(file);
          const zipFiles: File[] = [];
          for (const relativePath of Object.keys(contents.files)) {
            const zipEntry = contents.files[relativePath] as any;
            if (zipEntry.dir) continue;
            const blob = await zipEntry.async('blob');
            const fileName = relativePath.split('/').pop() || 'unnamed';
            zipFiles.push(new File([blob], fileName, { type: getMimeTypeFromExtension(fileName) }));
          }
          if (zipFiles.length > 0) await processFiles(zipFiles);
        } catch (err) {
          console.error("ZIP Error:", err);
        }
        continue;
      }

      const isText = TEXT_EXTENSIONS.includes(extension) || file.type.startsWith('text/');
      const isSupportedMedia = SUPPORTED_MIME_TYPES.includes(file.type);

      if (isText) {
        const text = await file.text();
        setPreviews(prev => [...prev, { 
          id: uniqueId, 
          mimeType: 'text/plain', 
          name: file.name, 
          fileName: file.name, 
          textContent: text 
        }].slice(-50)); // 提高上限到 50 个文件
      } else if (isSupportedMedia) {
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64Data = (reader.result as string).split(',')[1];
          setPreviews(prev => [...prev, { 
            id: uniqueId, 
            data: base64Data, 
            mimeType: file.type, 
            name: file.name, 
            fileName: file.name 
          }].slice(-50));
        };
        reader.readAsDataURL(file);
      }
    }
    setIsProcessing(false);
  };

  const getMimeTypeFromExtension = (fileName: string): string => {
    const ext = fileName.split('.').pop()?.toLowerCase();
    const map: Record<string, string> = {
      'png': 'image/png', 'jpg': 'image/jpeg', 'jpeg': 'image/jpeg',
      'webp': 'image/webp', 'pdf': 'application/pdf', 'txt': 'text/plain'
    };
    return map[ext || ''] || 'application/octet-stream';
  };

  const handlePaste = (e: ClipboardEvent<HTMLInputElement>) => {
    const items = e.clipboardData.items;
    const filesToProcess: File[] = [];
    for (let i = 0; i < items.length; i++) {
      if (items[i].kind === 'file') {
        const file = items[i].getAsFile();
        if (file) filesToProcess.push(file);
      }
    }
    if (filesToProcess.length > 0) {
      processFiles(filesToProcess);
    }
  };

  return (
    <div className="p-4 border-t border-slate-800 bg-slate-900/80 backdrop-blur-xl relative">
      <div className="max-w-4xl mx-auto flex flex-col gap-3">
        {(isProcessing) && (
          <div className="flex items-center gap-2 text-[10px] text-blue-400 font-bold animate-pulse px-2">
            <svg className="animate-spin h-3 w-3" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
            正在处理多媒体附件...
          </div>
        )}

        {previews.length > 0 && (
          <div className="flex items-end gap-3 animate-in fade-in slide-in-from-bottom-2">
            <div className="flex-1 flex gap-2 overflow-x-auto pb-2 scrollbar-hide pt-2 px-1">
              {previews.map((preview) => (
                <div key={preview.id} className="relative flex-shrink-0 group">
                  <div className={`w-16 h-16 rounded-xl border border-slate-700/50 overflow-hidden flex flex-col items-center justify-center shadow-lg transition-transform group-hover:scale-105 ${preview.textContent ? 'bg-emerald-500/10' : 'bg-slate-800'}`}>
                    {preview.mimeType.includes('image') && preview.data ? (
                      <img src={`data:${preview.mimeType};base64,${preview.data}`} className="w-full h-full object-cover" alt="Preview" />
                    ) : (
                      <div className="flex flex-col items-center p-1">
                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 ${preview.textContent ? 'text-emerald-400' : preview.mimeType.includes('pdf') ? 'text-red-400' : 'text-blue-400'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                        </svg>
