        tools: [{ functionDeclarations: historyToolDeclarations }],
        systemInstruction: `你是一个专家级的多模态分析助手。
关键指令：
1. **多图/多文档联动分析**：当用户上传多张图片或多个文件时，你应该进行对比、关联和深度整合分析，而不仅仅是逐一描述。
2. **异构数据处理**：能够理解代码片段、PDF文档、LaTeX公式与图片内容之间的逻辑联系。
3. **空间管理**：若收到清空或删除指令，请务必调用对应的 function 并在回复中确认。
4. **输出质量**：使用清晰的 Markdown 格式，重要结论请加粗。`,
      },
    });

    return {
      text: response.text,
      functionCalls: response.functionCalls
    };
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const generateVideo = async (prompt: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  let operation = await ai.models.generateVideos({
    model: 'veo-3.1-fast-generate-preview',
    prompt: prompt,
    config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
  });
  while (!operation.done) {
    await new Promise(resolve => setTimeout(resolve, 10000));
    operation = await ai.operations.getVideosOperation({ operation: operation });
  }
  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  if (!downloadLink) throw new Error("Video link not found.");
  const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
  const blob = await response.blob();
  return URL.createObjectURL(blob);
};

export const textToSpeech = async (text: string): Promise<Uint8Array> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Read this naturally: ${text.slice(0, 1000)}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("No audio data received.");

  const binaryString = atob(base64Audio);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useEffect, useRef, useState } from 'react';
import { Message } from '../types';
import Markdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { atomDark } from 'react-syntax-highlighter/dist/esm/styles/prism';
import { textToSpeech, decodeAudioData } from '../services/geminiService';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  isGeneratingVideo: boolean;
  onDeleteMessage: (id: string) => void;
  onEditMessage: (content: string) => void;
}

const MessageList: React.FC<MessageListProps> = ({ messages, isThinking, isGeneratingVideo, onDeleteMessage, onEditMessage }) => {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [playingId, setPlayingId] = useState<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isThinking, isGeneratingVideo]);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    alert('内容已复制到剪贴板');
  };

  const handleSpeak = async (id: string, text: string) => {
    if (playingId) return;
    setPlayingId(id);
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      const ctx = audioContextRef.current;
      const audioData = await textToSpeech(text);
      const buffer = await decodeAudioData(audioData, ctx);
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setPlayingId(null);
      source.start();
    } catch (err) {
      console.error("TTS Error:", err);
      setPlayingId(null);
    }
  };

  const handleDownloadFile = (content: string, language: string) => {
    const extensions: Record<string, string> = { 'latex': 'tex', 'tex': 'tex', 'javascript': 'js', 'typescript': 'ts', 'python': 'py', 'markdown': 'md', 'html': 'html', 'css': 'css', 'json': 'json', 'java': 'java', 'cpp': 'cpp', 'c': 'c' };
    const ext = extensions[language.toLowerCase()] || 'txt';
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
