                 </button>
               )}
            </div>

            <div className="flex items-center mb-2 gap-2 opacity-60">
               <span className="text-[10px] font-bold uppercase tracking-wider">{msg.role === 'user' ? 'YOU' : 'GEMINI'}</span>
