            {msg.mediaItems && msg.mediaItems.length > 0 && (
              <div className={`grid gap-2 mb-3 ${msg.mediaItems.length === 1 ? 'grid-cols-1' : 'grid-cols-2 md:grid-cols-3'}`}>
