export default MessageList;

import React, { useState, FormEvent, useRef, ClipboardEvent, useImperativeHandle, forwardRef } from 'react';
import { MessageMedia } from '../types';
import JSZip from 'jszip';

interface ChatInputProps {
  onSendMessage: (message: string, media?: MessageMedia[]) => void;
  onGenerateVideo: (prompt: string) => void;
  disabled: boolean;
}

const SUPPORTED_MIME_TYPES = [
  'image/png', 'image/jpeg', 'image/webp', 'image/heic', 'image/heif',
  'application/pdf'
];

const TEXT_EXTENSIONS = [
  'tex', 'txt', 'md', 'js', 'jsx', 'ts', 'tsx', 'py', 'java', 'c', 'cpp', 'h', 'css', 'html', 'json', 'xml', 'yaml', 'yml', 'sql'
];

const ChatInput = forwardRef((props: ChatInputProps, ref) => {
  const { onSendMessage, onGenerateVideo, disabled } = props;
  const [input, setInput] = useState('');
  const [mode, setMode] = useState<'chat' | 'video'>('chat');
  const [previews, setPreviews] = useState<(MessageMedia & { id: string; name: string })[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useImperativeHandle(ref, () => ({
    addFiles: (files: FileList | File[]) => {
      processFiles(files);
    },
    setInput: (text: string) => {
      setInput(text);
      setMode('chat');
    }
  }));

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const val = input.trim();
    if (!val && previews.length === 0) return;

    if (mode === 'video') {
      onGenerateVideo(val || "一段科幻大片视频");
      setInput('');
    } else {
      onSendMessage(val, previews.length > 0 ? previews : undefined);
      setInput('');
      setPreviews([]);
    }
  };

  const processFiles = async (files: FileList | File[]) => {
    setIsProcessing(true);
    const newFiles = Array.from(files);

    for (const file of newFiles) {
      const uniqueId = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      const extension = file.name.split('.').pop()?.toLowerCase() || '';

      if (extension === 'zip') {
        try {
          const zip = new JSZip();
          const contents = await zip.loadAsync(file);
          const zipFiles: File[] = [];
          for (const relativePath of Object.keys(contents.files)) {
            const zipEntry = contents.files[relativePath] as any;
            if (zipEntry.dir) continue;
            const blob = await zipEntry.async('blob');
            const fileName = relativePath.split('/').pop() || 'unnamed';
            zipFiles.push(new File([blob], fileName, { type: getMimeTypeFromExtension(fileName) }));
          }
          if (zipFiles.length > 0) await processFiles(zipFiles);
        } catch (err) {
          console.error("ZIP Error:", err);
        }
        continue;
      }

      const isText = TEXT_EXTENSIONS.includes(extension) || file.type.startsWith('text/');
      const isSupportedMedia = SUPPORTED_MIME_TYPES.includes(file.type);

      if (isText) {
        const text = await file.text();
        setPreviews(prev => [...prev, { 
          id: uniqueId, 
          mimeType: 'text/plain', 
          name: file.name, 
          fileName: file.name, 
          textContent: text 
        }].slice(-50));
      } else if (isSupportedMedia) {
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64Data = (reader.result as string).split(',')[1];
          setPreviews(prev => [...prev, { 
            id: uniqueId, 
            data: base64Data, 
            mimeType: file.type, 
            name: file.name, 
            fileName: file.name 
          }].slice(-50));
        };
        reader.readAsDataURL(file);
      }
    }
    setIsProcessing(false);
  };

  const getMimeTypeFromExtension = (fileName: string): string => {
    const ext = fileName.split('.').pop()?.toLowerCase();
    const map: Record<string, string> = {
      'png': 'image/png', 'jpg': 'image/jpeg', 'jpeg': 'image/jpeg',
      'webp': 'image/webp', 'pdf': 'application/pdf', 'txt': 'text/plain'
    };
    return map[ext || ''] || 'application/octet-stream';
  };

  const handlePaste = (e: ClipboardEvent<HTMLInputElement>) => {
    const items = e.clipboardData.items;
    const filesToProcess: File[] = [];
    for (let i = 0; i < items.length; i++) {
      if (items[i].kind === 'file') {
        const file = items[i].getAsFile();
        if (file) filesToProcess.push(file);
      }
    }
    if (filesToProcess.length > 0) {
      processFiles(filesToProcess);
    }
  };

  return (
    <div className="p-4 border-t border-slate-800 bg-slate-900/80 backdrop-blur-xl relative">
      <div className="max-w-4xl mx-auto flex flex-col gap-3">
        {(isProcessing) && (
          <div className="flex items-center gap-2 text-[10px] text-blue-400 font-bold animate-pulse px-2">
            <svg className="animate-spin h-3 w-3" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
            正在处理多媒体附件...
          </div>
        )}

        {previews.length > 0 && (
          <div className="flex items-end gap-3 animate-in fade-in slide-in-from-bottom-2">
            <div className="flex-1 flex gap-2 overflow-x-auto pb-2 scrollbar-hide pt-2 px-1">
              {previews.map((preview) => (
                <div key={preview.id} className="relative flex-shrink-0 group">
                  <div className={`w-16 h-16 rounded-xl border border-slate-700/50 overflow-hidden flex flex-col items-center justify-center shadow-lg transition-transform group-hover:scale-105 ${preview.textContent ? 'bg-emerald-500/10' : 'bg-slate-800'}`}>
                    {preview.mimeType.includes('image') && preview.data ? (
                      <img src={`data:${preview.mimeType};base64,${preview.data}`} className="w-full h-full object-cover" alt="Preview" />
                    ) : (
                      <div className="flex flex-col items-center p-1">
                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 ${preview.textContent ? 'text-emerald-400' : preview.mimeType.includes('pdf') ? 'text-red-400' : 'text-blue-400'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                        </svg>
                        <span className="text-[7px] text-slate-400 truncate max-w-[50px] mt-1 text-center leading-tight">{preview.name}</span>
                      </div>
                    )}
                  </div>
                  <button 
                    onClick={() => setPreviews(p => p.filter(x => x.id !== preview.id))} 
                    className="absolute -top-2 -right-2 bg-rose-600 text-white rounded-full p-1 shadow-2xl scale-0 group-hover:scale-100 transition-all hover:bg-rose-500 z-10"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                  </button>
                </div>
              ))}
            </div>
            <button onClick={() => setPreviews([])} className="mb-2 text-[10px] font-black text-rose-500/70 hover:text-rose-400 uppercase tracking-tighter shrink-0 transition-colors">移除全部 ({previews.length})</button>
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex gap-3 items-center">
          <input type="file" multiple className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && processFiles(e.target.files)} />
          <div className="flex bg-slate-800 rounded-xl p-1 border border-slate-700 shadow-inner">
            <button type="button" onClick={() => setMode('chat')} className={`p-2.5 rounded-lg transition-all ${mode === 'chat' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>
