import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Message, ChatState, MessageMedia } from './types';
import { sendMessageWithMedia, generateVideo } from './services/geminiService';
import MessageList from './components/MessageList';
import ChatInput from './components/ChatInput';

// 固定的持久化 Key，严禁修改，否则历史会丢失
const STORAGE_KEY = 'GEMINI_OMNIVERSE_PERSISTENT_STORAGE_v2';

const App: React.FC = () => {
  // 1. 数据初始化：从磁盘恢复历史
  const [state, setState] = useState<ChatState>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        const parsed = JSON.parse(savedData);
        if (Array.isArray(parsed) && parsed.length > 0) {
          console.log("[Storage] 成功从本地恢复了", parsed.length, "条对话记录");
          return {
            messages: parsed.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
            isThinking: false,
            isGeneratingVideo: false,
            error: null
          };
        }
      }
    } catch (e) {
      console.error("[Storage] 数据恢复失败:", e);
    }
    return { messages: [], isThinking: false, isGeneratingVideo: false, error: null };
  });

  const [isDataReady, setIsDataReady] = useState(false);
  const [apiKeySelected, setApiKeySelected] = useState(false);
  const [isDragging, setIsDragging] = useState(false);

  // 用于操作输入框的 ref
  const chatInputRef = useRef<{ addFiles: (files: FileList | File[]) => void; setInput: (text: string) => void } | null>(null);

  useEffect(() => {
    const initApp = async () => {
      // @ts-ignore
      if (window.aistudio) {
        // @ts-ignore
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setApiKeySelected(hasKey);
      }
      setIsDataReady(true);
      console.log("[Storage] 数据同步锁定已解除，历史记录安全。");
    };
    initApp();
  }, []);

  useEffect(() => {
    if (!isDataReady) return;
    try {
      const dataToSave = JSON.stringify(state.messages);
      localStorage.setItem(STORAGE_KEY, dataToSave);
    } catch (e) {
      console.error("[Storage] 自动保存失败:", e);
      if (String(e).includes("QuotaExceededError")) {
        setState(prev => ({ ...prev, error: "本地存储空间已满 (5MB)，建议清理部分对话内容。" }));
      }
    }
  }, [state.messages, isDataReady]);

  const storageUsage = useMemo(() => {
    try {
      const str = JSON.stringify(state.messages);
      const bytes = new Blob([str]).size;
      return Math.min(100, Math.round((bytes / (5 * 1024 * 1024)) * 100));
    } catch (e) { return 0; }
  }, [state.messages]);

  const handleSendMessage = async (content: string, mediaItems?: MessageMedia[]) => {
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: new Date(),
      mediaItems,
      type: mediaItems?.some(m => m.mimeType.includes('pdf')) ? 'doc_analysis' : 'text'
    };

    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isThinking: true, error: null }));

    try {
      const response = await sendMessageWithMedia([...state.messages, userMsg], content, mediaItems);

      if (response.functionCalls) {
        for (const call of response.functionCalls) {
          if (call.name === 'clear_all_history') {
            setState(prev => ({ ...prev, messages: [], isThinking: false }));
            return;
          }
          if (call.name === 'delete_last_n_messages') {
            const count = call.args.count || 2;
            setState(prev => ({ ...prev, messages: prev.messages.slice(0, -count), isThinking: false }));
            return;
          }
        }
      }

      const assistantMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "...",
        timestamp: new Date(),
      };
      setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isThinking: false }));
    } catch (err: any) {
      let errorMsg = "AI 响应异常。";
      const errStr = String(err);
      if (errStr.includes("429")) errorMsg = "⚠️ Google API 每日免费额度已满，请稍后再试。";
      else if (errStr.includes("403")) errorMsg = "🚫 权限不足，请检查 API Key。";

      setState(prev => ({ ...prev, isThinking: false, error: errorMsg }));
      setTimeout(() => setState(prev => ({ ...prev, error: null })), 5000);
    }
  };

  const handleGenerateVideo = async (prompt: string) => {
    if (!apiKeySelected) {
      // @ts-ignore
      if (window.aistudio) await window.aistudio.openSelectKey();
      setApiKeySelected(true);
    }
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: `🎥 生成视频：${prompt}`, timestamp: new Date(), type: 'video_gen' };
    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isGeneratingVideo: true }));
    try {
      const url = await generateVideo(prompt);
      const assistantMsg: Message = { id: (Date.now() + 1).toString(), role: 'assistant', content: '视频已生成。', timestamp: new Date(), mediaItems: [{url, mimeType: 'video/mp4'}], type: 'video_gen' };
      setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isGeneratingVideo: false }));
    } catch (err: any) { 
      setState(prev => ({ ...prev, isGeneratingVideo: false, error: "视频生成配额不足或请求失败。" })); 
      setTimeout(() => setState(prev => ({ ...prev, error: null })), 5000);
    }
  };

  const clearAllHistory = () => {
    if (confirm('确定要清空本地保存的所有聊天记录吗？')) {
      setState(prev => ({ ...prev, messages: [] }));
      localStorage.removeItem(STORAGE_KEY);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-200 relative" 
         onDragOver={e=>{e.preventDefault();setIsDragging(true)}} 
         onDragLeave={()=>setIsDragging(false)} 
         onDrop={e=>{e.preventDefault();setIsDragging(false);e.dataTransfer.files && chatInputRef.current?.addFiles(e.dataTransfer.files)}}>

      {isDragging && <div className="absolute inset-0 z-50 bg-blue-600/20 backdrop-blur-sm border-4 border-dashed border-blue-500 flex items-center justify-center pointer-events-none"><div className="bg-slate-900 p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4"><p className="text-xl font-bold text-white">释放文件进行分析</p></div></div>}

      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-xl z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 flex items-center justify-center shadow-lg"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" viewBox="0 0 20 20" fill="currentColor"><path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM5 10a1 1 0 01-1 1H3a1 1 0 110-2h1a1 1 0 011 1zM8 16v-1a1 1 0 112 0v1a1 1 0 11-2 0zM13.536 15.657a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM6.464 14.95a1 1 0 11-1.414 1.414l-.707-.707a1 1 0 011.414-1.414l.707.707z" /></svg></div>
          <div className="flex flex-col">
            <h1 className="text-sm font-black italic tracking-tighter text-white leading-none">GEMINI OMNIVERSE</h1>
            <span className="text-[9px] text-emerald-500 font-bold flex items-center gap-1">
              <span className="w-1 h-1 bg-emerald-500 rounded-full animate-pulse"></span>
              {isDataReady ? "HISTORY SECURED" : "SYNCING..."}
            </span>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden md:flex flex-col items-end">
             <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest mb-1">Local Storage Used</span>
             <div className="flex items-center gap-2">
                <div className="w-24 h-1.5 bg-slate-800 rounded-full overflow-hidden">
                  <div className={`h-full ${storageUsage > 80 ? 'bg-rose-500' : 'bg-indigo-500'} transition-all duration-1000`} style={{ width: `${storageUsage}%` }}></div>
                </div>
                <span className={`text-[10px] font-mono ${storageUsage > 80 ? 'text-rose-400' : 'text-slate-400'}`}>{storageUsage}%</span>
             </div>
          </div>
          <button onClick={clearAllHistory} className="p-2 text-slate-500 hover:text-rose-500 transition-colors" title="彻底清除本地聊天记录">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
          </button>
        </div>
      </header>

      <MessageList 
        messages={state.messages} 
        isThinking={state.isThinking} 
        isGeneratingVideo={isGeneratingVideo} 
        onDeleteMessage={(id) => setState(prev => ({ ...prev, messages: prev.messages.filter(m => m.id !== id) }))}
        onEditMessage={(content) => chatInputRef.current?.setInput(content)}
      />

      <ChatInput 
        ref={chatInputRef}
        onSendMessage={handleSendMessage} 
        onGenerateVideo={handleGenerateVideo}
        disabled={state.isThinking || state.isGeneratingVideo} 
      />

      {state.error && (
        <div className="fixed bottom-28 left-1/2 -translate-x-1/2 z-50 w-[90%] max-w-md animate-in fade-in slide-in-from-bottom-4">
          <div className="bg-slate-900 border-2 border-rose-500/50 backdrop-blur-xl p-4 rounded-2xl shadow-2xl flex items-start gap-3">
            <div className="p-2 bg-rose-500/20 rounded-full text-rose-500">
               <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
            </div>
            <div className="flex-1">
              <h4 className="text-rose-400 font-bold text-sm">操作受限</h4>
              <p className="text-slate-400 text-xs mt-1 leading-relaxed">{state.error}</p>
              <button onClick={()=>setState(prev=>({...prev, error: null}))} className="mt-2 text-[10px] text-slate-500 hover:text-white font-bold uppercase tracking-wider">我知道了</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

