}

export interface MessageMedia {
  data?: string; // Base64 for images/docs
  mimeType: string;
  url?: string; // For generated video/files
  fileName?: string;
  textContent?: string; // For text-based files like LaTeX, source code, PPT text
}

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: Date;
  mediaItems?: MessageMedia[];
  pptData?: PPTSlide[]; // Structured data for PPT templates
  type?: 'text' | 'video_gen' | 'doc_analysis' | 'ppt_template';
