import { GoogleGenAI, Type, FunctionDeclaration, Modality } from "@google/genai";
import { Message, MessageMedia } from "../types";

const SUPPORTED_MIME_TYPES = [
  'image/png', 'image/jpeg', 'image/webp', 'image/heic', 'image/heif',
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation'
];

const historyToolDeclarations: FunctionDeclaration[] = [
  {
    name: 'clear_all_history',
    description: '完全清空所有对话记录和本地存储空间。',
    parameters: { 
      type: Type.OBJECT, 
      properties: {
        confirm: { type: Type.BOOLEAN, description: '是否确认清空。' }
      },
      required: ['confirm']
    }
  },
  {
    name: 'generate_ppt_template',
    description: '根据用户需求生成一份专业的 PPT 演示文稿模板和提纲。',
    parameters: {
      type: Type.OBJECT,
      properties: {
        topic: { type: Type.STRING, description: 'PPT 的主题' },
        slides: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING, description: '幻灯片标题' },
              content: { type: Type.ARRAY, items: { type: Type.STRING }, description: '幻灯片要点内容' },
              layoutType: { type: Type.STRING, enum: ['title', 'content', 'comparison', 'summary'], description: '布局类型' }
            },
            required: ['title', 'content']
          }
        }
      },
      required: ['topic', 'slides']
    }
  }
];

const mapToContent = (messages: Message[]) => {
  const history = messages.slice(0, -1);
  return history.map(msg => {
    const parts: any[] = [];
    let combinedText = msg.content || "";
    if (msg.mediaItems) {
      msg.mediaItems.forEach(item => {
        if (item.textContent) combinedText += `\n\n[文件内容: ${item.fileName}]\n${item.textContent}\n`;
      });
    }
    if (combinedText.trim()) parts.push({ text: combinedText });
    if (msg.mediaItems) {
      msg.mediaItems.forEach(item => {
        if (item.data && SUPPORTED_MIME_TYPES.includes(item.mimeType) && !item.mimeType.includes('presentation')) {
          parts.push({ inlineData: { data: item.data, mimeType: item.mimeType } });
        }
      });
    }
    if (parts.length === 0) parts.push({ text: "..." });
    return { role: msg.role === 'user' ? 'user' : 'model', parts };
  });
};

export const sendMessageWithMedia = async (
  fullHistory: Message[],
  currentText: string,
  mediaItems?: MessageMedia[]
): Promise<{ text?: string; functionCalls?: any[] }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  let finalPrompt = currentText;
  const currentParts: any[] = [];

  if (mediaItems) {
    mediaItems.forEach(item => {
      if (item.textContent) {
        finalPrompt += `\n\n[上传的 PPT/文件内容: ${item.fileName}]\n${item.textContent}\n`;
      }
      if (item.data && SUPPORTED_MIME_TYPES.includes(item.mimeType) && !item.mimeType.includes('presentation')) {
        currentParts.push({ inlineData: { data: item.data, mimeType: item.mimeType } });
      }
    });
  }

  currentParts.unshift({ text: finalPrompt || "请分析我上传的内容。" });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [
        ...mapToContent(fullHistory),
        { role: 'user', parts: currentParts }
      ],
      config: {
        tools: [{ functionDeclarations: historyToolDeclarations }],
        systemInstruction: `你是一个全能的多模态助手，现在已支持 PPTX 文件的解析和生成。
1. **PPT 解析**：用户上传 PPT 后，你会收到提取出的文本。请结合文本逻辑进行深度总结、翻译或问答。
2. **PPT 模板生成**：当用户需要 PPT 建议时，请调用 'generate_ppt_template' 工具。
3. **输出风格**：保持专业、干练。`,
      },
    });

    return {
      text: response.text,
      functionCalls: response.functionCalls
    };
  } catch (error: any) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

export const generateVideo = async (prompt: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  let operation = await ai.models.generateVideos({
    model: 'veo-3.1-fast-generate-preview',
    prompt: prompt,
    config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
  });
  while (!operation.done) {
    await new Promise(resolve => setTimeout(resolve, 10000));
    operation = await ai.operations.getVideosOperation({ operation: operation });
  }
  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  if (!downloadLink) throw new Error("Video link not found.");
  const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
  const blob = await response.blob();
  return URL.createObjectURL(blob);
};

export const textToSpeech = async (text: string): Promise<Uint8Array> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Read this naturally: ${text.slice(0, 1000)}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName: 'Kore' },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("No audio data received.");

  const binaryString = atob(base64Audio);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
};

export async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number = 24000,
  numChannels: number = 1,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, FormEvent, useRef, ClipboardEvent, useImperativeHandle, forwardRef } from 'react';
import { MessageMedia } from '../types';
import JSZip from 'jszip';

interface ChatInputProps {
  onSendMessage: (message: string, media?: MessageMedia[]) => void;
  onGenerateVideo: (prompt: string) => void;
  disabled: boolean;
}

const SUPPORTED_MIME_TYPES = [
  'image/png', 'image/jpeg', 'image/webp', 'image/heic', 'image/heif',
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation'
];

const TEXT_EXTENSIONS = [
  'tex', 'txt', 'md', 'js', 'jsx', 'ts', 'tsx', 'py', 'java', 'c', 'cpp', 'h', 'css', 'html', 'json', 'xml', 'yaml', 'yml', 'sql'
];

const ChatInput = forwardRef((props: ChatInputProps, ref) => {
  const { onSendMessage, onGenerateVideo, disabled } = props;
  const [input, setInput] = useState('');
  const [mode, setMode] = useState<'chat' | 'video'>('chat');
  const [previews, setPreviews] = useState<(MessageMedia & { id: string; name: string })[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useImperativeHandle(ref, () => ({
    addFiles: (files: FileList | File[]) => {
      processFiles(files);
    },
    setInput: (text: string) => {
      setInput(text);
      setMode('chat');
    }
  }));

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const val = input.trim();
    if (!val && previews.length === 0) return;

    if (mode === 'video') {
      onGenerateVideo(val || "一段科幻大片视频");
      setInput('');
    } else {
      onSendMessage(val, previews.length > 0 ? previews : undefined);
      setInput('');
      setPreviews([]);
    }
  };

  const parsePPTX = async (file: File): Promise<string> => {
    try {
      const zip = new JSZip();
      const content = await zip.loadAsync(file);
      const slideFiles = Object.keys(content.files).filter(name => name.startsWith('ppt/slides/slide') && name.endsWith('.xml'));

      let allText = `PPT 文件: ${file.name}\n`;

      // 排序 slide 确保顺序正确
      slideFiles.sort((a, b) => {
        const numA = parseInt(a.match(/\d+/)?[0] || '0');
        const numB = parseInt(b.match(/\d+/)?[0] || '0');
        return numA - numB;
      });

      for (const slidePath of slideFiles) {
        const slideXml = await content.files[slidePath].async('string');
        const slideNum = slidePath.match(/\d+/)?[0];

        // 简单正则提取 <a:t> 标签内的文本内容
        const matches = slideXml.match(/<a:t>([^<]+)<\/a:t>/g);
        if (matches) {
          const slideText = matches.map(m => m.replace(/<a:t>|<\/a:t>/g, '')).join(' ');
          allText += `\n[第 ${slideNum} 页]\n${slideText}\n`;
        }
      }
      return allText;
    } catch (err) {
      console.error("PPTX Parsing Error:", err);
      return `解析 PPT 失败: ${file.name}`;
    }
  };

  const processFiles = async (files: FileList | File[]) => {
    setIsProcessing(true);
    const newFiles = Array.from(files);

    for (const file of newFiles) {
      const uniqueId = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      const mimeType = file.type || getMimeTypeFromExtension(file.name);

      if (extension === 'pptx' || mimeType.includes('presentation')) {
        const extractedText = await parsePPTX(file);
        setPreviews(prev => [...prev, { 
          id: uniqueId, 
          mimeType: 'application/vnd.openxmlformats-officedocument.presentationml.presentation', 
          name: file.name, 
          fileName: file.name, 
          textContent: extractedText 
        }].slice(-50));
        continue;
      }

      if (extension === 'zip') {
        try {
          const zip = new JSZip();
          const contents = await zip.loadAsync(file);
          const zipFiles: File[] = [];
          for (const relativePath of Object.keys(contents.files)) {
            const zipEntry = contents.files[relativePath] as any;
            if (zipEntry.dir) continue;
            const blob = await zipEntry.async('blob');
            const fileName = relativePath.split('/').pop() || 'unnamed';
            zipFiles.push(new File([blob], fileName, { type: getMimeTypeFromExtension(fileName) }));
          }
          if (zipFiles.length > 0) await processFiles(zipFiles);
        } catch (err) {
          console.error("ZIP Error:", err);
        }
        continue;
      }

      const isText = TEXT_EXTENSIONS.includes(extension) || file.type.startsWith('text/');
      const isSupportedMedia = SUPPORTED_MIME_TYPES.includes(file.type);

      if (isText) {
        const text = await file.text();
        setPreviews(prev => [...prev, { 
          id: uniqueId, 
          mimeType: 'text/plain', 
          name: file.name, 
          fileName: file.name, 
          textContent: text 
        }].slice(-50));
      } else if (isSupportedMedia) {
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64Data = (reader.result as string).split(',')[1];
          setPreviews(prev => [...prev, { 
            id: uniqueId, 
            data: base64Data, 
            mimeType: file.type, 
            name: file.name, 
            fileName: file.name 
          }].slice(-50));
        };
        reader.readAsDataURL(file);
      }
    }
    setIsProcessing(false);
  };

  const getMimeTypeFromExtension = (fileName: string): string => {
    const ext = fileName.split('.').pop()?.toLowerCase();
    const map: Record<string, string> = {
      'png': 'image/png', 'jpg': 'image/jpeg', 'jpeg': 'image/jpeg',
      'webp': 'image/webp', 'pdf': 'application/pdf', 'txt': 'text/plain',
      'pptx': 'application/vnd.openxmlformats-officedocument.presentationml.presentation'
    };
    return map[ext || ''] || 'application/octet-stream';
  };

  const handlePaste = (e: ClipboardEvent<HTMLInputElement>) => {
    const items = e.clipboardData.items;
    const filesToProcess: File[] = [];
    for (let i = 0; i < items.length; i++) {
      if (items[i].kind === 'file') {
        const file = items[i].getAsFile();
        if (file) filesToProcess.push(file);
      }
    }
    if (filesToProcess.length > 0) {
      processFiles(filesToProcess);
    }
  };

  return (
    <div className="p-4 border-t border-slate-800 bg-slate-900/80 backdrop-blur-xl relative">
      <div className="max-w-4xl mx-auto flex flex-col gap-3">
        {(isProcessing) && (
          <div className="flex items-center gap-2 text-[10px] text-orange-400 font-bold animate-pulse px-2">
            <svg className="animate-spin h-3 w-3" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
            正在深度解析文件结构...
          </div>
        )}

        {previews.length > 0 && (
          <div className="flex items-end gap-3 animate-in fade-in slide-in-from-bottom-2">
            <div className="flex-1 flex gap-2 overflow-x-auto pb-2 scrollbar-hide pt-2 px-1">
              {previews.map((preview) => (
                <div key={preview.id} className="relative flex-shrink-0 group">
                  <div className={`w-16 h-16 rounded-xl border border-slate-700/50 overflow-hidden flex flex-col items-center justify-center shadow-lg transition-transform group-hover:scale-105 ${preview.mimeType.includes('presentation') ? 'bg-orange-500/10' : preview.textContent ? 'bg-emerald-500/10' : 'bg-slate-800'}`}>
                    {preview.mimeType.includes('image') && preview.data ? (
                      <img src={`data:${preview.mimeType};base64,${preview.data}`} className="w-full h-full object-cover" alt="Preview" />
                    ) : (
                      <div className="flex flex-col items-center p-1 text-center">
                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 ${preview.mimeType.includes('presentation') ? 'text-orange-500' : preview.textContent ? 'text-emerald-400' : preview.mimeType.includes('pdf') ? 'text-red-400' : 'text-blue-400'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                        </svg>
                        <span className="text-[7px] text-slate-400 truncate max-w-[50px] mt-1 leading-tight">{preview.name}</span>
                      </div>
                    )}
                  </div>
                  <button 
                    onClick={() => setPreviews(p => p.filter(x => x.id !== preview.id))} 
                    className="absolute -top-2 -right-2 bg-rose-600 text-white rounded-full p-1 shadow-2xl scale-0 group-hover:scale-100 transition-all hover:bg-rose-500 z-10"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                  </button>
                </div>
              ))}
            </div>
            <button onClick={() => setPreviews([])} className="mb-2 text-[10px] font-black text-rose-500/70 hover:text-rose-400 uppercase tracking-tighter shrink-0 transition-colors">移除全部 ({previews.length})</button>
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex gap-3 items-center">
          <input type="file" multiple className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && processFiles(e.target.files)} />
          <div className="flex bg-slate-800 rounded-xl p-1 border border-slate-700 shadow-inner">
            <button type="button" onClick={() => setMode('chat')} className={`p-2.5 rounded-lg transition-all ${mode === 'chat' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
            </button>
            <button type="button" onClick={() => setMode('video')} className={`p-2.5 rounded-lg transition-all ${mode === 'video' ? 'bg-purple-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
            </button>
          </div>
          <button type="button" onClick={() => fileInputRef.current?.click()} disabled={disabled || mode === 'video'} className="p-3 bg-slate-800/80 hover:bg-slate-700 text-slate-300 rounded-xl border border-slate-700 disabled:opacity-30 transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          </button>

          <div className="flex-1 relative">
            <input 
              type="text" 
              value={input} 
              onChange={(e) => setInput(e.target.value)} 
              onPaste={handlePaste} 
              placeholder={mode === 'video' ? "描述视频内容..." : "粘贴图片、拖入文件/PPT或输入内容..."} 
              disabled={disabled} 
              className="w-full bg-slate-800/50 border border-slate-700 rounded-xl px-4 py-3.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/50 transition-all placeholder:text-slate-600" 
            />
          </div>

          <button type="submit" disabled={(!input.trim() && previews.length === 0) || disabled} className={`rounded-xl px-6 py-3.5 transition-all font-bold tracking-tight shadow-xl ${mode === 'video' ? 'bg-purple-600 hover:bg-purple-500 shadow-purple-500/20' : 'bg-blue-600 hover:bg-blue-500 shadow-blue-500/20'} text-white disabled:opacity-50 disabled:shadow-none`}>
            {mode === 'video' ? '生成视频' : `发送 ${previews.length > 0 ? `附件(${previews.length})` : ''}`}
          </button>
        </form>
      </div>
    </div>
  );
});

