  }, [messages, isThinking, isGeneratingVideo]);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    alert('内容已复制到剪贴板');
  };

  const handleSpeak = async (id: string, text: string) => {
    if (playingId) return;
    setPlayingId(id);
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      const ctx = audioContextRef.current;
      const audioData = await textToSpeech(text);
      const buffer = await decodeAudioData(audioData, ctx);
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setPlayingId(null);
      source.start();
    } catch (err) {
      console.error("TTS Error:", err);
      setPlayingId(null);
    }
  };

  const exportPPTOutline = (slides: PPTSlide[]) => {
    const text = slides.map((s, i) => `第 ${i + 1} 页: ${s.title}\n${s.content.map(c => `• ${c}`).join('\n')}\n`).join('\n---\n\n');
    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `ppt_outline_${Date.now()}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleDownloadFile = (content: string, language: string) => {
    const extensions: Record<string, string> = { 'latex': 'tex', 'tex': 'tex', 'javascript': 'js', 'typescript': 'ts', 'python': 'py', 'markdown': 'md', 'html': 'html', 'css': 'css', 'json': 'json', 'java': 'java', 'cpp': 'cpp', 'c': 'c' };
    const ext = extensions[language.toLowerCase()] || 'txt';
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `gemini_export_${Date.now()}.${ext}`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth">
      {messages.length === 0 && !isGeneratingVideo && (
        <div className="h-full flex flex-col items-center justify-center text-slate-500 space-y-4">
          <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-blue-600 to-purple-600 flex items-center justify-center shadow-2xl">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" /></svg>
          </div>
          <h2 className="text-xl font-bold text-slate-200">Gemini Omniverse</h2>
          <p className="text-sm text-slate-500 text-center max-w-sm">
            历史记忆已在本地加锁，现已支持 PPTX 解析与模板生成。
          </p>
        </div>
      )}

      {messages.map((msg) => (
        <div key={msg.id} className={`flex group/msg ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
          <div className={`relative max-w-[90%] md:max-w-[80%] rounded-2xl p-4 shadow-sm group-hover/msg:shadow-blue-500/10 transition-all ${msg.role === 'user' ? 'message-bubble-user text-white' : 'message-bubble-ai text-slate-100'}`}>

            <div className={`absolute -top-3 ${msg.role === 'user' ? 'right-4' : 'left-4'} flex gap-1.5 opacity-0 group-hover/msg:opacity-100 transition-all scale-90 group-hover/msg:scale-100 z-30`}>
               <button onClick={() => onDeleteMessage(msg.id)} className="p-1.5 bg-rose-600 text-white rounded-lg shadow-xl hover:bg-rose-500 transition-colors" title="删除消息">
                 <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
               </button>
               {msg.role === 'assistant' && (
                 <>
                  <button onClick={() => handleCopy(msg.content)} className="p-1.5 bg-slate-800 text-slate-300 rounded-lg shadow-xl hover:bg-slate-700 hover:text-white transition-colors border border-slate-700" title="复制文本">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" /></svg>
                  </button>
                  <button onClick={() => handleSpeak(msg.id, msg.content)} disabled={!!playingId} className={`p-1.5 ${playingId === msg.id ? 'bg-blue-600 animate-pulse' : 'bg-slate-800'} text-slate-300 rounded-lg shadow-xl hover:bg-slate-700 hover:text-white transition-colors border border-slate-700`} title="朗读内容">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" /></svg>
                  </button>
                 </>
               )}
            </div>

            <div className="flex items-center mb-2 gap-2 opacity-60">
               <span className="text-[10px] font-bold uppercase tracking-wider">{msg.role === 'user' ? 'YOU' : 'GEMINI'}</span>
               <span className="text-[10px]">{msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
               {playingId === msg.id && (
                 <div className="flex gap-0.5 items-end h-3 mb-0.5">
                   <div className="w-0.5 bg-blue-400 animate-[bounce_0.6s_infinite] h-full"></div>
                   <div className="w-0.5 bg-blue-400 animate-[bounce_0.8s_infinite] h-2/3"></div>
                   <div className="w-0.5 bg-blue-400 animate-[bounce_0.5s_infinite] h-1/2"></div>
                 </div>
               )}
            </div>

            {msg.mediaItems && msg.mediaItems.length > 0 && (
              <div className={`grid gap-2 mb-3 ${msg.mediaItems.length === 1 ? 'grid-cols-1' : 'grid-cols-2 md:grid-cols-3'}`}>
                {msg.mediaItems.map((item, idx) => (
                  <div key={idx} className="relative rounded-lg overflow-hidden border border-white/10 shadow-md">
                    {item.mimeType.includes('image') && item.data ? (
                      <img src={`data:${item.mimeType};base64,${item.data}`} className="w-full h-full object-cover max-h-48" alt="Attachment" />
                    ) : item.url && item.mimeType.includes('video') ? (
                      <video controls className="w-full bg-black" src={item.url} />
                    ) : (
                      <div className="flex items-center gap-3 p-3 bg-white/5 h-20">
                        <div className={`p-2 rounded-lg ${item.mimeType.includes('presentation') ? 'bg-orange-500/20' : 'bg-slate-800'}`}>
                           <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 ${item.mimeType.includes('pdf') ? 'text-red-400' : item.mimeType.includes('presentation') ? 'text-orange-400' : 'text-blue-400'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                        </div>
                        <div className="flex flex-col min-w-0">
                          <span className="text-[11px] font-bold truncate text-slate-200">{item.fileName}</span>
                          {item.mimeType.includes('presentation') && <span className="text-[9px] text-orange-400/80 font-bold">PPTX 文件已解析</span>}
                        </div>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}

            {/* PPT 模板渲染器 */}
            {msg.type === 'ppt_template' && msg.pptData && (
              <div className="space-y-4 mb-4 mt-2">
                <div className="flex items-center justify-between mb-2">
                  <h3 className="text-orange-400 font-bold text-sm uppercase tracking-wider flex items-center gap-2">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                    PPT 演示文稿建议
                  </h3>
                  <button onClick={() => exportPPTOutline(msg.pptData!)} className="text-[10px] bg-orange-600 hover:bg-orange-500 text-white px-2 py-1 rounded font-bold transition-colors">导出大纲</button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {msg.pptData.map((slide, idx) => (
                    <div key={idx} className="aspect-video bg-slate-900 border border-slate-700 rounded-xl overflow-hidden flex flex-col shadow-lg hover:border-orange-500/50 transition-colors group/slide">
                      <div className={`h-8 flex items-center px-3 text-[10px] font-bold uppercase tracking-tighter ${slide.layoutType === 'title' ? 'bg-orange-600 text-white' : 'bg-slate-800 text-slate-400'}`}>
                        Slide {idx + 1} {slide.layoutType && `• ${slide.layoutType}`}
                      </div>
                      <div className="flex-1 p-4 flex flex-col justify-center bg-gradient-to-br from-transparent to-slate-800/20">
                         <h4 className={`font-bold mb-2 leading-tight ${slide.layoutType === 'title' ? 'text-lg text-center' : 'text-sm text-orange-400'}`}>{slide.title}</h4>
                         <ul className="space-y-1">
                           {slide.content.map((point, pIdx) => (
                             <li key={pIdx} className="text-[11px] text-slate-300 flex items-start gap-2">
                               <span className="text-orange-500 mt-1">•</span>
                               <span className="flex-1">{point}</span>
                             </li>
                           ))}
                         </ul>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="markdown-content text-sm md:text-[15px] leading-relaxed">
              <Markdown remarkPlugins={[remarkGfm]} components={{
                code({node, inline, className, children, ...props}: any) {
                  const match = /language-(\w+)/.exec(className || '');
                  const lang = match ? match[1] : '';
                  const content = String(children).replace(/\n$/, '');
                  return !inline && match ? (
                    <div className="relative group/code my-4">
                      <div className="absolute right-2 top-2 z-10 flex gap-2 opacity-0 group-hover/code:opacity-100 transition-opacity">
                         <button onClick={() => handleDownloadFile(content, lang)} className="bg-slate-800/80 hover:bg-blue-600 text-white text-[10px] px-2 py-1 rounded border border-white/10 backdrop-blur-sm flex items-center gap-1 transition-colors">
                           <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                           导出 .{lang === 'latex' ? 'tex' : lang}
                         </button>
                      </div>
                      <SyntaxHighlighter style={atomDark} language={lang} PreTag="div" {...props}>{content}</SyntaxHighlighter>
                    </div>
                  ) : <code className={`${className} bg-slate-950/50 px-1.5 py-0.5 rounded text-blue-300 font-mono text-xs`} {...props}>{children}</code>;
                }
              }}>{msg.content}</Markdown>
            </div>
          </div>
        </div>
      ))}

      {(isThinking || isGeneratingVideo) && (
        <div className="flex justify-start animate-pulse">
          <div className="message-bubble-ai text-slate-100 p-4 rounded-2xl flex items-center gap-2">
            <div className="w-2 h-2 bg-orange-400 rounded-full animate-bounce"></div>
            <div className="w-2 h-2 bg-orange-400 rounded-full animate-bounce [animation-delay:-.3s]"></div>
            <div className="w-2 h-2 bg-orange-400 rounded-full animate-bounce [animation-delay:-.5s]"></div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MessageList;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Message, ChatState, MessageMedia } from './types';
import { sendMessageWithMedia, generateVideo } from './services/geminiService';
import MessageList from './components/MessageList';
import ChatInput from './components/ChatInput';

// 固定的持久化 Key，严禁修改，否则历史会丢失
const STORAGE_KEY = 'GEMINI_OMNIVERSE_PERSISTENT_STORAGE_v2';

const App: React.FC = () => {
  // 1. 数据初始化：从磁盘恢复历史
  const [state, setState] = useState<ChatState>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        const parsed = JSON.parse(savedData);
        if (Array.isArray(parsed) && parsed.length > 0) {
          console.log("[Storage] 成功从本地恢复了", parsed.length, "条对话记录");
          return {
            messages: parsed.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
            isThinking: false,
            isGeneratingVideo: false,
            error: null
          };
        }
      }
    } catch (e) {
      console.error("[Storage] 数据恢复失败:", e);
    }
    return { messages: [], isThinking: false, isGeneratingVideo: false, error: null };
  });

  const [isDataReady, setIsDataReady] = useState(false);
  const [apiKeySelected, setApiKeySelected] = useState(false);
  const [isDragging, setIsDragging] = useState(false);

  // 用于操作输入框的 ref
  const chatInputRef = useRef<{ addFiles: (files: FileList | File[]) => void; setInput: (text: string) => void } | null>(null);

  useEffect(() => {
    const initApp = async () => {
      // @ts-ignore
      if (window.aistudio) {
        // @ts-ignore
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setApiKeySelected(hasKey);
      }
      setIsDataReady(true);
      console.log("[Storage] 数据同步锁定已解除，历史记录安全。");
    };
    initApp();
  }, []);

  useEffect(() => {
    if (!isDataReady) return;
    try {
      const dataToSave = JSON.stringify(state.messages);
      localStorage.setItem(STORAGE_KEY, dataToSave);
    } catch (e) {
      console.error("[Storage] 自动保存失败:", e);
      if (String(e).includes("QuotaExceededError")) {
        setState(prev => ({ ...prev, error: "本地存储空间已满 (5MB)，建议清理部分对话内容。" }));
      }
    }
  }, [state.messages, isDataReady]);

  const storageUsage = useMemo(() => {
    try {
      const str = JSON.stringify(state.messages);
      const bytes = new Blob([str]).size;
      return Math.min(100, Math.round((bytes / (5 * 1024 * 1024)) * 100));
    } catch (e) { return 0; }
  }, [state.messages]);

  const handleSendMessage = async (content: string, mediaItems?: MessageMedia[]) => {
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: new Date(),
      mediaItems,
      type: mediaItems?.some(m => m.mimeType.includes('pdf')) ? 'doc_analysis' : 'text'
    };

    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isThinking: true, error: null }));

    try {
      const response = await sendMessageWithMedia([...state.messages, userMsg], content, mediaItems);

      if (response.functionCalls) {
        for (const call of response.functionCalls) {
          if (call.name === 'clear_all_history') {
            setState(prev => ({ ...prev, messages: [], isThinking: false }));
            return;
          }
          if (call.name === 'delete_last_n_messages') {
            const count = call.args.count || 2;
            setState(prev => ({ ...prev, messages: prev.messages.slice(0, -count), isThinking: false }));
            return;
          }
          if (call.name === 'generate_ppt_template') {
            const assistantMsg: Message = {
              id: (Date.now() + 1).toString(),
              role: 'assistant',
              content: `根据您的需求，我为您策划了关于 **${call.args.topic}** 的演示文稿提纲。`,
              timestamp: new Date(),
              type: 'ppt_template',
              pptData: call.args.slides
            };
            setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isThinking: false }));
            return;
          }
        }
      }

      const assistantMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "...",
        timestamp: new Date(),
      };
      setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isThinking: false }));
    } catch (err: any) {
      let errorMsg = "AI 响应异常。";
      const errStr = String(err);
      if (errStr.includes("429")) errorMsg = "⚠️ Google API 每日免费额度已满，请稍后再试。";
      else if (errStr.includes("403")) errorMsg = "🚫 权限不足，请检查 API Key。";

      setState(prev => ({ ...prev, isThinking: false, error: errorMsg }));
      setTimeout(() => setState(prev => ({ ...prev, error: null })), 5000);
    }
  };

  const handleGenerateVideo = async (prompt: string) => {
    if (!apiKeySelected) {
      // @ts-ignore
      if (window.aistudio) await window.aistudio.openSelectKey();
      setApiKeySelected(true);
    }
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: `🎥 生成视频：${prompt}`, timestamp: new Date(), type: 'video_gen' };
    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isGeneratingVideo: true }));
    try {
      const url = await generateVideo(prompt);
      const assistantMsg: Message = { id: (Date.now() + 1).toString(), role: 'assistant', content: '视频已生成。', timestamp: new Date(), mediaItems: [{url, mimeType: 'video/mp4'}], type: 'video_gen' };
      setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isGeneratingVideo: false }));
    } catch (err: any) { 
      setState(prev => ({ ...prev, isGeneratingVideo: false, error: "视频生成配额不足或请求失败。" })); 
      setTimeout(() => setState(prev => ({ ...prev, error: null })), 5000);
    }
  };

  const clearAllHistory = () => {
    if (confirm('确定要清空本地保存的所有聊天记录吗？')) {
      setState(prev => ({ ...prev, messages: [] }));
      localStorage.removeItem(STORAGE_KEY);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-200 relative" 
         onDragOver={e=>{e.preventDefault();setIsDragging(true)}} 
         onDragLeave={()=>setIsDragging(false)} 
         onDrop={e=>{e.preventDefault();setIsDragging(false);e.dataTransfer.files && chatInputRef.current?.addFiles(e.dataTransfer.files)}}>

      {isDragging && <div className="absolute inset-0 z-50 bg-blue-600/20 backdrop-blur-sm border-4 border-dashed border-blue-500 flex items-center justify-center pointer-events-none"><div className="bg-slate-900 p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4"><p className="text-xl font-bold text-white">释放文件进行分析</p></div></div>}

      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-xl z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 flex items-center justify-center shadow-lg"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" viewBox="0 0 20 20" fill="currentColor"><path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM5 10a1 1 0 01-1 1H3a1 1 0 110-2h1a1 1 0 011 1zM8 16v-1a1 1 0 112 0v1a1 1 0 11-2 0zM13.536 15.657a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM6.464 14.95a1 1 0 11-1.414 1.414l-.707-.707a1 1 0 011.414-1.414l.707.707z" /></svg></div>
          <div className="flex flex-col">
            <h1 className="text-sm font-black italic tracking-tighter text-white leading-none">GEMINI OMNIVERSE</h1>
            <span className="text-[9px] text-emerald-500 font-bold flex items-center gap-1">
              <span className="w-1 h-1 bg-emerald-500 rounded-full animate-pulse"></span>
              {isDataReady ? "HISTORY SECURED" : "SYNCING..."}
            </span>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden md:flex flex-col items-end">
             <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest mb-1">Local Storage Used</span>
             <div className="flex items-center gap-2">
                <div className="w-24 h-1.5 bg-slate-800 rounded-full overflow-hidden">
                  <div className={`h-full ${storageUsage > 80 ? 'bg-rose-500' : 'bg-indigo-500'} transition-all duration-1000`} style={{ width: `${storageUsage}%` }}></div>
                </div>
                <span className={`text-[10px] font-mono ${storageUsage > 80 ? 'text-rose-400' : 'text-slate-400'}`}>{storageUsage}%</span>
             </div>
          </div>
          <button onClick={clearAllHistory} className="p-2 text-slate-500 hover:text-rose-500 transition-colors" title="彻底清除本地聊天记录">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
          </button>
        </div>
      </header>

      <MessageList 
        messages={state.messages} 
        isThinking={state.isThinking} 
        isGeneratingVideo={state.isGeneratingVideo} 
        onDeleteMessage={(id) => setState(prev => ({ ...prev, messages: prev.messages.filter(m => m.id !== id) }))}
        onEditMessage={(content) => chatInputRef.current?.setInput(content)}
      />

      <ChatInput 
        ref={chatInputRef}
        onSendMessage={handleSendMessage} 
        onGenerateVideo={handleGenerateVideo}
        disabled={state.isThinking || state.isGeneratingVideo} 
      />

      {state.error && (
        <div className="fixed bottom-28 left-1/2 -translate-x-1/2 z-50 w-[90%] max-w-md animate-in fade-in slide-in-from-bottom-4">
          <div className="bg-slate-900 border-2 border-rose-500/50 backdrop-blur-xl p-4 rounded-2xl shadow-2xl flex items-start gap-3">
            <div className="p-2 bg-rose-500/20 rounded-full text-rose-500">
               <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
            </div>
            <div className="flex-1">
              <h4 className="text-rose-400 font-bold text-sm">操作受限</h4>
              <p className="text-slate-400 text-xs mt-1 leading-relaxed">{state.error}</p>
              <button onClick={()=>setState(prev=>({...prev, error: null}))} className="mt-2 text-[10px] text-slate-500 hover:text-white font-bold uppercase tracking-wider">我知道了</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Message, ChatState, MessageMedia } from './types';
import { sendMessageWithMedia, generateVideo } from './services/geminiService';
import MessageList from './components/MessageList';
import ChatInput from './components/ChatInput';

const STORAGE_KEY = 'GEMINI_OMNIVERSE_PERSISTENT_STORAGE_v2';

const App: React.FC = () => {
  const [state, setState] = useState<ChatState>(() => {
    try {
      const savedData = localStorage.getItem(STORAGE_KEY);
      if (savedData) {
        const parsed = JSON.parse(savedData);
        if (Array.isArray(parsed) && parsed.length > 0) {
          return {
            messages: parsed.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
            isThinking: false,
            isGeneratingVideo: false,
            error: null
          };
        }
      }
    } catch (e) {
      console.error("[Storage] Restore failed:", e);
    }
    return { messages: [], isThinking: false, isGeneratingVideo: false, error: null };
  });

  const [isDataReady, setIsDataReady] = useState(false);
  const [apiKeySelected, setApiKeySelected] = useState(false);
  const [isDragging, setIsDragging] = useState(false);

  const chatInputRef = useRef<{ addFiles: (files: FileList | File[]) => void; setInput: (text: string) => void } | null>(null);

  useEffect(() => {
    const initApp = async () => {
      // @ts-ignore
      if (window.aistudio) {
        // @ts-ignore
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setApiKeySelected(hasKey);
      }
      setIsDataReady(true);
    };
    initApp();
  }, []);

  useEffect(() => {
    if (!isDataReady) return;
    try {
      const dataToSave = JSON.stringify(state.messages);
      localStorage.setItem(STORAGE_KEY, dataToSave);
    } catch (e) {
      console.error("[Storage] Auto-save failed:", e);
      if (String(e).includes("QuotaExceededError")) {
        setState(prev => ({ ...prev, error: "本地存储空间已满 (5MB)，建议清理部分对话内容。" }));
      }
    }
  }, [state.messages, isDataReady]);

  const storageUsage = useMemo(() => {
    try {
      const str = JSON.stringify(state.messages);
      const bytes = new Blob([str]).size;
      return Math.min(100, Math.round((bytes / (5 * 1024 * 1024)) * 100));
    } catch (e) { return 0; }
  }, [state.messages]);

  const handleSendMessage = async (content: string, mediaItems?: MessageMedia[]) => {
    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content,
      timestamp: new Date(),
      mediaItems,
      type: mediaItems?.some(m => m.mimeType.includes('pdf')) ? 'doc_analysis' : 'text'
    };

    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isThinking: true, error: null }));

    try {
      const response = await sendMessageWithMedia([...state.messages, userMsg], content, mediaItems);

      if (response.functionCalls) {
        for (const call of response.functionCalls) {
          if (call.name === 'clear_all_history') {
            setState(prev => ({ ...prev, messages: [], isThinking: false }));
            localStorage.removeItem(STORAGE_KEY);
            return;
          }
          if (call.name === 'delete_last_n_messages') {
            const count = call.args.count || 2;
            setState(prev => ({ ...prev, messages: prev.messages.slice(0, -count), isThinking: false }));
            return;
          }
          if (call.name === 'generate_ppt_template') {
            const assistantMsg: Message = {
              id: (Date.now() + 1).toString(),
              role: 'assistant',
              content: `根据您的需求，我为您策划了关于 **${call.args.topic}** 的演示文稿提纲。`,
              timestamp: new Date(),
              type: 'ppt_template',
              pptData: call.args.slides
            };
            setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isThinking: false }));
            return;
          }
        }
      }

      const assistantMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.text || "...",
        timestamp: new Date(),
      };
      setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isThinking: false }));
    } catch (err: any) {
      let errorMsg = "AI 响应异常。";
      const errStr = String(err);
      if (errStr.includes("429")) errorMsg = "⚠️ Google API 每日免费额度已满，请稍后再试。";
      else if (errStr.includes("403")) errorMsg = "🚫 权限不足，请检查 API Key。";

      setState(prev => ({ ...prev, isThinking: false, error: errorMsg }));
      setTimeout(() => setState(p => ({ ...p, error: null })), 5000);
    }
  };

  const handleGenerateVideo = async (prompt: string) => {
    if (!apiKeySelected) {
      // @ts-ignore
      if (window.aistudio) await window.aistudio.openSelectKey();
      setApiKeySelected(true);
    }
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: `🎥 生成视频：${prompt}`, timestamp: new Date(), type: 'video_gen' };
    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isGeneratingVideo: true }));
    try {
      const url = await generateVideo(prompt);
      const assistantMsg: Message = { id: (Date.now() + 1).toString(), role: 'assistant', content: '视频已生成。', timestamp: new Date(), mediaItems: [{url, mimeType: 'video/mp4'}], type: 'video_gen' };
      setState(prev => ({ ...prev, messages: [...state.messages, userMsg, assistantMsg], isGeneratingVideo: false }));
    } catch (err: any) { 
      setState(prev => ({ ...prev, isGeneratingVideo: false, error: "视频生成配额不足或请求失败。" })); 
      setTimeout(() => setState(p => ({ ...p, error: null })), 5000);
    }
  };

  const clearAllHistory = () => {
    if (confirm('确定要清空本地保存的所有聊天记录吗？')) {
      setState(prev => ({ ...prev, messages: [] }));
      localStorage.removeItem(STORAGE_KEY);
    }
  };

  return (
    <div 
      className="flex flex-col h-screen bg-[#020617] text-slate-200 relative" 
      onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }} 
      onDragLeave={() => setIsDragging(false)} 
      onDrop={(e) => { 
        e.preventDefault(); 
        setIsDragging(false); 
        if (e.dataTransfer.files) {
          chatInputRef.current?.addFiles(e.dataTransfer.files);
        }
      }}
    >

      {isDragging && (
        <div className="absolute inset-0 z-50 bg-blue-600/20 backdrop-blur-sm border-4 border-dashed border-blue-500 flex items-center justify-center pointer-events-none">
          <div className="bg-slate-900 p-8 rounded-3xl shadow-2xl flex flex-col items-center gap-4">
            <p className="text-xl font-bold text-white">释放文件进行分析</p>
          </div>
        </div>
      )}

      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-xl z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 flex items-center justify-center shadow-lg">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" viewBox="0 0 20 20" fill="currentColor">
              <path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM5 10a1 1 0 01-1 1H3a1 1 0 110-2h1a1 1 0 011 1zM8 16v-1a1 1 0 112 0v1a1 1 0 11-2 0zM13.536 15.657a1 1 0 001.414-1.414l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM6.464 14.95a1 1 0 11-1.414 1.414l-.707-.707a1 1 0 011.414-1.414l.707.707z" />
            </svg>
          </div>
          <div className="flex flex-col">
            <h1 className="text-sm font-black italic tracking-tighter text-white leading-none">GEMINI OMNIVERSE</h1>
            <span className="text-[9px] text-emerald-500 font-bold flex items-center gap-1">
              <span className="w-1 h-1 bg-emerald-500 rounded-full animate-pulse"></span>
              {isDataReady ? "HISTORY SECURED" : "SYNCING..."}
            </span>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden md:flex flex-col items-end">
             <span className="text-[9px] text-slate-500 font-bold uppercase tracking-widest mb-1">Local Storage Used</span>
             <div className="flex items-center gap-2">
                <div className="w-24 h-1.5 bg-slate-800 rounded-full overflow-hidden">
                  <div className={`h-full ${storageUsage > 80 ? 'bg-rose-500' : 'bg-indigo-500'} transition-all duration-1000`} style={{ width: `${storageUsage}%` }}></div>
                </div>
                <span className={`text-[10px] font-mono ${storageUsage > 80 ? 'text-rose-400' : 'text-slate-400'}`}>{storageUsage}%</span>
             </div>
          </div>
          <button onClick={clearAllHistory} className="p-2 text-slate-500 hover:text-rose-500 transition-colors" title="彻底清除本地聊天记录">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
            </svg>
          </button>
        </div>
      </header>

      <MessageList 
        messages={state.messages} 
        isThinking={state.isThinking} 
        isGeneratingVideo={state.isGeneratingVideo} 
        onDeleteMessage={(id) => setState(prev => ({ ...prev, messages: prev.messages.filter(m => m.id !== id) }))}
        onEditMessage={(content) => chatInputRef.current?.setInput(content)}
      />

      <ChatInput 
        ref={chatInputRef}
        onSendMessage={handleSendMessage} 
        onGenerateVideo={handleGenerateVideo}
        disabled={state.isThinking || state.isGeneratingVideo} 
      />

      {state.error && (
        <div className="fixed bottom-28 left-1/2 -translate-x-1/2 z-50 w-[90%] max-w-md animate-in fade-in slide-in-from-bottom-4">
          <div className="bg-slate-900 border-2 border-rose-500/50 backdrop-blur-xl p-4 rounded-2xl shadow-2xl flex items-start gap-3">
            <div className="p-2 bg-rose-500/20 rounded-full text-rose-500">
               <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
               </svg>
            </div>
            <div className="flex-1">
              <h4 className="text-rose-400 font-bold text-sm">操作受限</h4>
              <p className="text-slate-400 text-xs mt-1 leading-relaxed">{state.error}</p>
              <button onClick={() => setState(prev => ({ ...prev, error: null }))} className="mt-2 text-[10px] text-slate-500 hover:text-white font-bold uppercase tracking-wider">我知道了</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, FormEvent, useRef, ClipboardEvent, useImperativeHandle, forwardRef } from 'react';
import { MessageMedia } from '../types';
import JSZip from 'jszip';

interface ChatInputProps {
  onSendMessage: (message: string, media?: MessageMedia[]) => void;
  onGenerateVideo: (prompt: string) => void;
  disabled: boolean;
}

const SUPPORTED_MIME_TYPES = [
  'image/png', 'image/jpeg', 'image/webp', 'image/heic', 'image/heif',
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation'
];

const TEXT_EXTENSIONS = [
  'tex', 'txt', 'md', 'js', 'jsx', 'ts', 'tsx', 'py', 'java', 'c', 'cpp', 'h', 'css', 'html', 'json', 'xml', 'yaml', 'yml', 'sql'
];

const ChatInput = forwardRef((props: ChatInputProps, ref) => {
  const { onSendMessage, onGenerateVideo, disabled } = props;
  const [input, setInput] = useState('');
  const [mode, setMode] = useState<'chat' | 'video'>('chat');
  const [previews, setPreviews] = useState<(MessageMedia & { id: string; name: string })[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useImperativeHandle(ref, () => ({
    addFiles: (files: FileList | File[]) => {
      processFiles(files);
    },
    setInput: (text: string) => {
      setInput(text);
      setMode('chat');
    }
  }));

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const val = input.trim();
    if (!val && previews.length === 0) return;

    if (mode === 'video') {
      onGenerateVideo(val || "一段科幻大片视频");
      setInput('');
    } else {
      onSendMessage(val, previews.length > 0 ? previews : undefined);
      setInput('');
      setPreviews([]);
    }
  };

  const parsePPTX = async (file: File): Promise<string> => {
    try {
      const zip = new JSZip();
      const content = await zip.loadAsync(file);
      const slideFiles = Object.keys(content.files).filter(name => name.startsWith('ppt/slides/slide') && name.endsWith('.xml'));

      let allText = `PPT 文件: ${file.name}\n`;

      slideFiles.sort((a, b) => {
        const numA = parseInt(a.match(/\d+/)?[0] || '0');
        const numB = parseInt(b.match(/\d+/)?[0] || '0');
        return numA - numB;
      });

      for (const slidePath of slideFiles) {
        const slideXml = await content.files[slidePath].async('string');
        const slideNum = slidePath.match(/\d+/)?[0];
        const matches = slideXml.match(/<a:t>([^<]+)<\/a:t>/g);
        if (matches) {
          const slideText = matches.map(m => m.replace(/<a:t>|<\/a:t>/g, '')).join(' ');
          allText += `\n[第 ${slideNum} 页]\n${slideText}\n`;
        }
      }
      return allText;
    } catch (err) {
      console.error("PPTX Parsing Error:", err);
      return `解析 PPT 失败: ${file.name}`;
    }
  };

  const processFiles = async (files: FileList | File[]) => {
    setIsProcessing(true);
    const newFiles = Array.from(files);

    for (const file of newFiles) {
      const uniqueId = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      const extension = file.name.split('.').pop()?.toLowerCase() || '';
      const mimeType = file.type || getMimeTypeFromExtension(file.name);

      if (extension === 'pptx' || mimeType.includes('presentation')) {
        const extractedText = await parsePPTX(file);
        setPreviews(prev => [...prev, { 
          id: uniqueId, 
          mimeType: 'application/vnd.openxmlformats-officedocument.presentationml.presentation', 
          name: file.name, 
          fileName: file.name, 
          textContent: extractedText 
        }].slice(-50));
        continue;
      }

      if (extension === 'zip') {
        try {
          const zip = new JSZip();
          const contents = await zip.loadAsync(file);
          const zipFiles: File[] = [];
          for (const relativePath of Object.keys(contents.files)) {
            const zipEntry = contents.files[relativePath] as any;
            if (zipEntry.dir) continue;
            const blob = await zipEntry.async('blob');
            const fileName = relativePath.split('/').pop() || 'unnamed';
            zipFiles.push(new File([blob], fileName, { type: getMimeTypeFromExtension(fileName) }));
          }
          if (zipFiles.length > 0) await processFiles(zipFiles);
        } catch (err) {
          console.error("ZIP Error:", err);
        }
        continue;
      }

      const isText = TEXT_EXTENSIONS.includes(extension) || file.type.startsWith('text/');
      const isSupportedMedia = SUPPORTED_MIME_TYPES.includes(file.type);

      if (isText) {
        const text = await file.text();
        setPreviews(prev => [...prev, { 
          id: uniqueId, 
          mimeType: 'text/plain', 
          name: file.name, 
          fileName: file.name, 
          textContent: text 
        }].slice(-50));
      } else if (isSupportedMedia) {
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64Data = (reader.result as string).split(',')[1];
          setPreviews(prev => [...prev, { 
            id: uniqueId, 
            data: base64Data, 
            mimeType: file.type, 
            name: file.name, 
            fileName: file.name 
          }].slice(-50));
        };
        reader.readAsDataURL(file);
      }
    }
    setIsProcessing(false);
  };

  const getMimeTypeFromExtension = (fileName: string): string => {
    const ext = fileName.split('.').pop()?.toLowerCase();
    const map: Record<string, string> = {
      'png': 'image/png', 'jpg': 'image/jpeg', 'jpeg': 'image/jpeg',
      'webp': 'image/webp', 'pdf': 'application/pdf', 'txt': 'text/plain',
      'pptx': 'application/vnd.openxmlformats-officedocument.presentationml.presentation'
    };
    return map[ext || ''] || 'application/octet-stream';
  };

  const handlePaste = (e: ClipboardEvent<HTMLInputElement>) => {
    const items = e.clipboardData.items;
    const filesToProcess: File[] = [];
    for (let i = 0; i < items.length; i++) {
      if (items[i].kind === 'file') {
        const file = items[i].getAsFile();
        if (file) filesToProcess.push(file);
      }
    }
    if (filesToProcess.length > 0) {
      processFiles(filesToProcess);
    }
  };

  const sendButtonText = mode === 'video' 
    ? '生成视频' 
    : (previews.length > 0 ? `发送附件(${previews.length})` : '发送');

  return (
    <div className="p-4 border-t border-slate-800 bg-slate-900/80 backdrop-blur-xl relative">
      <div className="max-w-4xl mx-auto flex flex-col gap-3">
        {isProcessing && (
          <div className="flex items-center gap-2 text-[10px] text-orange-400 font-bold animate-pulse px-2">
            <svg className="animate-spin h-3 w-3" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>
            正在深度解析文件结构...
          </div>
        )}

        {previews.length > 0 && (
          <div className="flex items-end gap-3 animate-in fade-in slide-in-from-bottom-2">
            <div className="flex-1 flex gap-2 overflow-x-auto pb-2 scrollbar-hide pt-2 px-1">
              {previews.map((preview) => (
                <div key={preview.id} className="relative flex-shrink-0 group">
                  <div className={`w-16 h-16 rounded-xl border border-slate-700/50 overflow-hidden flex flex-col items-center justify-center shadow-lg transition-transform group-hover:scale-105 ${preview.mimeType.includes('presentation') ? 'bg-orange-500/10' : preview.textContent ? 'bg-emerald-500/10' : 'bg-slate-800'}`}>
                    {preview.mimeType.includes('image') && preview.data ? (
                      <img src={`data:${preview.mimeType};base64,${preview.data}`} className="w-full h-full object-cover" alt="Preview" />
                    ) : (
                      <div className="flex flex-col items-center p-1 text-center">
                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 ${preview.mimeType.includes('presentation') ? 'text-orange-500' : preview.textContent ? 'text-emerald-400' : preview.mimeType.includes('pdf') ? 'text-red-400' : 'text-blue-400'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                        </svg>
                        <span className="text-[7px] text-slate-400 truncate max-w-[50px] mt-1 leading-tight">{preview.name}</span>
                      </div>
                    )}
                  </div>
                  <button 
                    onClick={() => setPreviews(p => p.filter(x => x.id !== preview.id))} 
                    className="absolute -top-2 -right-2 bg-rose-600 text-white rounded-full p-1 shadow-2xl scale-0 group-hover:scale-100 transition-all hover:bg-rose-500 z-10"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
                  </button>
                </div>
              ))}
            </div>
            <button onClick={() => setPreviews([])} className="mb-2 text-[10px] font-black text-rose-500/70 hover:text-rose-400 uppercase tracking-tighter shrink-0 transition-colors">移除全部 ({previews.length})</button>
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex gap-3 items-center">
          <input type="file" multiple className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && processFiles(e.target.files)} />
          <div className="flex bg-slate-800 rounded-xl p-1 border border-slate-700 shadow-inner">
            <button type="button" onClick={() => setMode('chat')} className={`p-2.5 rounded-lg transition-all ${mode === 'chat' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>
