export type Role = 'user' | 'assistant' | 'system';

export interface MessageMedia {
  data?: string; // Base64 for images
  mimeType: string;
  url?: string; // For generated video
  fileName?: string;
  textContent?: string; // For text-based documents
}

export interface Message {
  id: string;
  role: Role;
  content: string;
  timestamp: Date;
  mediaItems?: MessageMedia[];
  type?: 'text' | 'video_gen' | 'doc_analysis';
}

export interface ChatState {
  messages: Message[];
  isThinking: boolean;
  isGeneratingVideo: boolean;
  error: string | null;
}

import { GoogleGenAI, Modality } from "@google/genai";
import { Message, MessageMedia } from "../types";

const SUPPORTED_MIME_TYPES = [
  'image/png', 'image/jpeg', 'image/webp', 'image/heic', 'image/heif',
  'application/pdf'
];

const mapToContent = (messages: Message[]) => {
  return messages.map(msg => {
    const parts: any[] = [];
    let combinedText = msg.content || "";

    if (msg.mediaItems) {
      msg.mediaItems.forEach(item => {
        if (item.textContent) combinedText += `\n\n[File Content: ${item.fileName}]\n${item.textContent}\n`;
      });
    }

    if (combinedText.trim()) parts.push({ text: combinedText });

    if (msg.mediaItems) {
      msg.mediaItems.forEach(item => {
        if (item.data && SUPPORTED_MIME_TYPES.includes(item.mimeType)) {
          parts.push({ inlineData: { data: item.data, mimeType: item.mimeType } });
        }
      });
    }

    if (parts.length === 0) parts.push({ text: "..." });
    return { role: msg.role === 'user' ? 'user' : 'model', parts };
  });
};

export const sendMessageWithMedia = async (
  fullHistory: Message[],
  currentText: string,
  mediaItems?: MessageMedia[]
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const currentParts: any[] = [];
  let prompt = currentText;

  if (mediaItems) {
    mediaItems.forEach(item => {
      if (item.textContent) prompt += `\n\n[File Content: ${item.fileName}]\n${item.textContent}`;
      if (item.data && SUPPORTED_MIME_TYPES.includes(item.mimeType)) {
        currentParts.push({ inlineData: { data: item.data, mimeType: item.mimeType } });
      }
    });
  }

  currentParts.unshift({ text: prompt || "Analyze this content." });

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [
      ...mapToContent(fullHistory.slice(0, -1)),
      { role: 'user', parts: currentParts }
    ],
    config: {
      systemInstruction: "You are a helpful and intelligent AI assistant. Be concise and professional.",
    },
  });

  return response.text || "";
};

export const generateVideo = async (prompt: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  let operation = await ai.models.generateVideos({
    model: 'veo-3.1-fast-generate-preview',
    prompt: prompt,
    config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
  });
  while (!operation.done) {
    await new Promise(resolve => setTimeout(resolve, 10000));
    operation = await ai.operations.getVideosOperation({ operation: operation });
  }
  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  if (!downloadLink) throw new Error("Video link not found.");
  const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
  const blob = await response.blob();
  return URL.createObjectURL(blob);
};

import React, { useEffect, useRef } from 'react';
import { Message } from '../types';
import Markdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { atomDark } from 'react-syntax-highlighter/dist/esm/styles/prism';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  isGeneratingVideo: boolean;
  onDeleteMessage: (id: string) => void;
}

const MessageList: React.FC<MessageListProps> = ({ messages, isThinking, isGeneratingVideo, onDeleteMessage }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isThinking, isGeneratingVideo]);

  return (
    <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth">
      {messages.length === 0 && !isThinking && !isGeneratingVideo && (
        <div className="h-full flex flex-col items-center justify-center text-slate-500 space-y-4">
          <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-blue-600 to-indigo-600 flex items-center justify-center shadow-2xl">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
            </svg>
          </div>
          <h2 className="text-xl font-bold text-slate-200">Gemini AI Discovery</h2>
          <p className="text-sm text-slate-500 text-center max-w-sm">
