          </p>
        </div>
      )}

      {messages.map((msg) => (
        <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
          <div className={`relative max-w-[90%] md:max-w-[80%] rounded-2xl p-4 shadow-sm group ${msg.role === 'user' ? 'message-bubble-user text-white' : 'message-bubble-ai text-slate-100'}`}>
            <button 
              onClick={() => onDeleteMessage(msg.id)} 
