               <span className="text-[10px]">{msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
            </div>

            {msg.mediaItems && msg.mediaItems.length > 0 && (
              <div className="grid gap-2 mb-3 grid-cols-1">
                {msg.mediaItems.map((item, idx) => (
                  <div key={idx} className="rounded-lg overflow-hidden border border-white/10 shadow-md">
                    {item.mimeType.includes('image') && item.data ? (
                      <img src={`data:${item.mimeType};base64,${item.data}`} className="w-full max-h-64 object-contain bg-slate-900" alt="Attachment" />
                    ) : item.url && item.mimeType.includes('video') ? (
                      <video controls className="w-full bg-black" src={item.url} />
                    ) : (
                      <div className="flex items-center gap-3 p-3 bg-white/5">
                        <div className="p-2 rounded-lg bg-slate-800 text-blue-400">
                           <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
