import React, { useState, FormEvent, useRef, forwardRef, useImperativeHandle } from 'react';
import { MessageMedia } from '../types';

interface ChatInputProps {
  onSendMessage: (message: string, media?: MessageMedia[]) => void;
  onGenerateVideo: (prompt: string) => void;
  disabled: boolean;
}

const ChatInput = forwardRef((props: ChatInputProps, ref) => {
  const { onSendMessage, onGenerateVideo, disabled } = props;
  const [input, setInput] = useState('');
  const [mode, setMode] = useState<'chat' | 'video'>('chat');
  const [previews, setPreviews] = useState<(MessageMedia & { id: string; name: string })[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useImperativeHandle(ref, () => ({
    addFiles: (files: FileList | File[]) => {
      processFiles(files);
    },
    setInput: (text: string) => {
      setInput(text);
    }
  }));

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!input.trim() && previews.length === 0) return;

    if (mode === 'video') {
      onGenerateVideo(input.trim());
      setInput('');
    } else {
      onSendMessage(input.trim(), previews.length > 0 ? previews : undefined);
      setInput('');
      setPreviews([]);
    }
  };

  const processFiles = async (files: FileList | File[]) => {
    const newFiles = Array.from(files);
    for (const file of newFiles) {
      const id = Math.random().toString(36).substr(2, 9);
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64 = (reader.result as string).split(',')[1];
          setPreviews(prev => [...prev, { id, data: base64, mimeType: file.type, name: file.name, fileName: file.name }]);
        };
        reader.readAsDataURL(file);
      } else {
        const text = await file.text();
        setPreviews(prev => [...prev, { id, mimeType: file.type, name: file.name, fileName: file.name, textContent: text }]);
      }
    }
  };

  return (
    <div className="p-4 border-t border-slate-800 bg-slate-900/80 backdrop-blur-xl">
      <div className="max-w-4xl mx-auto flex flex-col gap-3">
        {previews.length > 0 && (
          <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
            {previews.map((preview) => (
              <div key={preview.id} className="relative group flex-shrink-0">
                <div className="w-16 h-16 rounded-lg bg-slate-800 border border-slate-700 overflow-hidden flex items-center justify-center">
                  {preview.data ? (
                    <img src={`data:${preview.mimeType};base64,${preview.data}`} className="w-full h-full object-cover" alt="Preview" />
                  ) : (
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-slate-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
                    </svg>
                  )}
                </div>
                <button 
                  onClick={() => setPreviews(p => p.filter(x => x.id !== preview.id))}
                  className="absolute -top-1 -right-1 bg-rose-600 text-white rounded-full p-0.5"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))}
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex gap-2">
          <input type="file" multiple className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && processFiles(e.target.files)} />
          <div className="flex bg-slate-800 rounded-xl p-1 border border-slate-700">
            <button type="button" onClick={() => setMode('chat')} className={`p-2 rounded-lg ${mode === 'chat' ? 'bg-blue-600 text-white' : 'text-slate-400'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
            </button>
            <button type="button" onClick={() => setMode('video')} className={`p-2 rounded-lg ${mode === 'video' ? 'bg-purple-600 text-white' : 'text-slate-400'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
            </button>
          </div>
          <button type="button" onClick={() => fileInputRef.current?.click()} className="p-3 bg-slate-800 text-slate-400 rounded-xl hover:text-white transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          </button>
          <input 
            type="text" 
            value={input} 
            onChange={(e) => setInput(e.target.value)} 
            placeholder={mode === 'video' ? "Describe a video..." : "Type a message..."}
            disabled={disabled}
            className="flex-1 bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500/50"
          />
          <button type="submit" disabled={(!input.trim() && previews.length === 0) || disabled} className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-3 rounded-xl font-bold transition-all disabled:opacity-50">
            Send
          </button>
        </form>
      </div>
    </div>
  );
});

export default ChatInput;

import React, { useState, useEffect, useRef } from 'react';
import { Message, ChatState, MessageMedia } from './types';
import { sendMessageWithMedia, generateVideo } from './services/geminiService';
import MessageList from './components/MessageList';
import ChatInput from './components/ChatInput';

const STORAGE_KEY = 'GEMINI_STABLE_CHAT_v1';

const App: React.FC = () => {
  const [state, setState] = useState<ChatState>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        return {
          messages: parsed.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
          isThinking: false,
          isGeneratingVideo: false,
          error: null
        };
      }
    } catch (e) { console.error("History restore failed", e); }
    return { messages: [], isThinking: false, isGeneratingVideo: false, error: null };
  });

  const chatInputRef = useRef<any>(null);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.messages));
  }, [state.messages]);

  const handleSendMessage = async (content: string, mediaItems?: MessageMedia[]) => {
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content, timestamp: new Date(), mediaItems };
    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isThinking: true }));

    try {
      const text = await sendMessageWithMedia([...state.messages, userMsg], content, mediaItems);
      const assistantMsg: Message = { id: (Date.now() + 1).toString(), role: 'assistant', content: text, timestamp: new Date() };
      setState(prev => ({ ...prev, messages: [...prev.messages, userMsg, assistantMsg], isThinking: false }));
    } catch (err: any) {
      setState(prev => ({ ...prev, isThinking: false, error: "Something went wrong. Check your connection." }));
      setTimeout(() => setState(p => ({ ...p, error: null })), 5000);
    }
  };

  const handleGenerateVideo = async (prompt: string) => {
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: `🎥 Video: ${prompt}`, timestamp: new Date() };
    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isGeneratingVideo: true }));

    try {
      const url = await generateVideo(prompt);
      const assistantMsg: Message = { 
        id: (Date.now() + 1).toString(), 
        role: 'assistant', 
        content: 'Generated video:', 
        timestamp: new Date(), 
        mediaItems: [{ url, mimeType: 'video/mp4' }] 
      };
      setState(prev => ({ ...prev, messages: [...prev.messages, userMsg, assistantMsg], isGeneratingVideo: false }));
    } catch (err: any) {
      setState(prev => ({ ...prev, isGeneratingVideo: false, error: "Video generation failed." }));
      setTimeout(() => setState(p => ({ ...p, error: null })), 5000);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-200">
      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-xl">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" viewBox="0 0 20 20" fill="currentColor"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg>
          </div>
          <h1 className="text-sm font-bold tracking-tight">GEMINI DISCOVERY</h1>
        </div>
        <button 
          onClick={() => { if(confirm('Clear all chat history?')) setState(prev => ({ ...prev, messages: [] })); }}
          className="p-2 text-slate-500 hover:text-rose-500 transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
        </button>
      </header>

      <MessageList 
        messages={state.messages} 
        isThinking={state.isThinking} 
        isGeneratingVideo={state.isGeneratingVideo}
        onDeleteMessage={(id) => setState(prev => ({ ...prev, messages: prev.messages.filter(m => m.id !== id) }))}
      />

      <ChatInput 
        ref={chatInputRef}
        onSendMessage={handleSendMessage} 
        onGenerateVideo={handleGenerateVideo}
        disabled={state.isThinking || state.isGeneratingVideo} 
