      {state.error && (
        <div className="fixed bottom-24 left-1/2 -translate-x-1/2 z-50 bg-rose-600 text-white px-4 py-2 rounded-full shadow-2xl text-xs font-bold animate-bounce">
          {state.error}
        </div>
      )}
    </div>
  );
};

