      const assistantMsg: Message = { 
        id: (Date.now() + 1).toString(), 
        role: 'assistant', 
        content: 'Generated video:', 
        timestamp: new Date(), 
        mediaItems: [{ url, mimeType: 'video/mp4' }] 
      };
      setState(prev => ({ ...prev, messages: [...prev.messages, userMsg, assistantMsg], isGeneratingVideo: false }));
    } catch (err: any) {
      setState(prev => ({ ...prev, isGeneratingVideo: false, error: "Video generation failed." }));
      setTimeout(() => setState(p => ({ ...p, error: null })), 5000);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-200">
      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-xl shrink-0">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center shadow-lg">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" viewBox="0 0 20 20" fill="currentColor"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg>
          </div>
          <div className="flex flex-col">
            <h1 className="text-xs font-black tracking-widest text-white leading-none">GEMINI DISCOVERY</h1>
            <span className="text-[9px] text-emerald-500 font-bold mt-1">v1.2 STABLE</span>
          </div>
        </div>

        {/* Storage Usage Visualizer */}
        <div className="hidden sm:flex items-center gap-4 bg-slate-800/40 px-4 py-1.5 rounded-full border border-slate-700/50">
           <div className="flex flex-col">
             <span className="text-[8px] uppercase font-bold text-slate-500 tracking-tighter">Memory Used</span>
             <div className="flex items-center gap-2">
                <div className="w-20 h-1 bg-slate-900 rounded-full overflow-hidden">
