import React, { useEffect, useRef } from 'react';
import { Message } from '../types';
import Markdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { atomDark } from 'react-syntax-highlighter/dist/esm/styles/prism';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  isGeneratingVideo: boolean;
  onDeleteMessage: (id: string) => void;
}

const MessageList: React.FC<MessageListProps> = ({ messages, isThinking, isGeneratingVideo, onDeleteMessage }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isThinking, isGeneratingVideo]);

  return (
    <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth">
      {messages.length === 0 && !isThinking && !isGeneratingVideo && (
        <div className="h-full flex flex-col items-center justify-center text-slate-500 space-y-4">
          <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-blue-600 to-indigo-600 flex items-center justify-center shadow-2xl">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
            </svg>
          </div>
          <h2 className="text-xl font-bold text-slate-200">Gemini AI Discovery</h2>
          <p className="text-sm text-slate-500 text-center max-w-sm">
            Stable version with manual storage management. Delete messages to save space.
          </p>
        </div>
      )}

      {messages.map((msg) => (
        <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
          <div className={`relative max-w-[90%] md:max-w-[80%] rounded-2xl p-4 shadow-sm group ${msg.role === 'user' ? 'message-bubble-user text-white' : 'message-bubble-ai text-slate-100'}`}>

            {/* Obvious Delete Button - Always Visible */}
            <button 
              onClick={() => onDeleteMessage(msg.id)} 
              className="absolute -top-2 -right-2 p-1.5 bg-rose-600 hover:bg-rose-500 text-white rounded-lg shadow-xl transition-all active:scale-90 z-10 border border-white/20"
              title="Delete this message to free space"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>

            <div className="flex items-center mb-2 gap-2 opacity-60">
               <span className="text-[10px] font-bold uppercase tracking-wider">{msg.role === 'user' ? 'YOU' : 'GEMINI'}</span>
               <span className="text-[10px]">{msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
            </div>

            {msg.mediaItems && msg.mediaItems.length > 0 && (
              <div className="grid gap-2 mb-3 grid-cols-1">
                {msg.mediaItems.map((item, idx) => (
                  <div key={idx} className="rounded-lg overflow-hidden border border-white/10 shadow-md">
                    {item.mimeType.includes('image') && item.data ? (
                      <img src={`data:${item.mimeType};base64,${item.data}`} className="w-full max-h-64 object-contain bg-slate-900" alt="Attachment" />
                    ) : item.url && item.mimeType.includes('video') ? (
                      <video controls className="w-full bg-black" src={item.url} />
                    ) : (
                      <div className="flex items-center gap-3 p-3 bg-white/5">
                        <div className="p-2 rounded-lg bg-slate-800 text-blue-400">
                           <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                        </div>
                        <span className="text-xs truncate text-slate-300">{item.fileName}</span>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}

            <div className="markdown-content text-sm md:text-[15px] leading-relaxed">
              <Markdown remarkPlugins={[remarkGfm]} components={{
                code({node, inline, className, children, ...props}: any) {
                  const match = /language-(\w+)/.exec(className || '');
                  return !inline && match ? (
                    <SyntaxHighlighter style={atomDark} language={match[1]} PreTag="div" {...props}>
                      {String(children).replace(/\n$/, '')}
                    </SyntaxHighlighter>
                  ) : <code className={`${className} bg-slate-950/50 px-1 rounded text-blue-300 font-mono text-xs`} {...props}>{children}</code>;
                }
              }}>{msg.content}</Markdown>
            </div>
          </div>
        </div>
      ))}

      {(isThinking || isGeneratingVideo) && (
        <div className="flex justify-start">
          <div className="message-bubble-ai text-slate-100 p-4 rounded-2xl flex items-center gap-2 animate-pulse">
            <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce"></div>
            <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce [animation-delay:-.3s]"></div>
            <div className="w-2 h-2 bg-blue-400 rounded-full animate-bounce [animation-delay:-.5s]"></div>
            <span className="text-xs text-slate-400 ml-2">{isGeneratingVideo ? 'Generating Video...' : 'Thinking...'}</span>
          </div>
        </div>
      )}
    </div>
  );
};

export default MessageList;

import React, { useState, FormEvent, useRef, forwardRef, useImperativeHandle, ClipboardEvent } from 'react';
import { MessageMedia } from '../types';

interface ChatInputProps {
  onSendMessage: (message: string, media?: MessageMedia[]) => void;
  onGenerateVideo: (prompt: string) => void;
  disabled: boolean;
}

const ChatInput = forwardRef((props: ChatInputProps, ref) => {
  const { onSendMessage, onGenerateVideo, disabled } = props;
  const [input, setInput] = useState('');
  const [mode, setMode] = useState<'chat' | 'video'>('chat');
  const [previews, setPreviews] = useState<(MessageMedia & { id: string; name: string })[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useImperativeHandle(ref, () => ({
    addFiles: (files: FileList | File[]) => {
      processFiles(files);
    },
    setInput: (text: string) => {
      setInput(text);
    }
  }));

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!input.trim() && previews.length === 0) return;

    if (mode === 'video') {
      onGenerateVideo(input.trim());
      setInput('');
    } else {
      onSendMessage(input.trim(), previews.length > 0 ? previews : undefined);
      setInput('');
      setPreviews([]);
    }
  };

  const processFiles = async (files: FileList | File[]) => {
    const newFiles = Array.from(files);
    for (const file of newFiles) {
      const id = Math.random().toString(36).substr(2, 9);
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64 = (reader.result as string).split(',')[1];
          setPreviews(prev => [...prev, { id, data: base64, mimeType: file.type, name: file.name, fileName: file.name }]);
        };
        reader.readAsDataURL(file);
      } else {
        // Handle text-based documents
        try {
          const text = await file.text();
          setPreviews(prev => [...prev, { id, mimeType: file.type, name: file.name, fileName: file.name, textContent: text }]);
        } catch (err) {
          console.error("Could not read file as text", err);
        }
      }
    }
  };

  const handlePaste = (e: ClipboardEvent<HTMLInputElement>) => {
    const items = e.clipboardData?.items;
    if (!items) return;

    const files: File[] = [];
    for (let i = 0; i < items.length; i++) {
      const file = items[i].getAsFile();
      if (file) {
        files.push(file);
      }
    }

    if (files.length > 0) {
      // If files are pasted, process them and prevent default if it's purely files
      processFiles(files);
      // We don't preventDefault here because the user might be pasting text AND a file
    }
  };

  return (
    <div className="p-4 border-t border-slate-800 bg-slate-900/80 backdrop-blur-xl">
      <div className="max-w-4xl mx-auto flex flex-col gap-3">
        {previews.length > 0 && (
          <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
            {previews.map((preview) => (
              <div key={preview.id} className="relative group flex-shrink-0">
                <div className="w-16 h-16 rounded-lg bg-slate-800 border border-slate-700 overflow-hidden flex items-center justify-center">
                  {preview.data ? (
                    <img src={`data:${preview.mimeType};base64,${preview.data}`} className="w-full h-full object-cover" alt="Preview" />
                  ) : (
                    <div className="flex flex-col items-center justify-center p-1">
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-blue-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
                      </svg>
                      <span className="text-[8px] text-slate-500 truncate w-12 text-center">{preview.name}</span>
                    </div>
                  )}
                </div>
                <button 
                  onClick={() => setPreviews(p => p.filter(x => x.id !== preview.id))}
                  className="absolute -top-1 -right-1 bg-rose-600 text-white rounded-full p-0.5 shadow-lg hover:bg-rose-500 transition-colors"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))}
          </div>
        )}

        <form onSubmit={handleSubmit} className="flex gap-2">
          <input type="file" multiple className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && processFiles(e.target.files)} />
          <div className="flex bg-slate-800 rounded-xl p-1 border border-slate-700">
            <button type="button" onClick={() => setMode('chat')} className={`p-2 rounded-lg transition-all ${mode === 'chat' ? 'bg-blue-600 text-white shadow-inner' : 'text-slate-500 hover:text-slate-300'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
            </button>
            <button type="button" onClick={() => setMode('video')} className={`p-2 rounded-lg transition-all ${mode === 'video' ? 'bg-purple-600 text-white shadow-inner' : 'text-slate-500 hover:text-slate-300'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z" /></svg>
            </button>
          </div>
          <button type="button" onClick={() => fileInputRef.current?.click()} className="p-3 bg-slate-800 text-slate-400 rounded-xl hover:text-white hover:bg-slate-700 transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          </button>
          <input 
            type="text" 
            value={input} 
            onChange={(e) => setInput(e.target.value)}
            onPaste={handlePaste}
            placeholder={mode === 'video' ? "Describe a video..." : "Type or paste images/files..."}
            disabled={disabled}
            className="flex-1 bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500/50 placeholder:text-slate-600 transition-all"
          />
          <button type="submit" disabled={(!input.trim() && previews.length === 0) || disabled} className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-3 rounded-xl font-bold transition-all disabled:opacity-50 shadow-lg active:scale-95">
            {disabled ? '...' : 'Send'}
          </button>
        </form>
      </div>
    </div>
  );
});

export default ChatInput;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Message, ChatState, MessageMedia } from './types';
import { sendMessageWithMedia, generateVideo } from './services/geminiService';
import MessageList from './components/MessageList';
import ChatInput from './components/ChatInput';

const STORAGE_KEY = 'GEMINI_STABLE_CHAT_v1';
const MAX_STORAGE_BYTES = 5 * 1024 * 1024; // 5MB standard limit

const App: React.FC = () => {
  const [state, setState] = useState<ChatState>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        return {
          messages: parsed.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
          isThinking: false,
          isGeneratingVideo: false,
          error: null
        };
      }
    } catch (e) { console.error("History restore failed", e); }
    return { messages: [], isThinking: false, isGeneratingVideo: false, error: null };
  });

  const chatInputRef = useRef<any>(null);

  const storageUsage = useMemo(() => {
    try {
      const str = JSON.stringify(state.messages);
      const bytes = new Blob([str]).size;
      return Math.min(100, Math.round((bytes / MAX_STORAGE_BYTES) * 100));
    } catch (e) { return 0; }
  }, [state.messages]);

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state.messages));
    } catch (e) {
      if (String(e).includes("QuotaExceededError")) {
        setState(prev => ({ ...prev, error: "Storage Full! Please delete some messages." }));
      }
    }
  }, [state.messages]);

  const handleSendMessage = async (content: string, mediaItems?: MessageMedia[]) => {
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content, timestamp: new Date(), mediaItems };
    // First, add only the user message
    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isThinking: true }));

    try {
      const text = await sendMessageWithMedia([...state.messages, userMsg], content, mediaItems);
      const assistantMsg: Message = { id: (Date.now() + 1).toString(), role: 'assistant', content: text, timestamp: new Date() };
      // SUCCESS: Only append the assistant message, do not re-add userMsg
      setState(prev => ({ ...prev, messages: [...prev.messages, assistantMsg], isThinking: false }));
    } catch (err: any) {
      setState(prev => ({ ...prev, isThinking: false, error: "Something went wrong. Check your connection." }));
      setTimeout(() => setState(p => ({ ...p, error: null })), 5000);
    }
  };

  const handleGenerateVideo = async (prompt: string) => {
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: `🎥 Video: ${prompt}`, timestamp: new Date() };
    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isGeneratingVideo: true }));

    try {
      const url = await generateVideo(prompt);
      const assistantMsg: Message = { 
        id: (Date.now() + 1).toString(), 
        role: 'assistant', 
        content: 'Generated video:', 
        timestamp: new Date(), 
        mediaItems: [{ url, mimeType: 'video/mp4' }] 
      };
      setState(prev => ({ ...prev, messages: [...prev.messages, assistantMsg], isGeneratingVideo: false }));
    } catch (err: any) {
      setState(prev => ({ ...prev, isGeneratingVideo: false, error: "Video generation failed." }));
      setTimeout(() => setState(p => ({ ...p, error: null })), 5000);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-200">
      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-xl shrink-0">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center shadow-lg">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" viewBox="0 0 20 20" fill="currentColor"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg>
          </div>
          <div className="flex flex-col">
            <h1 className="text-xs font-black tracking-widest text-white leading-none">GEMINI DISCOVERY</h1>
            <span className="text-[9px] text-emerald-500 font-bold mt-1">v1.2 STABLE</span>
          </div>
        </div>

        <div className="hidden sm:flex items-center gap-4 bg-slate-800/40 px-4 py-1.5 rounded-full border border-slate-700/50">
           <div className="flex flex-col">
             <span className="text-[8px] uppercase font-bold text-slate-500 tracking-tighter">Memory Used</span>
             <div className="flex items-center gap-2">
                <div className="w-20 h-1 bg-slate-900 rounded-full overflow-hidden">
                  <div 
                    className={`h-full transition-all duration-1000 ${storageUsage > 80 ? 'bg-rose-500 animate-pulse' : 'bg-blue-500'}`}
                    style={{ width: `${storageUsage}%` }}
                  ></div>
                </div>
                <span className={`text-[10px] font-mono font-bold ${storageUsage > 80 ? 'text-rose-400' : 'text-slate-400'}`}>
                  {storageUsage}%
                </span>
             </div>
           </div>
        </div>

        <button 
          onClick={() => { if(confirm('Clear all chat history?')) setState(prev => ({ ...prev, messages: [] })); }}
          className="p-2 text-slate-500 hover:text-rose-500 transition-colors"
          title="Clear History"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
        </button>
      </header>

      <MessageList 
        messages={state.messages} 
        isThinking={state.isThinking} 
        isGeneratingVideo={state.isGeneratingVideo}
        onDeleteMessage={(id) => setState(prev => ({ ...prev, messages: prev.messages.filter(m => m.id !== id) }))}
      />

      <ChatInput 
        ref={chatInputRef}
        onSendMessage={handleSendMessage} 
        onGenerateVideo={handleGenerateVideo}
        disabled={state.isThinking || state.isGeneratingVideo} 
      />

      {state.error && (
        <div className="fixed bottom-24 left-1/2 -translate-x-1/2 z-50 bg-rose-600 text-white px-4 py-2 rounded-full shadow-2xl text-xs font-bold animate-bounce">
          {state.error}
        </div>
      )}
    </div>
  );
};

export default App;

