            <div className="markdown-content text-sm md:text-[15px] leading-relaxed">
              <Markdown remarkPlugins={[remarkGfm]} components={{
                code({node, inline, className, children, ...props}: any) {
                  const match = /language-(\w+)/.exec(className || '');
                  return !inline && match ? (
                    <SyntaxHighlighter style={atomDark} language={match[1]} PreTag="div" {...props}>
                      {String(children).replace(/\n$/, '')}
                    </SyntaxHighlighter>
                  ) : <code className={`${className} bg-slate-950/50 px-1 rounded text-blue-300 font-mono text-xs`} {...props}>{children}</code>;
                }
              }}>{msg.content}</Markdown>
            </div>
          </div>
        </div>
      ))}

      {(isThinking || isGeneratingVideo) && (
        <div className="flex justify-start">
          <div className="message-bubble-ai text-slate-100 p-4 rounded-2xl flex items-center gap-2 animate-pulse border border-white/5 bg-slate-800/50">
            <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></div>
            <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:-.3s]"></div>
            <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:-.5s]"></div>
            <span className="text-xs text-slate-400 ml-2 font-medium">{isGeneratingVideo ? 'Creating Magic Video...' : 'Gemini is thinking...'}</span>
          </div>
        </div>
      )}
    </div>
  );
};

export default MessageList;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { Message, ChatState, MessageMedia } from './types';
import { sendMessageWithMedia, generateVideo } from './services/geminiService';
import MessageList from './components/MessageList';
import ChatInput from './components/ChatInput';

const STORAGE_KEY = 'GEMINI_STABLE_CHAT_v2'; // Bump version to ensure clean start if needed
const MAX_STORAGE_BYTES = 5 * 1024 * 1024; // 5MB

const App: React.FC = () => {
  const [state, setState] = useState<ChatState>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          return {
            messages: parsed.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) })),
            isThinking: false,
            isGeneratingVideo: false,
            error: null
          };
        }
      }
    } catch (e) {
      console.error("History restore failed", e);
    }
    return { messages: [], isThinking: false, isGeneratingVideo: false, error: null };
  });

  const chatInputRef = useRef<any>(null);

  // Sync with LocalStorage whenever messages change
  useEffect(() => {
    try {
      const data = JSON.stringify(state.messages);
      localStorage.setItem(STORAGE_KEY, data);
    } catch (e) {
      if (String(e).includes("QuotaExceededError")) {
        setState(prev => ({ ...prev, error: "Storage Full! Please use the red bin to delete large files/messages." }));
      }
    }
  }, [state.messages]);

  const storageUsage = useMemo(() => {
    try {
      const str = JSON.stringify(state.messages);
      const bytes = new Blob([str]).size;
      return Math.min(100, Math.round((bytes / MAX_STORAGE_BYTES) * 100));
    } catch (e) { return 0; }
  }, [state.messages]);

  const handleSendMessage = useCallback(async (content: string, mediaItems?: MessageMedia[]) => {
    if (state.isThinking) return;

    const userMsg: Message = { 
      id: `u-${Date.now()}`, 
      role: 'user', 
      content, 
      timestamp: new Date(), 
      mediaItems 
    };

    // 1. Add user message locally
    setState(prev => ({ 
      ...prev, 
      messages: [...prev.messages, userMsg], 
      isThinking: true,
      error: null 
    }));

    try {
      // 2. We use a snapshot of history to send to API to avoid race conditions
      // Note: We include the NEW user message in this snapshot
      const historySnapshot = [...state.messages, userMsg];
      const aiResponse = await sendMessageWithMedia(historySnapshot, content, mediaItems);

      const assistantMsg: Message = { 
        id: `a-${Date.now()}`, 
        role: 'assistant', 
        content: aiResponse, 
        timestamp: new Date() 
      };

      // 3. Append ONLY the assistant response
      setState(prev => ({ 
        ...prev, 
        messages: [...prev.messages, assistantMsg], 
        isThinking: false 
      }));
    } catch (err: any) {
      console.error("AI Error:", err);
      setState(prev => ({ 
        ...prev, 
        isThinking: false, 
        error: "Connection lost. Please try again." 
      }));
      setTimeout(() => setState(p => ({ ...p, error: null })), 5000);
    }
  }, [state.isThinking, state.messages]);

  const handleGenerateVideo = useCallback(async (prompt: string) => {
    if (state.isGeneratingVideo) return;

    const userMsg: Message = { 
      id: `u-v-${Date.now()}`, 
      role: 'user', 
      content: `🎥 Video Request: ${prompt}`, 
      timestamp: new Date() 
    };

    setState(prev => ({ ...prev, messages: [...prev.messages, userMsg], isGeneratingVideo: true }));

    try {
      const url = await generateVideo(prompt);
      const assistantMsg: Message = { 
        id: `a-v-${Date.now()}`, 
        role: 'assistant', 
        content: 'I have generated the video for you:', 
        timestamp: new Date(), 
        mediaItems: [{ url, mimeType: 'video/mp4' }] 
      };
      setState(prev => ({ ...prev, messages: [...prev.messages, assistantMsg], isGeneratingVideo: false }));
    } catch (err: any) {
      setState(prev => ({ ...prev, isGeneratingVideo: false, error: "Video generation failed." }));
    }
  }, [state.isGeneratingVideo, state.messages]);

  const deleteMessage = (id: string) => {
    setState(prev => ({
      ...prev,
      messages: prev.messages.filter(m => m.id !== id)
    }));
  };

  return (
    <div className="flex flex-col h-screen bg-[#020617] text-slate-200">
      <header className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-xl shrink-0 z-50">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center shadow-lg shadow-blue-500/20">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" viewBox="0 0 20 20" fill="currentColor"><path d="M2 5a2 2 0 012-2h7a2 2 0 012 2v4a2 2 0 01-2 2H9l-3 3v-3H4a2 2 0 01-2-2V5z" /></svg>
          </div>
          <div className="flex flex-col">
            <h1 className="text-[10px] font-black tracking-[0.2em] text-white leading-none">GEMINI PRO</h1>
            <span className="text-[9px] text-emerald-500 font-bold mt-1 uppercase tracking-tighter">Memory Guard Active</span>
          </div>
        </div>

        <div className="flex items-center gap-6">
          <div className="hidden md:flex flex-col items-end">
             <span className="text-[8px] uppercase font-bold text-slate-500 tracking-widest">Storage Status</span>
             <div className="flex items-center gap-3">
                <div className="w-32 h-1.5 bg-slate-800 rounded-full overflow-hidden border border-slate-700">
                  <div 
                    className={`h-full transition-all duration-700 ${storageUsage > 85 ? 'bg-rose-500 animate-pulse' : 'bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.5)]'}`}
                    style={{ width: `${storageUsage}%` }}
                  ></div>
                </div>
                <span className={`text-[10px] font-mono font-bold ${storageUsage > 85 ? 'text-rose-400' : 'text-slate-400'}`}>
                  {storageUsage}%
                </span>
             </div>
          </div>

          <button 
            onClick={() => { if(confirm('Wipe all history?')) setState(prev => ({ ...prev, messages: [] })); }}
            className="p-2.5 rounded-xl bg-slate-800/50 text-slate-400 hover:text-rose-500 hover:bg-rose-500/10 transition-all border border-slate-700/50"
            title="Wipe Session"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
          </button>
        </div>
      </header>

      <MessageList 
        messages={state.messages} 
        isThinking={state.isThinking} 
        isGeneratingVideo={state.isGeneratingVideo}
        onDeleteMessage={deleteMessage}
      />

      <ChatInput 
        ref={chatInputRef}
        onSendMessage={handleSendMessage} 
        onGenerateVideo={handleGenerateVideo}
        disabled={state.isThinking || state.isGeneratingVideo} 
      />

      {state.error && (
        <div className="fixed bottom-24 left-1/2 -translate-x-1/2 z-[100] bg-rose-600/90 backdrop-blur-md text-white px-6 py-3 rounded-2xl shadow-2xl text-xs font-bold animate-in slide-in-from-bottom-4 border border-rose-500">
          <div className="flex items-center gap-2">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" /></svg>
            {state.error}
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';
import { Message } from '../types';
import Markdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { atomDark } from 'react-syntax-highlighter/dist/esm/styles/prism';

interface MessageListProps {
  messages: Message[];
  isThinking: boolean;
  isGeneratingVideo: boolean;
  onDeleteMessage: (id: string) => void;
}

const MessageList: React.FC<MessageListProps> = ({ messages, isThinking, isGeneratingVideo, onDeleteMessage }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isThinking, isGeneratingVideo]);

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  return (
    <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-8 scroll-smooth pb-12">
      {messages.length === 0 && !isThinking && !isGeneratingVideo && (
        <div className="h-full flex flex-col items-center justify-center text-slate-500 space-y-6">
          <div className="relative">
            <div className="absolute inset-0 bg-blue-500 blur-3xl opacity-20"></div>
            <div className="relative w-24 h-24 rounded-3xl bg-slate-900 border border-slate-800 flex items-center justify-center shadow-2xl">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
              </svg>
            </div>
          </div>
          <div className="text-center space-y-2">
            <h2 className="text-xl font-bold text-slate-200">History Guard v1.2</h2>
            <p className="text-sm text-slate-500 max-w-xs mx-auto">
              Your messages are saved locally. Hover over any message to see the <span className="text-rose-500 font-bold underline">red trash bin</span> and clear space.
            </p>
          </div>
        </div>
      )}

      {messages.map((msg) => (
        <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-4 duration-500`}>
          <div className="relative group max-w-[90%] md:max-w-[80%]">

            {/* ACTION KNOBS - Floating control bar */}
            <div className={`absolute -top-4 ${msg.role === 'user' ? 'right-0' : 'left-0'} flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all duration-300 translate-y-2 group-hover:translate-y-0 z-10`}>
               {/* Copy Button */}
               <button 
                onClick={() => copyToClipboard(msg.content)}
                className="w-8 h-8 rounded-full bg-slate-800 border border-slate-700 flex items-center justify-center text-slate-400 hover:text-white hover:bg-slate-700 shadow-xl"
                title="Copy text"
               >
                 <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" /></svg>
               </button>

               {/* THE RED TRASH BIN - Physical deletion */}
               <button 
                onClick={() => onDeleteMessage(msg.id)}
                className="w-8 h-8 rounded-full bg-rose-600 border border-rose-500 flex items-center justify-center text-white hover:bg-rose-500 shadow-xl hover:scale-110 active:scale-95 transition-all"
                title="Delete from memory"
               >
                 <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
               </button>
            </div>

            <div className={`p-4 rounded-2xl shadow-2xl transition-all border ${msg.role === 'user' ? 'message-bubble-user border-blue-400/20' : 'message-bubble-ai border-white/5'}`}>
              <div className="flex items-center mb-3 gap-2 opacity-40">
                <span className="text-[9px] font-black tracking-widest uppercase">{msg.role === 'user' ? 'Master' : 'Gemini'}</span>
                <span className="w-1 h-1 bg-slate-500 rounded-full"></span>
                <span className="text-[9px]">{msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
              </div>

              {msg.mediaItems && msg.mediaItems.length > 0 && (
                <div className="grid gap-3 mb-4 grid-cols-1">
                  {msg.mediaItems.map((item, idx) => (
                    <div key={idx} className="rounded-xl overflow-hidden border border-white/10 bg-slate-900/40 backdrop-blur-sm group/media">
                      {item.mimeType.includes('image') && item.data ? (
                        <img src={`data:${item.mimeType};base64,${item.data}`} className="w-full max-h-[400px] object-contain" alt="Attached" />
                      ) : item.url && item.mimeType.includes('video') ? (
                        <video controls className="w-full bg-black aspect-video" src={item.url} />
                      ) : (
                        <div className="flex items-center gap-4 p-4">
                          <div className="w-10 h-10 rounded-lg bg-blue-500/20 text-blue-400 flex items-center justify-center">
                             <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                          </div>
                          <div className="flex flex-col">
                            <span className="text-xs font-bold text-slate-200 truncate max-w-[200px]">{item.fileName}</span>
                            <span className="text-[10px] text-slate-500 uppercase">{item.mimeType.split('/')[1]} Document</span>
                          </div>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              )}

              <div className="markdown-content text-[15px] leading-relaxed text-slate-100">
                <Markdown remarkPlugins={[remarkGfm]} components={{
                  code({node, inline, className, children, ...props}: any) {
                    const match = /language-(\w+)/.exec(className || '');
                    return !inline && match ? (
                      <div className="relative group/code mt-4 mb-4">
                        <SyntaxHighlighter style={atomDark} language={match[1]} PreTag="div" className="!bg-slate-950 !p-4 !rounded-xl !border !border-white/5" {...props}>
                          {String(children).replace(/\n$/, '')}
                        </SyntaxHighlighter>
                      </div>
                    ) : <code className="bg-slate-900 px-1.5 py-0.5 rounded text-blue-400 font-mono text-[13px]" {...props}>{children}</code>;
                  }
                }}>{msg.content}</Markdown>
              </div>
            </div>
          </div>
        </div>
      ))}

      {(isThinking || isGeneratingVideo) && (
        <div className="flex justify-start animate-in fade-in duration-500">
          <div className="bg-slate-800/40 backdrop-blur-md p-5 rounded-2xl border border-white/5 flex items-center gap-4">
            <div className="flex gap-1.5">
              <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
              <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
              <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce"></div>
            </div>
            <span className="text-[11px] font-bold text-slate-400 tracking-widest uppercase">
              {isGeneratingVideo ? 'Synthesizing Neural Frames...' : 'Processing Request...'}
            </span>
          </div>
        </div>
      )}
    </div>
  );
};

export default MessageList;
